//3 copy end
////////////////////////////////////////////////////////////////////////
////// Strength/Stress Load Case for Civil : AASHTO-Standard2K /////////
////////////////////////////////////////////////////////////////////////
void CLoadCombCtrl::Set_CvlAASHTOStr1_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
																				ArINT& arIlLoad, ArINT& arCrlLoad, ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad,
																				ArINT& arBLoad, ArINT& arSfLoad, ArINT& arCSLoad)
{
    if(m_nConstLoad==0 && m_nCfCount==0 && m_nEhCount==0 && m_nEvCount==0 && m_nBCount==0 && m_nSfCount==0) return;
    
    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=2.171, dIlFactor=2.171, dCrlFactor=2.171, dCfFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if(m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFix;
    strDFactor.Format(_T("%.3f"),  dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);
    int nMCount = max(m_nMCount, 1);
    for(int j=0; j<nMCount; j++)
    {
        strFix.Format(_T("%d"), j+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        CString csPrefix = _T("");  
		
        int n=0, i=0, nDL=0, nLL=0, nIL=0, nCRL=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);                  
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);        
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
    			 
			CString strcEL;
			int nErection = 0;
			 
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
		
        rData.Description = _T("Group I :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0) { rData.Description += csPrefix + _T("2.171M[") + strFix + _T("]");  csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("2.171L"); csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("2.171IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("2.171CF"); csPrefix = _T("+");}
        }
        if(nCRL> 0) {rData.Description += csPrefix + _T("2.171CRL");  csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");  csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)");  csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL;  csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("2.171(cEL)");  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr1A_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                                                                 ArINT& arIlLoad, ArINT& arCrlLoad, ArINT& arCSLoad)
{
    if(m_nDCount==0 && m_nMCount==0 && m_nLCount==0 && m_nCrlCount==0) return;
    
    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=2.86, dCrlFactor=2.86;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    CString strDFactor, strFix;
    strDFactor.Format(_T("%.3f"), dDFactor);
    
    int nMCount = max(m_nMCount, 1);
    for(int j=0; j<nMCount; j++)
    {
        strFix.Format(_T("%d"), j+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        CString csPrefix = _T("");  

        int n=0, i=0, nDL=0, nLL=0, nIL=0, nCRL=0;
        for(i=0; i<m_nDCount; i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount > 0)  
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
             
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group IA :");  
        if(nDL > 0) { rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0) { rData.Description += csPrefix + _T("2.86M[") + strFix + _T("]");  csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("2.86L"); csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("2.86IL"); csPrefix = _T("+");}
        }
        if(nCRL> 0) { rData.Description += csPrefix + _T("2.86CRL"); csPrefix = _T("+");} 
        if(m_nConstLoad!=0) // Prestress
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("2.86(cEL)"); csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr1B(CString strCode, ArINT& arDLoad, ArINT& arLpLoad, ArINT& arCrlLoad, ArINT& arIlpLoad, 
                 ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad, ArINT& arBLoad, ArINT& arSfLoad, ArINT& arCSLoad)
{
    if(m_nLpCount==0) return;
    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3,dLpFactor=1.3,dCrlFactor=1.3,dIlpFactor=1.3,dCfFactor=1.3,dEhFactor=1.69,dEvFactor=1.3,dBFactor=1.3,dSfFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strEvFactor;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);
    strEvFactor.Format(_T("%.3f"), dEvFactor);

    CString csPrefix = _T("");
    rData.Initialize();  
    LoadCaseNo = 0;  

    int n=0, i=0, nDL=0, nLP=0, nCRL=0, nILP=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0;
    for(i=0; i<m_nDCount;  i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
    for(i=0; i<m_nLpCount; i++) nLP += Set_STLCIncludeCS(arLpLoad.GetAt(i), dLpFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nCrlCount;i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
    for(i=0; i<m_nIlpCount;i++) nILP+= Set_STLCIncludeCS(arIlpLoad.GetAt(i),dIlpFactor,LoadCaseNo, rData, 0);
    for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nBCount;  i++) nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
    for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
    if(m_nConstLoad!=0)
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
        
		CString strcEL;
		int nErection = 0;
		
		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
        }
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
    }
    
    rData.Description = _T("Group IB :");  
    if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}
    if(nLP > 0) {rData.Description += csPrefix + _T("1.3LP");  csPrefix = _T("+");}
    if(nCRL> 0) {rData.Description += csPrefix + _T("1.3CRL"); csPrefix = _T("+");}
    if(nILP> 0) {rData.Description += csPrefix + _T("1.3ILP"); csPrefix = _T("+");}
    if(nCF > 0) {rData.Description += csPrefix + _T("1.3CF");  csPrefix = _T("+");}           
    if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH"); csPrefix = _T("+");} 
    if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
    if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
    if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}

    if(m_nConstLoad!=0)
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
        {rData.Description += csPrefix + strDFactor + _T("(cD)");  csPrefix = _T("+");}
        		 
		CString strcEL;
		int nErection = 0;
				
		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
            {rData.Description += csPrefix + strDFactor + strcEL;  csPrefix = _T("+");}
        }
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
        {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
    }
    if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
}

void CLoadCombCtrl::Set_CvlAASHTOStr2(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arCSLoad)
{
    if(m_nWCount==0) return;

    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3,dEhFactor=1.69,dEvFactor=1.3,dBFactor=1.3,dSfFactor=1.3,dWFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFixW;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    for(int j = 0; j < m_nWCount*2; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixW.Format(_T("%d"), j/2+1);

        int n=0, i=0, nDL=0, nWL=0, nEH=0, nEV=0, nBL=0, nSF=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
        nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group II :");  
        if(nDL > 0) { rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nWL > 0) { if(dWF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nEH > 0) { rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) { rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) { rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) { rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}

        if(m_nConstLoad!=0) // ST only
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            { rData.Description += csPrefix + strDFactor + _T("(cD)");  csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + strDFactor + strcEL;  csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                { rData.Description += csPrefix + _T("1.3(cEL)");  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
                                     
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr3_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                            ArINT& arIlLoad,ArINT& arCrlLoad, ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad,
                                            ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arWlLoad, ArINT& arBkLoad,
                                            ArINT& arCSLoad)
{
    if((m_nWCount==0 && m_nBkCount==0) || 
         (m_nWCount > 0 && m_nWlCount==0 && m_nBkCount==0 && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 &&
            m_nCfCount==0 && m_nConstLoad==0)) return;

    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dCrlFactor=1.3, dCfFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3;
    double dWFactor=0.39, dWlFactor=1.3, dBkFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if(m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFix, strFixW, strFixWL;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nWLCount = (m_nWlCount>0) ? m_nWlCount*2 : 1;
    int nMCount = max(m_nMCount, 1);
    
    for(int j=0; j<nMCount; j++) {
	for(int k=0; k<nWCount; k++) {
	for(int l=0; l<nWLCount; l++)
    {
        strFix.Format(_T("%d"), j+1);
        strFixW.Format(_T("%d"), k/2+1);
		strFixWL.Format(_T("%d"), l/2+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        CString csPrefix = _T("");
        int n=0, i=0, nDL=0, nLL=0, nIL=0, nCRL=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0, nWL=0, nWLL=0, nBK=0;;
        for(i=0; i<m_nDCount; i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount> 0)  
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++)  nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++)  nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        double dWF = (k%2==0) ? dWFactor : -1.*dWFactor;
        if(m_nWCount > 0)            nWL += Set_STLCIncludeCS(arWLoad.GetAt(k/2), dWF, LoadCaseNo, rData, 0);
		double dWLF = (l%2==0) ? dWlFactor : -1.*dWlFactor;
        if(m_nWlCount > 0)           nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(l/2), dWLF, LoadCaseNo, rData, 0);
        //for(i=0; i<m_nWlCount; i++)  nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i), dWlFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBkCount; i++)  nBK += Set_STLCIncludeCS(arBkLoad.GetAt(i), dBkFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
				 Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            			
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group III :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0) {rData.Description += csPrefix + _T("1.3M[") + strFix + _T("]");  csPrefix = _T("+");}     
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("1.3L");  csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("1.3IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("1.3CF"); csPrefix = _T("+");}
        }
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nCRL> 0) {rData.Description += csPrefix + _T("1.3CRL"); csPrefix = _T("+");}     
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
		if(nWLL > 0) {if(dWLF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWLF)+_T("WL[") + strFixWL + _T("]"); csPrefix = _T("+");}
        //if(nWLL> 0) {rData.Description += csPrefix + _T("1.3WL");  csPrefix = _T("+");}
        if(nBK > 0) {rData.Description += csPrefix + _T("1.3BK");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("1.3(cEL)"); csPrefix = _T("+");}  
                else if(CheckCSEL(nErection, _T("W")))
                {rData.Description += csPrefix + _T("0.39(cEL)"); csPrefix = _T("+");}  
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
}}}}
    
void CLoadCombCtrl::Set_CvlAASHTOStr4_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                            ArINT& arIlLoad,ArINT& arCrlLoad, ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad,
                                            ArINT& arBLoad, ArINT& arSfLoad, ArINT& arRsLoad, ArINT& arShLoad, ArINT& arTLoad,
                                            ArINT& arTpgLoad, ArINT& arCSLoad)
{
    if(m_nConstLoad==0 && m_nRsCount==0 && m_nShCount==0 && m_nTCount==0 && m_nTpgCount==0) return;

    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dCrlFactor=1.3, dCfFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3;
    double dRsFactor=1.3, dShFactor=1.3, dTFactor=1.3, dTpgFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFix, strFixT, strFixTpg;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);
    int nTCountTemp, nTpgCountTemp;
    nTCountTemp = max(m_nTCount, 1);
    nTpgCountTemp = max(m_nTpgCount, 1);

    int nMCount = max(m_nMCount, 1);
    for(int j=0; j<nMCount;     j++) {
    for(int l=0; l<nTCountTemp; l++) {
    for(int m=0; m<nTpgCountTemp; m++)
    {
        CString csPrefix = _T("");
        strFix.Format(_T("%d"), j+1);
        strFixT.Format(_T("%d"), l+1);
        strFixTpg.Format(_T("%d"), m+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        int n=0, i=0, nDL=0, nLL=0, nIL=0, nCRL=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0, nRS=0, nSH=0, nTL=0, nTPG=0;
        for(i=0; i<m_nDCount; i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount > 0)  
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++)  nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++)  nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nRsCount; i++)  nRS += Set_STLCIncludeCS(arRsLoad.GetAt(i), dRsFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nShCount; i++)  nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor, LoadCaseNo, rData, 10);
        if(m_nTCount > 0)            nTL += Set_STLCIncludeCS(arTLoad.GetAt(l),  dTFactor,  LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)          nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor,LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTpgFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dShFactor, LoadCaseNo, rData, TRUE);
        }
        rData.Description = _T("Group IV :");
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0) {rData.Description += csPrefix + _T("1.3M[") + strFix + _T("]");  csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("1.3L");  csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("1.3IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("1.3CF"); csPrefix = _T("+");}
        }
        if(nCRL> 0) {rData.Description += csPrefix + _T("1.3CRL"); csPrefix = _T("+");}
        if(nTL > 0) {rData.Description += csPrefix + _T("1.3T[") + strFixT + _T("]"); csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + _T("1.3TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + _T("1.3SH");  csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(nRS > 0) {rData.Description += csPrefix + _T("1.3RS");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)");  csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL;  csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")) || CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("1.3(cEL)");  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            {rData.Description += csPrefix + _T("1.3(cSH)");  csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
}}}}


void CLoadCombCtrl::Set_CvlAASHTOStr5(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arRsLoad, ArINT& arShLoad, ArINT& arTLoad, 
                 ArINT& arTpgLoad, ArINT& arCSLoad)
{  
    if(m_nWCount==0 || (m_nConstLoad==0 && m_nRsCount==0 && m_nShCount==0 && m_nTCount==0 && m_nTpgCount==0)) return;

    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.25, dEhFactor=1.625, dEvFactor=1.25, dBFactor=1.25, dSfFactor=1.25, dWFactor=1.25;
    double dRsFactor=1.25, dShFactor=1.25, dTFactor=1.25, dTpgFactor=1.25;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.9375;  
    if(m_nStrEpType == 1) dEhFactor = 1.4375;
    else if(m_nStrEpType == 2) dEhFactor = 0.625;
    else if(m_nStrEpType == 3) dEhFactor = 1.25;
    else if(m_nStrEpType == 3) dEhFactor = 1.875;
    CString strDFactor, strEhFactor, strFixW, strFixT, strFixTpg;
    strDFactor.Format(_T("%.4f"), dDFactor);
    strEhFactor.Format(_T("%.4f"), dEhFactor);  

    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nTCount = max(m_nTCount, 1);
    int nTpgCount = max(m_nTpgCount, 1);

    for(int j = 0; j < nWCount; j++) {
    for(int l = 0; l < nTCount; l++) {
    for(int m = 0; m < nTpgCount; m++)
    {
        CString csPrefix = _T("");
        strFixW.Format(_T("%d"), j/2+1);
        strFixT.Format(_T("%d"), l+1);    
        strFixTpg.Format(_T("%d"), m+1);    
        rData.Initialize();  
        LoadCaseNo = 0;

        int n=0, i=0, nDL=0, nTL=0, nTPG=0, nSH=0, nEH=0, nEV=0, nBL=0, nSF=0, nWL=0, nRS=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nTCount > 0)           nTL += Set_STLCIncludeCS(arTLoad.GetAt(l),  dTFactor,  LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)         nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nShCount; i++) nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor, LoadCaseNo, rData, D_SGLD_SS_CVL);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        double dWF = (j%2==0) ? dWFactor : -1.* dWFactor;
        if(m_nWCount>0)             nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2),  dWF,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nRsCount; i++) nRS += Set_STLCIncludeCS(arRsLoad.GetAt(i), dRsFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTpgFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dShFactor, LoadCaseNo, rData, TRUE);
        }
    
        rData.Description = _T("Group V :");
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nTL > 0) {rData.Description += csPrefix + _T("1.25T[") + strFixT + _T("]"); csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + _T("1.25TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + _T("1.25SH");  csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.25EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.25B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.25SF");  csPrefix = _T("+");}
        if(nRS > 0) {rData.Description += csPrefix + _T("1.25RS");  csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
                else if(CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")) || CheckCSEL(nErection, _T("W")))
                {rData.Description += csPrefix + _T("1.25(cEL)");  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            {rData.Description += csPrefix + _T("1.25(cSH)");  csPrefix = _T("+");}
        }
        
        if(LoadCaseNo > 0)   Set_LoadComb4Civil(rData, D_STR); 
}}}}

void CLoadCombCtrl::Set_CvlAASHTOStr6_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                            ArINT& arIlLoad,ArINT& arCrlLoad, ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad,
                                            ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arWlLoad, ArINT& arBkLoad,
                                            ArINT& arRsLoad, ArINT& arShLoad, ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad)
{
    if(m_nConstLoad==0 && ((m_nWCount==0 && m_nBkCount==0) || 
         (m_nWCount > 0 && m_nWlCount==0 && m_nBkCount==0 && m_nLCount==0 && m_nMCount==0 && m_nCrlCount==0 && m_nCfCount==0))) return;
    if(m_nConstLoad==0 && m_nRsCount==0 && m_nShCount==0 && m_nTCount==0 && m_nTpgCount==0) return;

    int LoadCaseNo;
    T_LCOM_D rData;
    double dDFactor=1.25, dMFactor=1.25, dCrlFactor=1.25, dCfFactor=1.25, dEhFactor=1.625, dEvFactor=1.25, dBFactor=1.25; 
    double dSfFactor=1.25, dWFactor=0.375, dWlFactor= 1.25, dBkFactor=1.25, dRsFactor=1.25, dShFactor=1.25;
    double dTFactor=1.25, dTpgFactor=1.25;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.9375;  
    if     (m_nStrEpType == 1) dEhFactor = 1.4375;
    else if(m_nStrEpType == 2) dEhFactor = 0.625;
    else if(m_nStrEpType == 3) dEhFactor = 1.25;
    else if(m_nStrEpType == 3) dEhFactor = 1.875;
    CString strDFactor, strEhFactor, strFix, strFixW, strFixWL, strFixT, strFixTpg;
    strDFactor.Format(_T("%.4f"), dDFactor);
    strEhFactor.Format(_T("%.4f"), dEhFactor);  

    int nWCount   = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nWLCount   = (m_nWlCount>0) ? m_nWlCount*2 : 1;
    int nTCount   = max(m_nTCount,  1);
    int nTpgCount = max(m_nTpgCount,1);
    int nMCount   = max(m_nMCount,  1);
    
    for(int k = 0; k < nMCount; k++) {
    for(int j = 0; j < nWCount; j++) {
	for(int n = 0; n < nWLCount; n++) {
    for(int l = 0; l < nTCount; l++) {
    for(int m = 0; m < nTpgCount; m++)
    {
        CString csPrefix = _T("");
        strFix.Format(_T("%d"), k+1);
        strFixW.Format(_T("%d"), j/2+1);
		strFixWL.Format(_T("%d"), n/2+1);
        strFixT.Format(_T("%d"), l+1);    
        strFixTpg.Format(_T("%d"), m+1);    
        rData.Initialize();  
        LoadCaseNo = 0;
        int i=0, nDL=0, nLL=0, nIL=0, nCRL=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0, nWL=0, nWLL=0, nBK=0, nRS=0, nSH=0, nTL=0, nTPG=0;
        for(i=0; i<m_nDCount; i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(k), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount > 0)  
        {
            for(i=0; i<m_nLCount;  i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++)  nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++)  nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
        if(m_nWCount > 0)            nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2),  dWF,  LoadCaseNo, rData, 0);
		double dWLF = (n%2==0) ? dWlFactor : -1.*dWlFactor;
        if(m_nWlCount > 0)           nWLL += Set_STLCIncludeCS(arWlLoad.GetAt(n/2),  dWLF,  LoadCaseNo, rData, 0);
        //for(i=0; i<m_nWlCount; i++)  nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i), dWlFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBkCount; i++)  nBK += Set_STLCIncludeCS(arBkLoad.GetAt(i), dBkFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nRsCount; i++)  nRS += Set_STLCIncludeCS(arRsLoad.GetAt(i), dRsFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nShCount; i++)  nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor, LoadCaseNo, rData, D_SGLD_SS_CVL);
        if(m_nTCount > 0)            nTL += Set_STLCIncludeCS(arTLoad.GetAt(l),  dTFactor,  LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)          nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor,LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0)
        {
            int nnn = 0;
            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; } 
				             
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dTpgFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn), dPSS, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn), dShFactor, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group VI :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0) {rData.Description += csPrefix + _T("1.25M[") + strFix + _T("]");  csPrefix = _T("+");}     
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("1.25L"); csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("1.25IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("1.25CF"); csPrefix = _T("+");}
        }
        if(nTL > 0) {rData.Description += csPrefix + _T("1.25T[") + strFixT + _T("]"); csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + _T("1.25TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + _T("1.25SH");  csPrefix = _T("+");}
        if(nCRL> 0) {rData.Description += csPrefix + _T("1.25CRL"); csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.25EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.25B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.25SF");  csPrefix = _T("+");}
		if(nWLL > 0) {if(dWLF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWLF)+_T("WL[") + strFixWL + _T("]"); csPrefix = _T("+");}
        //if(nWLL> 0) {rData.Description += csPrefix + _T("1.25WL");  csPrefix = _T("+");}
        if(nBK > 0) {rData.Description += csPrefix + _T("1.25BK");  csPrefix = _T("+");}
        if(nRS > 0) {rData.Description += csPrefix + _T("1.25RS");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            int nnn = 0;
            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
                else if(CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")) || CheckCSEL(nErection, _T("W")) || CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("1.25(cEL)"); csPrefix = _T("+");}  
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
            {rData.Description += csPrefix + _T("1.25(cSH)"); csPrefix = _T("+");}  
        }
    
        if(LoadCaseNo > 0)   Set_LoadComb4Civil(rData, D_STR); 
}}}}}}

void CLoadCombCtrl::Set_CvlAASHTOStr7(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArINT& arELoad, ArINT& arCSLoad)
{
    if(m_nECount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3, dEFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if(m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFixE;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    for(int j = 0; j < m_nECount*2; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixE.Format(_T("%d"), j/2+1);

        int n=0, i=0, nDL=0, nEL=0, nEH=0, nEV=0, nBL=0, nSF=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        double dEF = (j%2==0) ? dEFactor : -1.*dEFactor;
        nEL += Set_STLCIncludeCS(arELoad.GetAt(j/2), dEF, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("E")))
                    Set_CStageCase(arCSLoad.GetAt(n), dEFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group VII :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nEL > 0) {if(dEF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dEF)+_T("E[") + strFixE + _T("]"); csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            { rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+"); }
			 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+"); }
                else if(CheckCSEL(nErection, _T("E")))
                { rData.Description += csPrefix + _T("1.3(cEL)"); csPrefix = _T("+"); }
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr7S(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArUNT& arEspLoad, ArINT& arCSLoad)
{
    if(m_nEspCount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3, dEFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFixE;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    for(int j = 0; j < m_nEspCount*2; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixE.Format(_T("%d"), j/2+1);
        double dScaleUpFactor=1.0;
        Get_ScaleUpFactor(D_LOADCASE_SPECTRUM, arEspLoad.GetAt(j/2), dScaleUpFactor);

        int n=0, i=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        double dEF = (j%2==0) ? dEFactor*dScaleUpFactor : -1.*dEFactor*dScaleUpFactor;
        Set_SpectrumCase(arEspLoad.GetAt(j/2), dEF, LoadCaseNo, rData, TRUE);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group VII :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(dEF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dEF)+_T("ESP[") + strFixE + _T("]"); csPrefix = _T("+");
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
            		 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 

                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}


void CLoadCombCtrl::Set_CvlAASHTOStr7_CNS91(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, ArINT& arBLoad, 
                 ArINT& arSfLoad, ArINT& arELoad, ArINT& arCSLoad)
{
    if(m_nECount==0) return;
    int n=0;

    int LoadCaseNo = 0;
    T_LCOM_D rData;
    double dDFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3, dEFactor=1.3;
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strDFactor, strEhFactor, strFixE;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    double dEFactor_x = 1.3, dEFactor_y = 1.3*0.3;
    CString csPrefix = _T("");
    rData.Initialize(); 
    LoadCaseNo = 0;

    int i=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0;
    for(i=0; i<m_nDCount;  i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
    for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
    for(i=0; i<m_nBCount;  i++) nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
    for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);  
    if(m_nConstLoad!=0)
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
		 
		CString strcEL;
		int nErection = 0;
				
		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			 
			 
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            else if(CheckCSEL(nErection, _T("E")))
                Set_CStageCase(arCSLoad.GetAt(n), dEFactor, LoadCaseNo, rData, TRUE);
        }
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
    }
    rData.Description = _T("Group VII :");
    if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D");   csPrefix = _T("+"); }
    if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH"); csPrefix = _T("+"); }
    if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");            csPrefix = _T("+"); }
    if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");             csPrefix = _T("+"); }
    if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");            csPrefix = _T("+"); }
    if(m_nConstLoad!=0)
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
        {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+"); }
		 
		CString strcEL;
		int nErection = 0;
				
		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			 
			 
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
            {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+"); }
            else if(CheckCSEL(nErection, _T("E")))
            {rData.Description += csPrefix + _T("1.3(cEL)"); csPrefix = _T("+");}
        }
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
        {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
    }

    if(m_nECount == 1)
    {
        int nEL = Set_STLCIncludeCS(arELoad.GetAt(0), dEFactor, LoadCaseNo, rData, 0);
        if(nEL>0) {rData.Description += csPrefix + _T("1.3E"); csPrefix = _T("+");}
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
    else
    {
        for(int j=0; j<m_nECount; j++)
        {
            T_LCOM_D LcomD_e = rData;
            BOOL bAddE = TRUE;
            int nEL=0;
            CString strE = csPrefix + _T("1.3(");
            for(int k=0; k<m_nECount; k++)
            {
                if(k==j)
                {
                    nEL = Set_STLCIncludeCS(arELoad.GetAt(k), dEFactor_x, LoadCaseNo, LcomD_e, 0);
                    if(nEL==0) { bAddE = FALSE; break; }
                    strFixE.Format(_T("1.0E[%d]"), k+1);
                }
                else
                {
                    nEL = Set_STLCIncludeCS(arELoad.GetAt(k), dEFactor_y, LoadCaseNo, LcomD_e, 0);
                    strFixE.Format(_T("0.3E[%d]"), k+1);
                }
                if(j==0) strE += strFixE;
                else     strE += csPrefix + strFixE;
            }
            strE += _T(")");
            if(bAddE && LoadCaseNo>0)
            {
                LcomD_e.Description = strE;
                Set_LoadComb4Civil(LcomD_e, D_STR); 
            }
        }
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr7S_CNS91(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, ArINT& arBLoad, 
                 ArINT& arSfLoad, ArUNT& arEspLoad_x, ArUNT& arEspLoad_y, ArUNT& arEspLoad_z, ArINT& arCSLoad)
{
    if(m_nEspCount==0) return;

    int nEsp_x = arEspLoad_x.GetSize();
    int nEsp_y = arEspLoad_y.GetSize();
    int nEsp_z = arEspLoad_z.GetSize();
    int j=0, k=0, l=0;

    int LoadCaseNo = 0;
    T_LCOM_D rData;
    double dDFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if     (m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFixE;
    strDFactor.Format(_T("%.3f"), dDFactor);  
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    double  dEFactor = 1.3;
    double  dEF_x=1.3, dEF_y=1.3*0.3, dEF_z=1.3*0.3;
    CString strEF_x=_T("1.0"), strEF_y=_T("0.3"), strEF_z=_T("0.3");
    CString strOrd_x, strOrd_y, strOrd_z;
    int nFlag=1;
    CString csPrefix = _T("");

    int nCount = 0;
    ArUNT arESP; arESP.RemoveAll();
    if     (nEsp_x<1 && nEsp_y<1) { nCount = nEsp_z; arESP.Copy(arEspLoad_z); goto GT_GN_COMB; }
    else if(nEsp_y<1 && nEsp_z<1) { nCount = nEsp_x; arESP.Copy(arEspLoad_x); goto GT_GN_COMB; }
    else if(nEsp_x<1 && nEsp_z<1) { nCount = nEsp_y; arESP.Copy(arEspLoad_y); goto GT_GN_COMB; }

    if(nEsp_x<1) nEsp_x = 1;
    if(nEsp_y<1) nEsp_y = 1;

GT_TW_COMBINED:
    for(j=0; j<nEsp_x; j++)
    {
        strOrd_x.Format(_T("%d"), j+1);
        for(k=0; k<nEsp_y; k++)
        {
            strOrd_y.Format(_T("%d"), k+1);
            for(l=0; l<nEsp_z; l++)
            {
                strOrd_z.Format(_T("%d"), l+1);
                CString csPrefix = _T("");
                rData.Initialize(); 
                LoadCaseNo = 0;
                int i=0, n=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0;
                for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
                for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
                for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
                if(arEspLoad_x.GetSize()>0) Set_SpectrumCase(arEspLoad_x.GetAt(j), dEF_x, LoadCaseNo, rData, TRUE);
                if(arEspLoad_y.GetSize()>0) Set_SpectrumCase(arEspLoad_y.GetAt(k), dEF_y, LoadCaseNo, rData, TRUE);
                if(arEspLoad_z.GetSize()>0) Set_SpectrumCase(arEspLoad_z.GetAt(l), dEF_z, LoadCaseNo, rData, TRUE);
                if(m_nConstLoad!=0)
                {
                    if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                        Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
					 
					CString strcEL;
					int nErection = 0;
										
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
						 
						 
                    
                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                            Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                    }
                    if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                        Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
                }

                rData.Description = _T("Group VII :");  
                if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
                if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
                if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
                if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
                if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
                rData.Description += csPrefix + _T("1.3("); csPrefix = _T("");
                if(arEspLoad_x.GetSize()>0) { rData.Description += csPrefix + strEF_x + _T("ESP_x[") + strOrd_x + _T("]"); csPrefix = _T("+"); }
                else csPrefix = _T("");
                if(arEspLoad_y.GetSize()>0) { rData.Description += csPrefix + strEF_y + _T("ESP_y[") + strOrd_y + _T("]"); csPrefix = _T("+"); }
                else csPrefix = _T("");
                if(arEspLoad_z.GetSize()>0) { rData.Description += csPrefix + strEF_z + _T("ESP_z[") + strOrd_z + _T("]"); csPrefix = _T("+"); }
                rData.Description += _T(")");
                if(m_nConstLoad!=0)
                {
                    if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
					 
					CString strcEL;
					int nErection = 0;
										
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
						 
						 
                    
                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
                    }
                    if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
                }

                if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
            }
        }
    }
    if(nFlag<3)
    {
        nFlag++;
        if(nFlag==2)
        {
            dEF_x = 1.3*0.3; dEF_y = 1.3;     dEF_z = 1.3*0.3;
            strEF_x = _T("0.3"); strEF_y = _T("1.0"); strEF_z = _T("0.3");
        }
        else if(nFlag==3)
        {
            dEF_x = 1.3*0.3; dEF_y = 1.3*0.3; dEF_z = 1.3;
            strEF_x = _T("0.3"); strEF_y = _T("0.3"); strEF_z = _T("1.0");
        }

        goto GT_TW_COMBINED;
    }
    else return;

GT_GN_COMB:
    for(j = 0; j < nCount; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixE.Format(_T("%d"), j+1);
        int i=0, n=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        Set_SpectrumCase(arESP.GetAt(j), dEFactor, LoadCaseNo, rData, TRUE);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
    
        rData.Description = _T("Group VII :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(nCount == 1) {rData.Description += csPrefix + _T("1.3ESP"); csPrefix = _T("+");}
        else            {rData.Description += csPrefix + _T("1.3ESP[") + strFixE + _T("]"); csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}  
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}  
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }

}

void CLoadCombCtrl::Set_CvlAASHTOStr8_M(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                            ArINT& arIlLoad,ArINT& arCrlLoad, ArINT& arCfLoad, ArINT& arEhLoad, ArINT& arEvLoad,
                                            ArINT& arBLoad, ArINT& arSfLoad, ArINT& arIpLoad, ArINT& arCSLoad)
{
    if(m_nIpCount==0) return;

    int LoadCaseNo = 0;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dCrlFactor=1.3, dCfFactor=1.3, dEhFactor=1.69, dEvFactor=1.3, dBFactor=1.3, dSfFactor=1.3, dIpFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.975;  
    if(m_nStrEpType == 1) dEhFactor = 1.495;
    else if(m_nStrEpType == 2) dEhFactor = 0.65;
    else if(m_nStrEpType == 3) dEhFactor = 1.3;
    else if(m_nStrEpType == 4) dEhFactor = 1.95;
    CString strDFactor, strEhFactor, strFix;
    strDFactor.Format(_T("%.3f"), dDFactor);
    strEhFactor.Format(_T("%.3f"), dEhFactor);

    int nMCount = max(m_nMCount, 1);
    for(int j=0; j<nMCount; j++)
    {
        strFix.Format(_T("%d"), j+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        CString csPrefix = _T("");  
        int n=0, i=0, nDL=0, nLL=0, nIL=0, nCRL=0, nCF=0, nEH=0, nEV=0, nBL=0, nSF=0, nIP=0;
        for(i=0; i<m_nDCount; i++)   nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);                  
        if(m_nLCount > 0)  
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++)  nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++)  nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nIpCount; i++)  nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
    
        rData.Description = _T("Group VIII :");  
        if(nDL > 0)   {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(m_nMCount>0){rData.Description += csPrefix + _T("1.3M[") + strFix + _T("]");  csPrefix = _T("+");}
        if(m_nLCount > 0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("1.3L");  csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + _T("1.3IL"); csPrefix = _T("+");}
        }  
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("1.3CF"); csPrefix = _T("+");}
        }
        if(nCRL> 0)   {rData.Description += csPrefix + _T("1.3CRL"); csPrefix = _T("+");}
        if(nEH > 0)   {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0)   {rData.Description += csPrefix + _T("1.3EV");  csPrefix = _T("+");} 
        if(nBL > 0)   {rData.Description += csPrefix + _T("1.3B");   csPrefix = _T("+");}
        if(nSF > 0)   {rData.Description += csPrefix + _T("1.3SF");  csPrefix = _T("+");}
        if(nIP > 0)   {rData.Description += csPrefix + _T("1.3IP");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + _T("1.3(cEL)"); csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlAASHTOStr9(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arIpLoad, ArINT& arCSLoad)
{
    if(m_nIpCount==0) return;

    int LoadCaseNo = 0;
    T_LCOM_D rData;
    double dDFactor=1.2, dEhFactor=1.56, dEvFactor=1.2, dBFactor=1.2, dSfFactor=1.2, dWFactor=1.2, dIpFactor=1.2;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    if(m_nStrDlType == 0) dDFactor = 0.9;  
    if(m_nStrEpType == 1) dEhFactor = 1.38;
    else if(m_nStrEpType == 2) dEhFactor = 0.6;
    else if(m_nStrEpType == 3) dEhFactor = 1.2;
    else if(m_nStrEpType == 3) dEhFactor = 1.8;
    CString strDFactor, strEhFactor, strFixW;
    strDFactor.Format(_T("%.1f"), dDFactor);
    strEhFactor.Format(_T("%.2f"), dEhFactor);  
    int nWCountTemp;
    nWCountTemp = (m_nWCount>0) ? m_nWCount*2 : 1;

    for(int j = 0; j < nWCountTemp; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixW.Format(_T("%d"), j/2+1);
        int n=0, i=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0, nWL=0, nIP=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        double dWF = (j%2==0) ? dWFactor : -1.*dWFactor;
        if(m_nWCount > 0)           nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nIpCount; i++) nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i), dIpFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group IX :");  
        if(nDL > 0) {rData.Description += csPrefix + strDFactor + _T("D"); csPrefix = _T("+");}  
        if(nEH > 0) {rData.Description += csPrefix + strEhFactor + _T("EH");    csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("1.2EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("1.2B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("1.2SF");  csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nIP > 0) {rData.Description += csPrefix + _T("1.2IP");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + strDFactor + _T("(cD)"); csPrefix = _T("+");}
            			 
			CString strcEL;
			int nErection = 0;
						
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strDFactor + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                {rData.Description += csPrefix + _T("1.2(cEL)"); csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

