        double dEF = (j%2==0) ? dFactor : -1.*dFactor;
        nEL += Set_STLCIncludeCS(arELoad.GetAt(j/2), dEF, LoadCaseNo, rData, 0);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactor,  LoadCaseNo, rData, 0);
