        if(nEL > 0) {if(dEF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dEF)+_T("E[") + strFixE + _T("]"); csPrefix = _T("+");}
        if(nEH > 0) {rData.Description += csPrefix + _T("EH"); csPrefix = _T("+");} 
