                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("E")))
                {rData.Description += csPrefix + strcEL;  csPrefix = _T("+");}  
