void CLoadCombCtrl::Set_CvlAASHTOSer9(CString strCode, ArINT& arDLoad, ArINT& arEhLoad, ArINT& arEvLoad, 
                 ArINT& arBLoad, ArINT& arSfLoad, ArINT& arWLoad, ArINT& arIpLoad, ArINT& arCSLoad)
{
    if(m_nIpCount==0) return;

    int LoadCaseNo = 0;
    T_LCOM_D rData;
    double dFactor=1.0, dEhFactor=1.0, dEvFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixW;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;

    for(int j = 0; j < nWCount; j++)
    {
        CString csPrefix = _T("");
        rData.Initialize(); 
        LoadCaseNo = 0;
        strFixW.Format(_T("%d"), j/2+1);
        int i=0, n=0, nDL=0, nEH=0, nEV=0, nBL=0, nSF=0, nWL=0, nIP=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEhCount; i++) nEH += Set_STLCIncludeCS(arEhLoad.GetAt(i), dEhFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nEvCount; i++) nEV += Set_STLCIncludeCS(arEvLoad.GetAt(i), dEvFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dFactor,  LoadCaseNo, rData, 0);
        double dWF = (j%2==0) ? dFactor : -1.*dFactor;
        if(m_nWCount > 0)           nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2),  dWF,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nIpCount; i++) nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i), dFactor,  LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("Group IX :");  
        if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}  
        if(nEH > 0) {rData.Description += csPrefix + _T("EH");  csPrefix = _T("+");} 
        if(nEV > 0) {rData.Description += csPrefix + _T("EV");  csPrefix = _T("+");} 
        if(nBL > 0) {rData.Description += csPrefix + _T("B");   csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("SF");  csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
        if(nIP > 0) {rData.Description += csPrefix + _T("IP");  csPrefix = _T("+");}
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}  
            			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("W")))
                {rData.Description += csPrefix + strcEL; csPrefix = _T("+");}  
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0)
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL) rData.nActive = 2;
            Set_LoadComb4Civil(rData, D_SER);
        }
    }
}

