////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////
////// Strength/Stress Load Case for Civil : JTJ021-89, CJJ77-98 ///////
////////////////////////////////////////////////////////////////////////
void CLoadCombCtrl::Set_CvlChStrType1M(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArUNT& arMLoad,  
                 ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arCSLoad)
{
    if(m_nConstLoad==0 && m_nDCount==0  && m_nEpCount==0 && m_nLCount==0 && m_nMCount==0 && m_nIlCount==0 && 
         m_nCfCount==0   && m_nLsCount==0 &&  m_nCrlCount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.2, dEpFactor=1.2, dMFactor=1.4, dCfFactor=1.4, dLsFactor=1.4, dCrlFactor=1.4;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    
    // DL는 항상포함, CF, LS는 M가 있는 경우만 포함
    for(int kk = 0; kk < 2; kk++)
    {
        if(kk == 1) {dDFactor = 0.9, dEpFactor = 0.9;}
        int nMCount = max(m_nMCount, 1);
        for(int j=0; j<nMCount; j++)
        {
            strFix.Format(_T("%d"), j+1);
            rData.Initialize();  
            LoadCaseNo = 0;
            CString csPrefix = _T("");
            int i=0, nDL=0, nLL=0, nIL=0, nEP=0, nCF=0, nLS=0, nCRL=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
            BOOL bMoving = FALSE;
            if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(j))) || !m_bMovingSkip;
            if(bMoving) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);              
            if(m_nLCount>0)  
            {
                for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);        
                for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
            }
            if(bMoving || m_nLCount>0)
            {
                for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nLsCount; i++) nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dLsFactor, LoadCaseNo, rData, 0);
            }
            for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                    else if(CheckCSEL(nErection, _T("L")))
                        Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            }
    
            rData.Description = _T("");
            CString csDeadF = kk==0 ? _T("1.2") : _T("0.9");
            if(nDL > 0) {rData.Description += csPrefix + csDeadF + _T("D");   csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + csDeadF + _T("EP");  csPrefix = _T("+");}
            if(bMoving) {rData.Description += csPrefix + _T("1.4M[") + strFix + _T("]");  csPrefix = _T("+");}     
            if(m_nLCount>0)
            {
                if(nLL > 0) {rData.Description += csPrefix + _T("1.4L");  csPrefix = _T("+");}
                if(nIL > 0) {rData.Description += csPrefix + _T("1.4IL"); csPrefix = _T("+");}
            }
            if(bMoving || m_nLCount>0)
            {
                if(nCF > 0) {rData.Description += csPrefix + _T("1.4CF");  csPrefix = _T("+");}    
                if(nLS > 0) {rData.Description += csPrefix + _T("1.4LS"); csPrefix = _T("+");}
            }
            if(nCRL> 0) {rData.Description += csPrefix + _T("1.4CRL"); csPrefix = _T("+");}
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                {rData.Description += csPrefix + csDeadF + _T("(cD)"); csPrefix = _T("+");}
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    { rData.Description += csPrefix + csDeadF + strcEL; csPrefix = _T("+"); }
                    else if(CheckCSEL(nErection, _T("L")))
                    { rData.Description += csPrefix + _T("1.4(cEL)"); csPrefix = _T("+"); }
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            }
            if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);   
        }
    }
} 

void CLoadCombCtrl::Set_CvlChStrType2M(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArUNT& arMLoad,  
                 ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arWLoad,
                 ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arBrkLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad,
                 ArINT& arWprLoad, ArINT& arIpLoad, ArINT& arFrLoad, ArINT& arShLoad, ArINT& arCrLoad, ArINT& arStlLoad,
                 ArUNT& arSmLoad, ArINT& arBLoad, ArINT& arCSLoad)  
{
    if(m_nConstLoad==0 && m_nWCount==0 && m_nTCount==0 && m_nTpgCount==0 && m_nBrkCount==0 && m_nWpCount==0 &&
         m_nFpCount==0 && m_nSfCount==0 && m_nWprCount==0 && m_nFrCount==0 && m_nIpCount==0 && m_nWpCount==0 &&
         m_nFpCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nStlCount==0 && m_nSmCount==0 && m_nBCount==0) return;
 
    int LoadCaseNo = 0, c=0;
    T_LCOM_D rData;
    double dFactorA=1.1, dFactorB=1.3, dFactorBrk=1.3;  
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    
    int nWCount   = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount  = max(m_nSmCount, 1);
    int nTCount   = max(m_nTCount,  1);
    int nTpgCount = max(m_nTpgCount,1);
    CString strFixM, strFixW, strFixSm, strFixT, strFixTpg;
    // 동시에 하중조합에 참여하지 않는 기타가변하중을 고려하기 위한 변수 설정
    BOOL bFlagBrk = FALSE;
    BOOL bFlagWp = FALSE;
    BOOL bFlagIp = FALSE;
    BOOL bFlagNone = FALSE;
    if(m_nBrkCount > 0) bFlagBrk = TRUE;    // BRK가 있을 경우
    if(m_nIpCount > 0)  bFlagIp = TRUE;     // IP가 있을 경우
    if(m_nWpCount + m_nFpCount + m_nSfCount + m_nWprCount > 0) bFlagWp = TRUE; // WP, FP, SF, WPR이 있을 경우    
    if(!bFlagBrk && !bFlagWp && !bFlagIp) bFlagNone = TRUE;
    // 커브교일때 이심력과 제동력 조합시  제동력은 70%로 계산한다.
    if(m_bCurvedBridge && m_nBrkCount > 0 && m_nCfCount > 0) dFactorBrk = 1.3 * 0.7; 
    
    for(int kk = 0; kk < 2; kk++)
    {
        if(kk == 1) dFactorA = 0.8;
        for(int nVType = 0; nVType < 4; nVType++){
        if((nVType == 0 && bFlagBrk) || (nVType == 1 && bFlagWp) || (nVType == 2 && bFlagIp) || (nVType == 3 && bFlagNone))
        {
            int nMCount = max(m_nMCount, 1);
            for(int n = 0; n < nMCount; n++) {
            for(int j = 0; j < nWCount; j++)  {
            for(int k = 0; k < nSmCount; k++) {
            for(int l = 0; l < nTCount; l++)  {
            for(int m = 0; m < nTpgCount; m++){
            strFixM.Format(_T("%d"), n+1);
            strFixW.Format(_T("%d"), j/2+1);
            strFixSm.Format(_T("%d"), k+1);
            strFixT.Format(_T("%d"), l+1);
            strFixTpg.Format(_T("%d"), m+1);
            rData.Initialize();
            LoadCaseNo = 0;
            int i=0, nDL=0, nLL=0, nIL=0, nEP=0, nCF=0, nLS=0, nCRL=0, nWL=0, nTL=0, nTPG=0, nBRK=0, nWP=0, nFP=0;
            int nSF=0, nWPR=0, nFR=0, nIP=0, nCR=0, nSH=0, nSTL=0, nBL=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactorA, LoadCaseNo, rData, D_SGLD_DL_CVL);
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactorA, LoadCaseNo, rData, 0);
            BOOL bMoving = FALSE;
            if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(n))) || !m_bMovingSkip;
            if(bMoving) Set_MovingCase(arMLoad.GetAt(n),  dFactorB, LoadCaseNo, rData, TRUE);
            if(m_nLCount>0)
            {
                for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
            }
            if(bMoving || m_nLCount>0)
            {
                for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nLsCount; i++) nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
            }
            for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dFactorB, LoadCaseNo, rData, 0);
            double dWF = (j%2==0) ? dFactorB : -1. * dFactorB;
            if(m_nWCount > 0)
            {
                nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
            }
            if(m_nTCount > 0)           nTL += Set_STLCIncludeCS(arTLoad.GetAt(l),  dFactorB, LoadCaseNo, rData, 0);
            if(m_nTpgCount > 0)         nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dFactorB, LoadCaseNo, rData, 0);          
            if(nVType == 0 && bFlagBrk)
                for(i=0; i<m_nBrkCount; i++) nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(i),dFactorBrk, LoadCaseNo, rData, 0);
            if(nVType == 1 && bFlagWp)
            {
                for(i=0; i<m_nWpCount; i++)   nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFpCount; i++)   nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nSfCount; i++)   nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nWprCount; i++)  nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFrCount; i++)   nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
            }
            if(nVType == 2 && bFlagIp)
            {
                for(i=0; i<m_nIpCount; i++)   nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFrCount; i++)   nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i), dFactorB, LoadCaseNo, rData, 0);
            }
            for(i=0; i<m_nCrCount; i++)   nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dFactorB, LoadCaseNo, rData, D_SGLD_CS_CVL);
            for(i=0; i<m_nShCount; i++)   nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dFactorB, LoadCaseNo, rData, D_SGLD_SS_CVL);
            for(i=0; i<m_nStlCount; i++)  nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dFactorB, LoadCaseNo, rData, 0);
            if(m_nSmCount > 0)            Set_SettleCase(arSmLoad.GetAt(k), dFactorB, LoadCaseNo, rData, TRUE); 
            for(i=0; i<m_nBCount; i++)    nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactorB, LoadCaseNo, rData, 0);
            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c),  dFactorA,  LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], c)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        Set_CStageCase(arCSLoad.GetAt(c), dFactorA, LoadCaseNo, rData, TRUE);
                    else if(CheckCSEL(nErection, _T("L")) || CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")) || CheckCSEL(nErection, _T("W")) || CheckCSEL(nErection, _T("STL")))
                        Set_CStageCase(arCSLoad.GetAt(c), dFactorB, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dPSS, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_CS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dFactorB, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_SS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dFactorB, LoadCaseNo, rData, TRUE);
            }

            rData.Description = _T("");
            CString csPrefix = _T(""); 
            CString csDeadF = kk==0 ? _T("1.1") : _T("0.8");
            if(nDL > 0) {rData.Description += csPrefix + csDeadF + _T("D");   csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + csDeadF + _T("EP");  csPrefix = _T("+");}
            if(bMoving) {rData.Description += csPrefix + _T("1.3M[") + strFixM + _T("]");csPrefix = _T("+");}        
            if(m_nLCount>0)
            {
                if(nLL > 0) {rData.Description += csPrefix + _T("1.3L");  csPrefix = _T("+");}
                if(nIL > 0) {rData.Description += csPrefix + _T("1.3IL"); csPrefix = _T("+");}
            }
            if(bMoving || m_nLCount>0)
            {
                if(nCF > 0) {rData.Description += csPrefix + _T("1.3CF");  csPrefix = _T("+");}
                if(nLS > 0) {rData.Description += csPrefix + _T("1.3LS"); csPrefix = _T("+");}
            }
            if(nCRL> 0) {rData.Description += csPrefix + _T("1.3CRL"); csPrefix = _T("+");}
            if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nTL > 0) {rData.Description += csPrefix + _T("1.3T[") + strFixT + _T("]"); csPrefix = _T("+");}
            if(nTPG> 0) {rData.Description += csPrefix + _T("1.3TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
            if(nVType == 0 && bFlagBrk)
            {
                if(m_bCurvedBridge && m_nCfCount > 0) {rData.Description += csPrefix + _T("0.91BRK");csPrefix = _T("+");}
                else {rData.Description += csPrefix + _T("1.3BRK");csPrefix = _T("+");}
            }
            if(nVType == 1 && bFlagWp)
            {
                if(nWP > 0) {rData.Description += csPrefix + _T("1.3WP"); csPrefix = _T("+");}
                if(nFP > 0) {rData.Description += csPrefix + _T("1.3FP"); csPrefix = _T("+");}
                if(nSF > 0) {rData.Description += csPrefix + _T("1.3SF"); csPrefix = _T("+");}
                if(nWPR> 0) {rData.Description += csPrefix + _T("1.3WPR");csPrefix = _T("+");} 
                if(nFR > 0) {rData.Description += csPrefix + _T("1.3FR"); csPrefix = _T("+");}
            }
            if(nVType == 2 && bFlagIp)
            {
                if(nIP > 0) {rData.Description += csPrefix + _T("1.3IP");  csPrefix = _T("+");}
                if(nFR > 0) {rData.Description += csPrefix + _T("1.3FR");  csPrefix = _T("+");}
            }
            if(nCR > 0) {rData.Description += csPrefix + _T("1.3CR");  csPrefix = _T("+");}
            if(nSH > 0) {rData.Description += csPrefix + _T("1.3SH");  csPrefix = _T("+");}
            if(nSTL> 0) {rData.Description += csPrefix + _T("1.3STL"); csPrefix = _T("+");}
            if(m_nSmCount > 0) {rData.Description += csPrefix + _T("1.3SM[") + strFixSm + _T("]"); csPrefix = _T("+");}      
            if(nBL > 0) {rData.Description += csPrefix + _T("1.3B");  csPrefix = _T("+");}

            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, c))
                {rData.Description += csPrefix + csDeadF + _T("(cD)"); csPrefix = _T("+");}
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], c)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    { rData.Description += csPrefix + csDeadF + strcEL; csPrefix = _T("+"); }
                    else if(CheckCSEL(nErection, _T("L")) || CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")) || CheckCSEL(nErection, _T("W")) || CheckCSEL(nErection, _T("STL")))
                    { rData.Description += csPrefix + _T("1.3(cEL)"); csPrefix = _T("+"); }
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, c))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_CS_CVL, c))
                {rData.Description += csPrefix + _T("1.3(cCR)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_SS_CVL, c))
                {rData.Description += csPrefix + _T("1.3(cSH)"); csPrefix = _T("+");}
            }
            if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);              
}}}}}}}}}

void CLoadCombCtrl::Set_CvlChStrType3Lc(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arLcLoad, ArINT& arCfLoad, ArINT& arLscLoad, ArINT& arCSLoad)
{
    if(m_nPsCount==0 && m_nLcCount==0) return;
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.2, dPsFactor=1.2, dEpFactor=1.2, dLcFactor=1.1, dCfFactor=1.1, dLscFactor=1.1;  
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    // PS or LC or LSC가 있는 경우만 포함
    for(int kk = 0; kk < 2; kk++)
    {
        if(kk == 1) {dDFactor=0.9, dPsFactor=0.9, dEpFactor=0.9;}
        rData.Initialize(); 
        LoadCaseNo = 0;

        int i=0, nDL=0, nPS=0, nEP=0, nLC=0, nCF=0, nLS=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dPsFactor, LoadCaseNo, rData, D_SGLD_TS_CVL);
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        if(m_nLcCount > 0)  
        {
            for(i=0; i<m_nLcCount; i++)  nLC += Set_STLCIncludeCS(arLcLoad.GetAt(i), dLcFactor, LoadCaseNo, rData, 0);        
            for(i=0; i<m_nCfCount; i++)  nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nLscCount; i++) nLS += Set_STLCIncludeCS(arLscLoad.GetAt(i),dLscFactor,LoadCaseNo, rData, 0);
        }  
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");
        CString csPrefix = _T("");
        CString csDead = kk==0 ? _T("1.2") : _T("0.9");  
        if(nDL > 0) {rData.Description += csPrefix + csDead + _T("D");  csPrefix = _T("+");}
        if(nPS > 0) {rData.Description += csPrefix + csDead + _T("PS"); csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + csDead + _T("EP"); csPrefix = _T("+");}
        if(nLC > 0) {rData.Description += csPrefix + _T("1.1LC"); csPrefix = _T("+");}  
        if(nCF > 0) {rData.Description += csPrefix + _T("1.1CF"); csPrefix = _T("+");} 
        if(nLS > 0) {rData.Description += csPrefix + _T("1.1LSC");csPrefix = _T("+");}       

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + csDead + _T("(cD)");  csPrefix = _T("+");}
            			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + csDead + strcEL;  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
    }
}

void CLoadCombCtrl::Set_CvlChStrType3M(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, ArUNT& arMLoad,
                 ArINT& arCfLoad, ArINT& arLscLoad, ArINT& arCSLoad)
{
    if(m_nMCount==0) return;  // Moving load가 있는 경우만 이 함수는 쓰임

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.2, dPsFactor=1.2, dEpFactor=1.2, dMFactor=1.1, dCfFactor=1.1, dLscFactor=1.1;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    
    // DL는 항상포함, CF, LSC는 M가 있는 경우만 포함
    for(int kk = 0; kk < 2; kk++)
    {
        if(kk == 1) {dDFactor=0.9, dPsFactor=0.9, dEpFactor=0.9;}
        for(int j = 0; j < m_nMCount; j++)
        {
            if(m_bMovingSkip && Exist_MovingLoadData(arMLoad.GetAt(j)))
            {
                strFix.Format(_T("%d"), j+1);
                rData.Initialize();  
                LoadCaseNo = 0;
                CString csPrefix = _T("");
                int i=0, nDL=0, nPS=0, nEP=0, nCF=0, nLSC=0;
                for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
                for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dPsFactor, LoadCaseNo, rData, D_SGLD_TS_CVL);
                for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
                                                                        Set_MovingCase(arMLoad.GetAt(j),  dMFactor,  LoadCaseNo, rData, TRUE);              
                for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nLscCount; i++)nLSC+= Set_STLCIncludeCS(arLscLoad.GetAt(i),dLscFactor,LoadCaseNo, rData, 0);
                if(m_nConstLoad!=0)
                {
                    if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                        Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
					 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
						 
						 
                    
                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                            Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                    }
                    if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                        Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);  
                }
                
                rData.Description = _T("");
        
                CString csDead = kk==0 ? _T("1.2") : _T("0.9");
                if(nDL > 0) {rData.Description += csPrefix + csDead + _T("D");   csPrefix = _T("+");}
                if(nPS > 0) {rData.Description += csPrefix + csDead + _T("PS");  csPrefix = _T("+");}
                if(nEP > 0) {rData.Description += csPrefix + csDead + _T("EP");  csPrefix = _T("+");}
                {rData.Description += csPrefix + _T("1.1M[") + strFix + _T("]");  csPrefix = _T("+");}     
                if(nCF > 0) {rData.Description += csPrefix + _T("1.1CF");  csPrefix = _T("+");}    
                if(nLSC> 0) {rData.Description += csPrefix + _T("1.1LSC"); csPrefix = _T("+");}    
                if(m_nConstLoad!=0)
                {
                    if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    {rData.Description += csPrefix + csDead += _T("(cD)");  csPrefix = _T("+");}
					 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
						 
						 
                    
                        if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        {rData.Description += csPrefix + csDead + strcEL;  csPrefix = _T("+");}
                    }
                    if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
                }
                if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);   
            }
        }
    }
}

void CLoadCombCtrl::Set_CvlChStrType4M(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArUNT& arMLoad,  
                 ArINT& arLLoad, ArINT& arIlLoad,ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arCvLoad,
                 ArINT& arCSLoad)
{
    if(m_nCvCount==0) return;  // Moving load와 Collision Load가 있는 경우만 이 함수는 쓰임

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.2, dEpFactor=1.2, dMFactor=1.4, dCfFactor=1.4, dLsFactor=1.4, dCrlFactor=1.4;
    double dCvFactor=1.3;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    
    // DL는 항상포함, CF, LS는 M가 있는 경우만 포함
    for(int kk = 0; kk < 2; kk++)
    {
        if(kk == 1) {dDFactor=0.9, dEpFactor=0.9;}
        int nMCount = max(m_nMCount, 1);
        for(int j=0; j<nMCount; j++)
        {
            strFix.Format(_T("%d"), j+1);
            rData.Initialize();  
            LoadCaseNo = 0;
            CString csPrefix = _T("");
            int i=0, nDL=0, nLL=0, nIL=0, nEP=0, nCF=0, nLS=0, nCRL=0, nCV=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
            BOOL bMoving = FALSE;
            if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(j))) || !m_bMovingSkip;
            if(bMoving) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);              
            if(m_nLCount>0)  
            {
                for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor, LoadCaseNo, rData, 0);        
                for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dMFactor, LoadCaseNo, rData, 0);
            }
            if(bMoving || m_nLCount>0)
            {
                for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nLsCount; i++) nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dLsFactor, LoadCaseNo, rData, 0);
            }
            for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dCrlFactor,LoadCaseNo, rData, 0);
            for(i=0; i<m_nCvCount; i++) nCV += Set_STLCIncludeCS(arCvLoad.GetAt(i), dCvFactor, LoadCaseNo, rData, 0);
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                    else if(CheckCSEL(nErection, _T("L")))
                        Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPSS,LoadCaseNo, rData, TRUE);  
            }
    
            rData.Description = _T("");
            CString csDead = kk==0 ? _T("1.2") : _T("0.9");
            if(nDL > 0) {rData.Description += csPrefix + csDead + _T("D");   csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + csDead + _T("EP");  csPrefix = _T("+");}
            if(bMoving) {rData.Description += csPrefix + _T("1.4M[") + strFix + _T("]");  csPrefix = _T("+");}
            if(m_nLCount > 0)
            {
                if(nLL > 0) {rData.Description += csPrefix + _T("1.4L");  csPrefix = _T("+");}
                if(nIL > 0) {rData.Description += csPrefix + _T("1.4IL"); csPrefix = _T("+");}
            } 
            if(bMoving || m_nLCount>0)
            {
                if(nCF > 0) {rData.Description += csPrefix + _T("1.4CF");  csPrefix = _T("+");}    
                if(nLS > 0) {rData.Description += csPrefix + _T("1.4LS"); csPrefix = _T("+");}
            }
            if(nCRL> 0) {rData.Description += csPrefix + _T("1.4CRL"); csPrefix = _T("+");}
            if(nCV > 0) {rData.Description += csPrefix + _T("1.3CV");  csPrefix = _T("+");}
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                {rData.Description += csPrefix + csDead + _T("(cD)");  csPrefix = _T("+");}
                 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    {rData.Description += csPrefix + csDead + strcEL;  csPrefix = _T("+");}
                    else if(CheckCSEL(nErection, _T("L")))
                    {rData.Description += csPrefix + _T("1.4(cEL)");  csPrefix = _T("+");}
                }
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            }
            if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);   
        }
    }
}

////////////////////////////////////////////////////////////////////////
////// Serviceability Load Case for Civil : JTJ021-89, CJJ77-98 ////////
////////////////////////////////////////////////////////////////////////
void CLoadCombCtrl::Set_CvlChService1M(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arShLoad, ArINT& arCrLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arBLoad, ArUNT& arMLoad, 
                 ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arCSLoad,
                 int nActive)
{
    if(m_nConstLoad==0 && m_nDCount==0 && m_nPsCount==0 && m_nEpCount==0 && m_nShCount==0 && m_nCrCount==0 &&
         m_nStlCount==0 && m_nSmCount==0 && m_nBCount==0 && m_nLCount==0 && m_nCrlCount==0) return;

    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixM, strFixSm;
    int nSmCount = max(m_nSmCount, 1);
    
    int nMCount = max(m_nMCount, 1);
    for(int l=0; l<nMCount; l++) {
    for(int k = 0; k < nSmCount; k++)
    {
        strFixM.Format(_T("%d"), l+1);
        strFixSm.Format(_T("%d"), k+1);  
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nLL=0, nIL=0, nPS=0, nEP=0, nCR=0, nSH=0, nSTL=0, nBL=0, nCF=0, nLS=0, nCRL=0;
        for(i=0; i<m_nDCount; i++)   nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
        for(i=0; i<m_nPsCount; i++)  nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
        for(i=0; i<m_nEpCount; i++)  nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        for(i=0; i<m_nCrCount; i++)  nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_CS_CVL); 
        for(i=0; i<m_nShCount; i++)  nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_SS_CVL); 
        for(i=0; i<m_nStlCount; i++) nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
        if(m_nSmCount > 0)           Set_SettleCase(arSmLoad.GetAt(k), dFactor, LoadCaseNo, rData, TRUE);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactor, LoadCaseNo, rData, 0); 
        BOOL bMoving = FALSE;
        if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(l))) || !m_bMovingSkip;
        if(bMoving) Set_MovingCase(arMLoad.GetAt(l), dFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount>0)  
        {
            for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            if(nActive==1) for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
        }
        if(bMoving || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++)  nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            for(i=0; i<m_nLsCount; i++)  nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        }
        for(i=0; i<m_nCrlCount; i++) nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
        }
                        
        rData.Description = _T("");
        if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC :");
        CString csPrefix = _T("");        
    
        if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
        if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
        if(nCR > 0) {rData.Description += csPrefix + _T("CR");  csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + _T("SH");  csPrefix = _T("+");}
        if(nSTL> 0) {rData.Description += csPrefix + _T("STL"); csPrefix = _T("+");}
        if(m_nSmCount > 0) {rData.Description += csPrefix + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}      
        if(nBL > 0) {rData.Description += csPrefix + _T("B");  csPrefix = _T("+");}
        if(bMoving) {rData.Description += csPrefix + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}        
        if(m_nLCount>0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("L"); csPrefix = _T("+");}
            if(nActive == 1 && nIL > 0) {rData.Description += csPrefix + _T("IL"); csPrefix = _T("+");}
        }
        if(bMoving || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("CF");  csPrefix = _T("+");}
            if(nLS > 0) {rData.Description += csPrefix + _T("LS") ; csPrefix = _T("+");}
        }
        if(nCRL> 0) {rData.Description += csPrefix + _T("CRL"); csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("L")))
                { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
            {rData.Description += csPrefix + _T("(cCR)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            {rData.Description += csPrefix + _T("(cSH)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0)
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
            Set_LoadComb4Civil(rData, D_SER);
        }    
}}}

void CLoadCombCtrl::Set_CvlChService2M(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arShLoad, ArINT& arCrLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arBLoad, ArUNT& arMLoad, 
                 ArINT& arLLoad, ArINT& arIlLoad,ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arWLoad,
                 ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arBrkLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad,
                 ArINT& arWprLoad, ArINT& arIpLoad, ArINT& arFrLoad, ArINT& arCSLoad, int nActive)
{
    if(m_nConstLoad==0 && m_nWCount==0 && m_nTCount==0 && m_nTpgCount==0 && m_nBrkCount==0 && m_nWpCount==0 &&
         m_nFpCount==0 && m_nSfCount==0 && m_nWprCount==0 && m_nFrCount==0 && m_nIpCount==0 && m_nWpCount==0 &&
         m_nFpCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nStlCount==0 && m_nSmCount==0 && m_nBCount==0) return;

    int LoadCaseNo = 0, c=0;
    T_LCOM_D rData;
    double dFactor=1.0, dFactorBrk=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixM, strFixW, strFixSm, strFixT, strFixTpg;
    int nWCount   = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount  = max(m_nSmCount, 1);
    int nTCount   = max(m_nTCount,  1);
    int nTpgCount = max(m_nTpgCount,1);
    
    BOOL bFlagBrk = FALSE;
    BOOL bFlagWp = FALSE;
    BOOL bFlagIp = FALSE;
    BOOL bFlagNone = FALSE;
    if(m_nBrkCount > 0) bFlagBrk = TRUE;    // BRK가 있을 경우
    if(m_nIpCount > 0)  bFlagIp = TRUE;     // IP가 있을 경우
    if(m_nWpCount + m_nFpCount + m_nSfCount + m_nWprCount > 0) bFlagWp = TRUE; // WP, FP, SF, WPR이 있을 경우    
    if(!bFlagBrk && !bFlagWp && !bFlagIp) bFlagNone = TRUE;
    // 커브교일때 이심력과 제동력 조합시  제동력은 70%로 계산한다.
    if(m_bCurvedBridge && m_nBrkCount > 0 && m_nCfCount > 0) dFactorBrk = 0.7; 

    for(int nVType = 0; nVType < 4; nVType++){
    if((nVType == 0 && bFlagBrk) || (nVType == 1 && bFlagWp) || (nVType == 2 && bFlagIp) || (nVType == 3 && bFlagNone))
    {  
        int nMCount = max(m_nMCount, 1);
        for(int l = 0; l < nMCount;   l++){
        for(int k = 0; k < nSmCount;  k++) {
        for(int j = 0; j < nWCount;   j++) {
        for(int n = 0; n < nTCount;   n++) {
        for(int m = 0; m < nTpgCount; m++) {
            strFixM.Format(_T("%d"), l+1);
            strFixSm.Format(_T("%d"), k+1);  
            strFixW.Format(_T("%d"), j/2+1);          
            strFixT.Format(_T("%d"), n+1);
            strFixTpg.Format(_T("%d"), m+1);
            rData.Initialize();  
            LoadCaseNo = 0;

            int i=0, nDL=0, nLL=0, nIL=0, nPS=0, nEP=0, nCR=0, nSH=0, nSTL=0, nBL=0, nCF=0, nLS=0, nCRL=0;
            int nWL=0, nTL=0, nTPG=0, nBRK=0, nWP=0, nFP=0, nSF=0, nWPR=0, nFR=0, nIP=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
            for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            for(i=0; i<m_nCrCount; i++) nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_CS_CVL); 
            for(i=0; i<m_nShCount; i++) nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_SS_CVL); 
            for(i=0; i<m_nStlCount; i++)nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
            if(m_nSmCount > 0)          Set_SettleCase(arSmLoad.GetAt(k), dFactor, LoadCaseNo, rData, TRUE);
            for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactor, LoadCaseNo, rData, 0); 
            BOOL bMoving = FALSE;
            if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(l))) || !m_bMovingSkip;
            if(bMoving) Set_MovingCase(arMLoad.GetAt(l),  dFactor, LoadCaseNo, rData, TRUE);
            if(m_nLCount>0)  
            {
                for(i=0; i<m_nLCount; i++)  nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dFactor, LoadCaseNo, rData, 0);                
                if(nActive == 1) for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            }
            if(bMoving || m_nLCount>0)
            {
                for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
                for(i=0; i<m_nLsCount; i++) nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            }
            for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
            double dWF = (j%2==0) ? dFactor : -1.*dFactor;
            if(m_nWCount > 0)
            {
                nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
            }
            if(m_nTCount > 0)           nTL += Set_STLCIncludeCS(arTLoad.GetAt(n),  dFactor, LoadCaseNo, rData, 0);
            if(m_nTpgCount > 0)         nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dFactor, LoadCaseNo, rData, 0);
            if(nVType == 0 && bFlagBrk)
                for(i=0; i<m_nBrkCount; i++) nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(i),dFactorBrk, LoadCaseNo, rData, 0);
            if(nVType == 1 && bFlagWp)
            {
                for(i=0; i<m_nWpCount; i++)  nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFpCount; i++)  nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nWprCount; i++) nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFrCount; i++)  nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            }
            if(nVType == 2 && bFlagIp)
            {
                for(i=0; i<m_nIpCount; i++)  nIP += Set_STLCIncludeCS(arIpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
                for(i=0; i<m_nFrCount; i++)  nFR += Set_STLCIncludeCS(arFrLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            }
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c),  dFactor,  LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], c)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("L")) ||
                         CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG"))|| CheckCSEL(nErection, _T("W"))  || CheckCSEL(nErection, _T("STL")))
                        Set_CStageCase(arCSLoad.GetAt(c), dFactor, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dPST, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_TS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dPSS, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_CS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dFactor, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_SS_CVL, c))
                    Set_CStageCase(arCSLoad.GetAt(c), dFactor, LoadCaseNo, rData, TRUE);
            }
                        
            rData.Description = _T("");
            if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC :");
            CString csPrefix = _T("");        
    
            if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
            if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
            if(nCR > 0) {rData.Description += csPrefix + _T("CR");  csPrefix = _T("+");}
            if(nSH > 0) {rData.Description += csPrefix + _T("SH");  csPrefix = _T("+");}
            if(nSTL> 0) {rData.Description += csPrefix + _T("STL"); csPrefix = _T("+");}
            if(m_nSmCount > 0) {rData.Description += csPrefix + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}      
            if(nBL > 0) {rData.Description += csPrefix + _T("B");  csPrefix = _T("+");}
            if(bMoving) {rData.Description += csPrefix + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}        
            if(m_nLCount>0)
            {
                if(nLL > 0) {rData.Description += csPrefix + _T("L"); csPrefix = _T("+");}
                if(nActive == 1 && nIL > 0) {rData.Description += csPrefix + _T("IL"); csPrefix = _T("+");}
            }
            if(bMoving || m_nLCount>0)
            {
                if(nCF > 0) {rData.Description += csPrefix + _T("CF");  csPrefix = _T("+");}
                if(nLS > 0) {rData.Description += csPrefix + _T("LS") ; csPrefix = _T("+");}
            }
            if(nCRL> 0) {rData.Description += csPrefix + _T("CRL"); csPrefix = _T("+");}
            if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix +GetFactorString(dWF)+_T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nTL > 0) {rData.Description += csPrefix + _T("T[") + strFixT + _T("]"); csPrefix = _T("+");}
            if(nTPG> 0) {rData.Description += csPrefix + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
            if(nVType == 0 && bFlagBrk)
            {
                if(m_bCurvedBridge && m_nCfCount > 0) {rData.Description += csPrefix + _T("0.7BRK");csPrefix = _T("+");}
                else {rData.Description += csPrefix + _T("BRK");csPrefix = _T("+");}
            }
            if(nVType == 1 && bFlagWp)
            {
                if(nWP > 0) {rData.Description += csPrefix + _T("WP"); csPrefix = _T("+");}
                if(nFP > 0) {rData.Description += csPrefix + _T("FP"); csPrefix = _T("+");}
                if(nSF > 0) {rData.Description += csPrefix + _T("SF"); csPrefix = _T("+");}
                if(nWPR> 0) {rData.Description += csPrefix + _T("WPR");csPrefix = _T("+");} 
                if(nFR > 0) {rData.Description += csPrefix + _T("FR"); csPrefix = _T("+");}
            }
            if(nVType == 2 && bFlagIp)
            {
                if(nIP > 0) {rData.Description += csPrefix + _T("IP");  csPrefix = _T("+");}
                if(nFR > 0) {rData.Description += csPrefix + _T("FR");  csPrefix = _T("+");}
            }   
            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, c))
                {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], c)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("L")) ||
                         CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG"))|| CheckCSEL(nErection, _T("W"))  || CheckCSEL(nErection, _T("STL")))
                    { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, c))
                {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_TS_CVL, c))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_CS_CVL, c))
                {rData.Description += csPrefix + _T("(cCR)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_SS_CVL, c))
                {rData.Description += csPrefix + _T("(cSH)"); csPrefix = _T("+");}
            }
            if(LoadCaseNo > 0)
            {
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
                Set_LoadComb4Civil(rData, D_SER);
            }    
}}}}}}}}

void CLoadCombCtrl::Set_CvlChService3Lc(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arLcLoad, ArINT& arCfLoad, ArINT& arLscLoad, ArINT& arCSLoad, int nActive)
{
    if(m_nConstLoad==0 && m_nLcCount==0) return;
    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    
    rData.Initialize();  
    LoadCaseNo = 0;
    int i=0, nDL=0, nPS=0, nEP=0, nLC=0, nCF=0, nLSC=0;
    for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
    for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
    for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
    if(m_nLcCount > 0)  
    {
        for(i=0; i<m_nLcCount; i++)  nLC += Set_STLCIncludeCS(arLcLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);    
        for(i=0; i<m_nCfCount; i++)  nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nLscCount; i++) nLSC+= Set_STLCIncludeCS(arLscLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0);
    }
    if(m_nConstLoad!=0) // CS or ST+CS
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n),  dFactor,  LoadCaseNo, rData, TRUE);
		 
		CString strcEL;
		int nErection = 0;

		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			 
			 
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
        }
        if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
    }
                    
    rData.Description = _T("");
    if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC :");
    CString csPrefix = _T(""); 
    if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
    if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
    if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
    if(m_nLcCount > 0)
    {
        if(nLC > 0) {rData.Description += csPrefix + _T("LC");  csPrefix = _T("+");}
        if(nCF > 0) {rData.Description += csPrefix + _T("CF");  csPrefix = _T("+");}
        if(nLSC> 0) {rData.Description += csPrefix + _T("LSC"); csPrefix = _T("+");}
    }
    
    if(m_nConstLoad!=0) // CS or ST+CS
    {
        if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
        {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
		 
		CString strcEL;
		int nErection = 0;
		
		for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
		{
			strcEL = _T(""); nErection = 0;
			if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			 
			 
        
            if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
        }
        if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
        {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
        if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
        {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
    }
    if(LoadCaseNo > 0)
    {
        if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
        if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
        Set_LoadComb4Civil(rData, D_SER);
    }
}

void CLoadCombCtrl::Set_CvlChService3M(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArUNT& arMLoad, ArINT& arCfLoad, ArINT& arLscLoad, ArINT& arCSLoad, int nActive)
{
    if(m_nMCount == 0) return;

    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixM;

    for(int l = 0; l < m_nMCount; l++)
    {
        if(m_bMovingSkip && Exist_MovingLoadData(arMLoad.GetAt(l)))
        {
            rData.Initialize();  
            LoadCaseNo = 0;
            strFixM.Format(_T("%d"), l+1);
            int i=0, nDL=0, nPS=0, nEP=0, nLC=0, nCF=0, nLSC=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
            for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
                                                                    Set_MovingCase(arMLoad.GetAt(l),  dFactor, LoadCaseNo, rData, TRUE);    
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            for(i=0; i<m_nLscCount; i++)nLSC+= Set_STLCIncludeCS(arLscLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0);
            if(m_nConstLoad!=0)
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n),  dFactor,  LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;

				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            }
                    
            rData.Description = _T("");
            if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC :");
            CString csPrefix = _T("");
            if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
            if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
                                    {rData.Description += csPrefix + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}
            if(nCF > 0) {rData.Description += csPrefix + _T("CF");  csPrefix = _T("+");}
            if(nLSC> 0) {rData.Description += csPrefix + _T("LSC"); csPrefix = _T("+");}
            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}


				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            }
            if(LoadCaseNo > 0)
            {
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
                Set_LoadComb4Civil(rData, D_SER);
            }
        }
    }
}

void CLoadCombCtrl::Set_CvlChService4M(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arShLoad, ArINT& arCrLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arBLoad, ArUNT& arMLoad, 
                 ArINT& arLLoad, ArINT& arIlLoad, ArINT& arCfLoad, ArINT& arLsLoad, ArINT& arCrlLoad, ArINT& arCvLoad,
                 ArINT& arCSLoad, int nActive)
{
    if(m_nCvCount==0) return;

    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixM, strFixSm;
    
    int nSmCount = max(m_nSmCount, 1);
    int nMCount  = max(m_nMCount, 1);
    for(int l = 0; l < nMCount;  l++) {
    for(int k = 0; k < nSmCount; k++)
    {
        strFixM.Format(_T("%d"), l+1);
        strFixSm.Format(_T("%d"), k+1);  
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nLL=0, nIL=0, nPS=0, nEP=0, nCR=0, nSH=0, nSTL=0, nBL=0, nCF=0, nLS=0, nCRL=0, nCV=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
        for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        for(i=0; i<m_nCrCount; i++) nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_CS_CVL); 
        for(i=0; i<m_nShCount; i++) nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_SS_CVL); 
        for(i=0; i<m_nStlCount; i++)nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
        if(m_nSmCount > 0)          Set_SettleCase(arSmLoad.GetAt(k), dFactor, LoadCaseNo, rData, TRUE);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dFactor, LoadCaseNo, rData, 0); 
        BOOL bMoving = FALSE;
        if(m_nMCount>0) bMoving = (m_bMovingSkip && !Exist_MovingLoadData(arMLoad.GetAt(l))) || !m_bMovingSkip;
        if(bMoving) Set_MovingCase(arMLoad.GetAt(l), dFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount > 0)  
        {
            for(i=0; i<m_nLCount; i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
            if(nActive == 1) for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0);
        }
        if(bMoving || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            for(i=0; i<m_nLsCount; i++) nLS += Set_STLCIncludeCS(arLsLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        }
        for(i=0; i<m_nCrlCount; i++)nCRL+= Set_STLCIncludeCS(arCrlLoad.GetAt(i),dFactor, LoadCaseNo, rData, 0); 
        for(i=0; i<m_nCvCount; i++) nCV += Set_STLCIncludeCS(arCvLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        if(m_nConstLoad!=0)
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dFactor,  LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
        }
        
        rData.Description = _T("");
        if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC :");
        CString csPrefix = _T("");        
    
        if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
        if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
        if(nCR > 0) {rData.Description += csPrefix + _T("CR");  csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + _T("SH");  csPrefix = _T("+");}
        if(nSTL> 0) {rData.Description += csPrefix + _T("STL"); csPrefix = _T("+");}
        if(m_nSmCount > 0) {rData.Description += csPrefix + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}      
        if(nBL > 0) {rData.Description += csPrefix + _T("B");   csPrefix = _T("+");}
        if(bMoving) {rData.Description += csPrefix + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}        
        if(m_nLCount > 0)
        {
            if(nLL > 0) {rData.Description += csPrefix + _T("L"); csPrefix = _T("+");}
            if(nActive == 1 && nIL > 0) {rData.Description += csPrefix + _T("IL"); csPrefix = _T("+");}
        }
        if(bMoving || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + _T("CF");  csPrefix = _T("+");}
            if(nLS > 0) {rData.Description += csPrefix + _T("LS") ;   csPrefix = _T("+");}          
        }
        if(nCRL> 0) {rData.Description += csPrefix + _T("CRL"); csPrefix = _T("+");}
        if(nCV > 0) {rData.Description += csPrefix + _T("CV");  csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("L")))
                { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
            {rData.Description += csPrefix + _T("(cCR)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            {rData.Description += csPrefix + _T("(cSH)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0)
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
            Set_LoadComb4Civil(rData, D_SER);
        }    
}}}
    
void CLoadCombCtrl::Set_CvlChStrSer6E(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArINT& arELoad, ArINT& arCSLoad, int nActive)
{
    if(m_nECount==0) return;

    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;  
    
    for(int k = 0; k < m_nECount*2; k++)
    {
        strFix.Format(_T("%d"), k/2+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        int i=0, nDL=0, nPS=0, nEP=0, nEL=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
        for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, D_SGLD_TS_CVL); 
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
        double dEF = (k%2==0) ? dFactor : -1.*dFactor;
        nEL += Set_STLCIncludeCS(arELoad.GetAt(k/2), dEF, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dFactor,  LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("E")))
                    Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
        rData.Description = _T("");
        if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC : ");
        CString csPrefix = _T("");  
        if(nDL > 0) { rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
        if(nPS > 0) { rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
        if(nEP > 0) { rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
        if(nEL > 0) { if(dEF<0.0) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dEF)+_T("E[") + strFix + _T("]"); csPrefix = _T("+");}      
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("E")))
                { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0)
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
            Set_LoadComb4Civil(rData, D_SER);
        }
    }
}

void CLoadCombCtrl::Set_CvlChStrSer6S(CString strCode, ArINT& arDLoad, ArINT& arPsLoad, ArINT& arEpLoad, 
                 ArUNT& arEspLoad, ArINT& arCSLoad, int nActive)
{
    if(m_nEspCount == 0) return;

    int LoadCaseNo, n=0;
    T_LCOM_D rData;
    double dFactor=1.0, dSFactor;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix, strScaleUpFactor;  
    for(int j = 0; j < m_nEspCount; j++)
    {    
        for(int k = 0; k < 2; k++)
        {
            if(k == 0) dSFactor = 1.0;    
            else dSFactor = -1.0;
            strFix.Format(_T("%d"), j+1);
            double dScaleUpFactor;
            BOOL bCheck	= Get_ScaleUpFactor(D_LOADCASE_SPECTRUM, arEspLoad.GetAt(j), dScaleUpFactor);
            strScaleUpFactor.Format(_T("%.3f"), dScaleUpFactor);       
            rData.Initialize();  
            LoadCaseNo = 0;
            int i=0, nDL=0, nPS=0, nEP=0, nEL=0;
            for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dFactor, LoadCaseNo, rData, D_SGLD_DL_CVL); 
            for(i=0; i<m_nPsCount; i++) nPS += Set_STLCIncludeCS(arPsLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dFactor, LoadCaseNo, rData, 0); 
            Set_SpectrumCase(arEspLoad.GetAt(j), dSFactor*dScaleUpFactor, LoadCaseNo, rData, TRUE);
            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n),  dFactor,  LoadCaseNo, rData, TRUE);
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                        Set_CStageCase(arCSLoad.GetAt(n), dFactor, LoadCaseNo, rData, TRUE);
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                    Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
            }

            rData.Description = _T("");
            if(nActive == 2 && m_nLcomType != D_LCOMTYPE_GENERAL) rData.Description = _T("ServiceLC : ");    
            CString csPrefix=_T("");      
            if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
            if(nPS > 0) {rData.Description += csPrefix + _T("PS");  csPrefix = _T("+");}
            if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
            if(k == 0)  // + sign
            {
                if(bCheck) {rData.Description += csPrefix + strScaleUpFactor + _T("*ESP[") + strFix + _T("]"); csPrefix = _T("+");}
                else       {rData.Description += csPrefix + _T("ESP[") + strFix + _T("]"); csPrefix = _T("+");}
            }
            else   // - sign
            {
                if(bCheck) {rData.Description += _T("-") + strScaleUpFactor + _T("*ESP[") + strFix + _T("]"); csPrefix = _T("+");}
                else       {rData.Description += _T("-ESP[") + strFix + _T("]"); csPrefix = _T("+");}
            }
            if(m_nConstLoad!=0) // CS or ST+CS
            {
                if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
				 
				CString strcEL;
				int nErection = 0;
				
				for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
				{
					strcEL = _T(""); nErection = 0;
					if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					 
					 
                
                    if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    { rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
                }
                if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTP)"); csPrefix = _T("+");}
                if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
            }
        
            if(LoadCaseNo > 0)
            {
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
                if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
                Set_LoadComb4Civil(rData, D_SER);
            }
        }
    }  
}

void CLoadCombCtrl::Set_CvlCh_CSPS(CString strCode, ArINT& arCSLoad, int nActive, int nStr)
{
    if(m_nConstLoad==0) return; // ST only
    BOOL bStageCS=FALSE;
	if(m_pDoc->IsPostMode())	bStageCS = m_pDoc->m_pPostCtrl->StageAnalysis();
	else											bStageCS = m_bCSAnalysis;
    if(!bStageCS) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData; rData.Initialize();

    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);

    double dFactor   =  1.;
    double dMnFactor = -1.;
    
    if(CheckCS_SgldK(D_SGLD_SUM_CVL, n))
    {
        Set_CStageCase(arCSLoad.GetAt(n), 1.0, LoadCaseNo, rData, TRUE);
        if(fabs(dPST-1.0) < m_dZeroLim)
        {
            rData.Description = _T("(SUM-TS) + (1.0)TS");
        }
        else
        {
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {
                Set_CStageCase(arCSLoad.GetAt(n), dPSS-1.0, LoadCaseNo, rData, TRUE);
                rData.Description = _T("(SUM-TS) + (SFAT)TS");
            }
        }
    }

    if(LoadCaseNo > 0)
    {
        if(nStr == D_STR) Set_LoadComb4Civil(rData, D_STR);
        else
        {
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 1)  rData.nActive = 1;  // Strength
            if(m_nLcomType != D_LCOMTYPE_GENERAL && nActive == 2)  rData.nActive = 2;  // Serviceability.
            Set_LoadComb4Civil(rData, D_SER);
        }
    }
}

BOOL CLoadCombCtrl::CheckCSEL(int nErection, CString strLoadType)
{
    int iErIdx = nErection-2;
    if(iErIdx < 0 || iErIdx > D_STCT_EREC_MAX_CVL) return FALSE;
	return m_strCSEL_LdType[iErIdx].Compare(strLoadType)==0 ? TRUE:FALSE;
}
///////////////////////////////////////////////////////////////////////////
////// Strength/Stress Load Case for Civil : KRTA-BRG2K, KSCE-USD03 ///////
///////////////////////////////////////////////////////////////////////////

void CLoadCombCtrl::Set_CvlDeadMoveCfEpQ(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad,
                                        ArINT& arIlLoad, ArINT& arCfLoad, ArINT& arEpLoad, ArINT& arBLoad, ArINT& arWpLoad,
                                        ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arCSLoad, int nType)
{
    // (KRTA-BRG, KSCE-USD, 2.2.1) : 1.3D + 2.15(L+I) + 1.3CF + 1.7H + 1.3Q
    // (KSCE-RAIL-USD04,    3.3.1) : 1.4D + 2.00(L+I) + 1.4CF + 1.7H + 1.4Q (nType==0)
    // (KSCE-RAIL-USD04,    3.3.2) : 1.7D + 1.70(L+I) + 1.7CF + 1.7H + 1.7Q (nType==1)
    if(m_nConstLoad==0 && m_nDCount==0 && m_nMCount==0 && m_nLCount ==0 && m_nIlCount==0 && m_nCfCount==0 &&
         m_nEpCount ==0 && m_nBCount==0 && m_nWpCount==0 && m_nFpCount==0 && m_nSfCount==0 && m_nWprCount==0) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=2.15, dIlFactor=2.15, dCfFactor=1.3, dEpFactor=1.7, dBFactor=1.3;
    double dWpFactor=1.3, dFpFactor=1.3, dSfFactor=1.3, dWprFactor=1.3;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        if(nType==0)
        {
            dDFactor=1.4,  dMFactor=2.0,  dIlFactor=2.0, dCfFactor=1.4, dEpFactor=1.7, dBFactor=1.4;
            dWpFactor=1.4, dFpFactor=1.4, dSfFactor=1.4, dWprFactor=1.4;
        }
        else if(nType==1)
        {
            dDFactor  = dMFactor  = dIlFactor = dCfFactor  = dEpFactor = dBFactor = 1.7;
            dWpFactor = dFpFactor = dSfFactor = dWprFactor = 1.7;
        }
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    int nMCount = max(m_nMCount, 1);
    // DL는 항상포함 CF는 Moving Load가 있는 경우만 포함
    for(int j=0; j<nMCount; j++)
    {
        strFix.Format(_T("%d"), j+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        CString csPrefix = _T("");
        int i=0, nDL=0, nLL=0, nIL=0, nCF=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0;
        for(i=0; i<m_nDCount; i++) nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount;  i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nEpCount; i++) nEP  += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount;  i++) nBL  += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP  += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP  += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF  += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount;i++) nWPR += Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");
        if(nDL > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");  csPrefix = _T("+");}
        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFix + _T("]"); csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL>0) {rData.Description += csPrefix + GetFactorString(dMFactor)  + _T("L");  csPrefix = _T("+");}
            if(nIL>0) {rData.Description += csPrefix + GetFactorString(dIlFactor) + _T("IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF>0) {rData.Description += csPrefix + GetFactorString(dCfFactor)  + _T("CF");  csPrefix = _T("+");}
        }
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor)  + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor)   + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor)  + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor)  + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor)  + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n)) { rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)");  csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL;  csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                { rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL;  csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);   
    }
}

void CLoadCombCtrl::Set_CvlDeadMoveCfEpQG(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad, 
         ArINT& arCfLoad, ArINT& arEpLoad, ArINT& arBLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, 
         ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arCrLoad, ArINT& arShLoad, ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad)
{
    // (KRTA-BRG, KSCE-USD, 2.2.4) : 1.3D + 1.3(L+I) + 1.3CF + 1.7H + 1.3Q + 1.3G
    // (KSCE-RAIL-USD04,    3.3.5) : 1.4D + 1.4(L+I) + 1.4CF + 1.7H + 1.4Q + 1.4G
    if(m_nConstLoad==0 && m_nStlCount==0 && m_nSmCount==0 && m_nCrCount==0 && m_nShCount==0 &&
         m_nTCount==0 && m_nTpgCount==0) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dIlFactor=1.3, dCfFactor=1.3, dEpFactor=1.7, dBFactor=1.3, dWpFactor=1.3, dWprFactor=1.3; 
    double dFpFactor=1.3, dSfFactor=1.3, dStlFactor=1.3, dSmFactor=1.3, dCrFactor=1.3, dShFactor=1.3, dTFactor=1.3;
    double dTpgFactor=1.3;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,  dMFactor=1.4,   dIlFactor=1.4, dCfFactor=1.4,  dEpFactor=1.7, dBFactor=1.4;
        dWpFactor=1.4, dWprFactor=1.4, dFpFactor=1.4, dSfFactor=1.4, dStlFactor=1.4, dSmFactor=1.4;
        dCrFactor=1.4, dShFactor=1.4,  dTFactor=1.4,  dTpgFactor=1.4;
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    // DL는 항상포함, IL과 CF는 LL가 있는 경우만 포함
    int nSmCount  = max(m_nSmCount,  1);
    int nTCount   = max(m_nTCount,   1);
    int nTpgCount = max(m_nTpgCount, 1);
    CString strFixM, strFixSm, strFixT, strFixTpg;
        
    int nMCount = max(m_nMCount, 1);
    for(int j = 0; j < nMCount;   j++) {
    for(int k = 0; k < nSmCount;  k++) {
    for(int l = 0; l < nTCount;   l++) {
    for(int m = 0; m < nTpgCount; m++)
    {          
        rData.Initialize();
        LoadCaseNo = 0;
        strFixM.Format(_T("%d"), j+1);
        strFixSm.Format(_T("%d"), k+1);
        strFixT.Format(_T("%d"), l+1);
        strFixTpg.Format(_T("%d"), m+1);

        int i=0, nDL=0, nLL=0, nIL=0, nCF=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nSTL=0, nCR=0, nSH=0, nTL=0, nTPG=0;
        for(i=0; i<m_nDCount; i++)   nDL  += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,   LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j),  dMFactor,  LoadCaseNo, rData, TRUE);
        if(m_nLCount > 0)
        { 
            for(i=0; i<m_nLCount; i++)  nLL  += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,   LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL  += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor,  LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF  += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor,  LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nEpCount; i++)  nEP  += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL  += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,   LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++)  nWP  += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++)  nFP  += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF  += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++) nWPR += Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nStlCount; i++) nSTL += Set_STLCIncludeCS(arStlLoad.GetAt(i),dStlFactor, LoadCaseNo, rData, 0);
        if(m_nSmCount > 0)           Set_SettleCase(arSmLoad.GetAt(k), dSmFactor, LoadCaseNo, rData, TRUE);
        for(i=0; i<m_nCrCount; i++)  nCR  += Set_STLCIncludeCS(arCrLoad.GetAt(i), dCrFactor,  LoadCaseNo, rData, D_SGLD_CS_CVL);
        for(i=0; i<m_nShCount; i++)  nSH  += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor,  LoadCaseNo, rData, D_SGLD_SS_CVL);
        if(m_nTCount > 0)            nTL  += Set_STLCIncludeCS(arTLoad.GetAt(l),  dTFactor,   LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)          nTPG += Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTpgFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dCrFactor,  LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dShFactor,  LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");      
        CString csPrefix = _T("");
        if(nDL > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");   csPrefix = _T("+");}
        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+");}
        if(m_nLCount>0)
        { 
            if(nLL > 0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("L");  csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + GetFactorString(dIlFactor) + _T("IL"); csPrefix = _T("+");}  
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF"); csPrefix = _T("+");}
        }
        if(nCR > 0) {rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("CR");  csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + GetFactorString(dShFactor) + _T("SH");  csPrefix = _T("+");}
        if(nTL > 0) {rData.Description += csPrefix + GetFactorString(dTFactor)  + _T("T[") + strFixT + _T("]");   csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + GetFactorString(dTpgFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor)  + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}
        if(nSTL> 0) {rData.Description += csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
        if(m_nSmCount > 0) {rData.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
            

			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+"); }
                else if(CheckCSEL(nErection, _T("L")))
                { rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+"); }
                else if(CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")))
                { rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+"); }
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
            rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("(cCR)"); csPrefix = _T("+");
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            rData.Description += csPrefix + GetFactorString(dShFactor) + _T("(cSH)"); csPrefix = _T("+");
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
}}}}}


void CLoadCombCtrl::Set_CvlDeadMoveCfEpQCo(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad, 
                ArINT& arCfLoad, ArINT& arEpLoad, ArINT& arBLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, 
                ArINT& arCoLoad, ArINT& arCSLoad)
{
    // (KRTA-BRG, KSCE-USD, 2.2.8) : 1.3D + 1.3(L+I) + 1.3CF + 1.7H + 1.3Q + 1.3CO
    // (KSCE-RAIL-USD04,    3.3.9) : 1.4D + 1.4(L+I)         + 1.7H + 1.4Q + 1.4CO
    if(m_nCoCount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dIlFactor=1.3, dCfFactor=1.3, dEpFactor=1.7, dBFactor=1.3; 
    double dWpFactor=1.3, dFpFactor=1.3, dSfFactor=1.3, dWprFactor=1.3, dCoFactor=1.3;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,  dMFactor=1.4,  dIlFactor=1.4, dCfFactor=0.0,  dEpFactor=1.7, dBFactor=1.4; 
        dWpFactor=1.4, dFpFactor=1.4, dSfFactor=1.4, dWprFactor=1.4, dCoFactor=1.4;
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;      

    int nMCount = max(m_nMCount, 1);
    for(int j=0; j<nMCount; j++)
    {
        rData.Initialize();
        LoadCaseNo = 0;  
        CString csPrefix = _T("");
        strFix.Format(_T("%d"), j+1);
        int i=0, nDL=0, nLL=0, nIL=0, nCF=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nCO=0;
        for(i=0; i<m_nDCount; i++)  nDL  += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(j), dMFactor, LoadCaseNo, rData, TRUE);
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount;   i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount;  i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor, LoadCaseNo, rData, 0);
        }
        if(strCode!=_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
        {
            if(m_nMCount>0 || m_nLCount>0)
            {
                for(i=0; i<m_nCfCount;  i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
            }
        }
        else nCF = 0;
        for(i=0; i<m_nEpCount; i++) nEP  += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL  += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP  += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP  += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF  += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++)nWPR += Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);
        for(i=0; i<m_nCoCount; i++) nCO  += Set_STLCIncludeCS(arCoLoad.GetAt(i), dCoFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T(""); 
        if(nDL  > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D"); csPrefix = _T("+");}
        if(m_nMCount>0) { rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFix + _T("]"); csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("L");  csPrefix = _T("+");}
            if(nIL>0) {rData.Description += csPrefix + GetFactorString(dIlFactor) + _T("IL"); csPrefix = _T("+");}
        }
        if(strCode!=_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
        {
            if(m_nMCount>0 || m_nLCount>0)
            {
                if(nCF>0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF");  csPrefix = _T("+");}
            }
        }
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");  csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP"); csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP"); csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF"); csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR");csPrefix = _T("+");}
        if(nCO > 0) {rData.Description += csPrefix + GetFactorString(dCoFactor) + _T("CO"); csPrefix = _T("+");}

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
            

			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
    }
}

void CLoadCombCtrl::Set_CvlDeadEpQW(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArINT& arBLoad, 
                    ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arCSLoad)		
{  // 이 함수는 Wind Load가 있는 경우만 쓰임
    // (KRTA-BRG, KSCE-USD, 2.2.2) : 1.3D + 1.7H + 1.3Q + 1.3W
    // (KSCE-RAIL-USD04,    3.3.3) : 1.4D + 1.7H + 1.4Q + 1.4W
    if(m_nWCount==0) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3,   dEpFactor=1.7, dBFactor=1.3, dWpFactor=1.3, dFpFactor=1.3, dSfFactor=1.3;
    double dWprFactor=1.3, dWFactor=1.3;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,   dEpFactor=1.7, dBFactor=1.4, dWpFactor=1.4, dFpFactor=1.4, dSfFactor=1.4;
        dWprFactor=1.4, dWFactor=1.4;
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;

    // DL, W는 항상포함
    for(int j=0; j<m_nWCount*2; j++)
    {
        strFix.Format(_T("%d"), j/2+1);
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nWL=0;
        for(i=0; i<m_nDCount; i++)   nDL  += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEpCount; i++)  nEP  += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL  += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++)  nWP  += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++)  nFP  += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF  += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++) nWPR += Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        double dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
        nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
                                                                                        
        rData.Description = _T("");
        CString csPrefix = _T("");
        if(nDL > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");  csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFix + _T("]");  csPrefix = _T("+");}    
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");  csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP"); csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP"); csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF"); csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR");csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
    
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+"); }
                else if(CheckCSEL(nErection, _T("W")))
                { rData.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);  
    }
}

void CLoadCombCtrl::Set_CvlDeadEpQWG(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArINT& arBLoad, 
                ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arStlLoad, 
                ArUNT& arSmLoad, ArINT& arCrLoad, ArINT& arShLoad, ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad)
{  // Wind Load(_T("W"))와 _T("G")가 있는 경우만 이 함수는 쓰임
    // (KRTA-BRG, KSCE-USD, 2.2.5) : 1.25D + 1.65H + 1.25Q + 1.25W + 1.25G
    // (KSCE-RAIL-USD04,    3.3.6) : 1.40D + 1.70H + 1.40Q + 1.40W + 1.40G
    if(m_nWCount==0 ||
        (m_nConstLoad==0 && m_nStlCount==0 && m_nSmCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nTCount==0 && m_nTpgCount==0)) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.25, dEpFactor=1.65, dBFactor=1.25, dWpFactor=1.25, dFpFactor=1.25, dSfFactor=1.25;
    double dWprFactor=1.25, dWFactor=1.25, dStlFactor=1.25, dSmFactor=1.25, dCrFactor=1.25, dShFactor=1.25;
    double dTFactor=1.25, dTpgFactor=1.25;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,   dEpFactor=1.7, dBFactor=1.4,   dWpFactor=1.4, dFpFactor=1.4, dSfFactor=1.4;
        dWprFactor=1.4, dWFactor=1.4,  dStlFactor=1.4, dSmFactor=1.4, dCrFactor=1.4, dShFactor=1.4;
        dTFactor=1.4,   dTpgFactor=1.4;
    }

    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    int nWCount   = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount  = max(m_nSmCount, 1);
    int nTCount   = max(m_nTCount,  1);
    int nTpgCount = max(m_nTpgCount,1);
    CString strFixW, strFixSm, strFixT, strFixTpg;

    // DL, W, G는 항상포함
    
    for(int j = 0; j < nWCount;   j++) {
    for(int k = 0; k < nSmCount;  k++) {
    for(int l = 0; l < nTCount;   l++) {
    for(int m = 0; m < nTpgCount; m++)
    {
        strFixW.Format(_T("%d"), j/2+1);  
        strFixSm.Format(_T("%d"), k+1);  
        strFixT.Format(_T("%d"), l+1);
        strFixTpg.Format(_T("%d"), m+1);
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nWL=0, nSTL=0, nCR=0, nSH=0, nTL=0, nTPG=0;
        for(i=0; i<m_nDCount; i++)   nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,   LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEpCount; i++)  nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,   LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++)  nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++)  nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++)  nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++) nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor, LoadCaseNo, rData, 0);
        double dWF = 1.0;
        if(m_nWCount>0)
        {
            dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
            nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nStlCount; i++) nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dStlFactor, LoadCaseNo, rData, 0);
        if(m_nSmCount > 0)           Set_SettleCase(arSmLoad.GetAt(k), dSmFactor,  LoadCaseNo, rData, TRUE); 
        for(i=0; i<m_nCrCount; i++)  nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dCrFactor,  LoadCaseNo, rData, D_SGLD_CS_CVL);
        for(i=0; i<m_nShCount; i++)  nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor,  LoadCaseNo, rData, D_SGLD_SS_CVL);
        if(m_nTCount > 0)            nTL += Set_STLCIncludeCS(arTLoad.GetAt(l),  dTFactor,   LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)          nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor, LoadCaseNo, rData, 0);

        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(n), dTpgFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("STL")))
                    Set_CStageCase(arCSLoad.GetAt(n), dStlFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dCrFactor,  LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dShFactor,  LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");
        CString csPrefix = _T("");
        if(nDL > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");   csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]");  csPrefix = _T("+");}    
        if(nCR > 0) {rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("CR");  csPrefix = _T("+");}
        if(nSH > 0) {rData.Description += csPrefix + GetFactorString(dShFactor) + _T("SH");  csPrefix = _T("+");}
        if(nTL > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]");   csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + GetFactorString(dTpgFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nTL > 0) {rData.Description += csPrefix + GetFactorString(dStlFactor) + _T("STL"); csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}
        if(m_nSmCount > 0) {rData.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]");csPrefix = _T("+");}      
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
             
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("T")) || CheckCSEL(nErection, _T("TPG")))
                { rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("STL")))
                { rData.Description += csPrefix + GetFactorString(dStlFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                { rData.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, n))
            { rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("(cCR)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, n))
            { rData.Description += csPrefix + GetFactorString(dShFactor) + _T("(cSH)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
}}}}}

void CLoadCombCtrl::Set_CvlDeadEpQWCo(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArINT& arBLoad, 
                    ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arWLoad, ArINT& arCoLoad, ArINT& arCSLoad)		
{  // 이 함수는 Wind Load(_T("W"))와 Collision Load(_T("CO"))가 있는 경우만 쓰임
    // (KRTA-BRG, KSCE-USD, 2.2.9 ) : 1.2D + 1.55H + 1.2Q + 1.2W + 1.2CO
    // (KSCE-RAIL-USD04,    3.3.10) : 1.2D + 1.50H + 1.2Q + 1.2W + 1.2CO
    if(m_nWCount==0 || m_nCoCount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.2,   dEpFactor=1.55, dBFactor=1.2, dWpFactor=1.2, dFpFactor=1.2, dSfFactor=1.2;
    double dWprFactor=1.2, dWFactor=1.2,   dCoFactor=1.2;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11")) dEpFactor=1.5;
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    
    // DL, W, CO 는 항상포함
    for(int j=0; j<m_nWCount*2; j++)
    {
        strFix.Format(_T("%d"), j/2+1);
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nWL=0, nCO=0;
        for(i=0; i<m_nDCount; i++)  nDL  += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEpCount; i++) nEP  += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL  += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP  += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP  += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF  += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++)nWPR += Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        double dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
        nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);    
        for(i=0; i<m_nCoCount; i++) nCO  += Set_STLCIncludeCS(arCoLoad.GetAt(i), dCoFactor, LoadCaseNo, rData, 0);
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
			 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
    
        rData.Description = _T("");
        CString csPrefix = _T("");    
        if(nDL > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");   csPrefix = _T("+");}
        if(nWL > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFix + _T("]");  csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP"); csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}
        if(nCO > 0) {rData.Description += csPrefix + GetFactorString(dCoFactor) + _T("CO");  csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            { rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
            

			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
				
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                { rData.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
    }
}

void CLoadCombCtrl::Set_CvlDeadMoveCfEpQWWlBrk(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad,
         ArINT& arCfLoad, ArINT& arEpLoad, ArINT& arBLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, 
         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arBrkLoad, ArINT& arBkLoad, ArINT& arCSLoad)
{
    //(KRTA-BRG, KSCE-USD, 2.2.3) : 1.3D + 1.3(L+I) + 1.3CF + 1.7H + 1.3Q + 1.3(0.5W + WL + BK)
    //(KSCE-RAIL-USD04,    3.3.4) : 1.4D + 1.4(L+I) + 1.4CF + 1.7H + 1.4Q + 1.4(0.5W + WL + SB + LR)
    if(m_nWCount==0 && m_nBrkCount==0) return;  // W와 Brk중 하나는 반드시 포함
    if(m_nConstLoad==0 && m_nLCount==0 && m_nMCount==0 && m_nWlCount==0 && m_nBrkCount==0) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.3, dMFactor=1.3, dIlFactor=1.3, dCfFactor=1.3, dEpFactor=1.7, dBFactor=1.3;
    double dWpFactor=1.3, dFpFactor=1.3, dSfFactor=1.3, dWprFactor=1.3, dWFactor=0.65, dWlFactor=1.3;
    double dBrkFactor=1.3, dBkFactor=0.;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,   dMFactor=1.4,  dIlFactor=1.4, dCfFactor=1.4,  dEpFactor=1.7, dBFactor=1.4;
        dWpFactor=1.4,  dFpFactor=1.4, dSfFactor=1.4, dWprFactor=1.4, dWFactor=0.7,  dWlFactor=1.4;
        dBrkFactor=1.4, dBkFactor=1.4;
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFixW, strFixM;

    int nMCount = max(m_nMCount, 1);
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
    // DL는 항상포함, W와 Brk중 하나는 반드시 포함. IL과 CF는 LL가 있는 경우만, WL는 W가 있는 경우만 포함  
    for(int j = 0; j < nWCount; j++) {
    for(int k = 0; k < nMCount; k++)
    {     
        strFixW.Format(_T("%d"), j/2+1);
        strFixM.Format(_T("%d"), k+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        int i=0, nDL=0, nLL=0, nIL=0, nCF=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nWL=0, nWLL=0, nBRK=0, nBK=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(k),  dMFactor,  LoadCaseNo, rData, TRUE);
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount;  i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount;  i++) nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount;i++) nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        double dWF = 1.0;
        if(m_nWCount > 0)
        {
            dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
            nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);                 
            for(i=0;i<m_nWlCount;i++)  nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i), dWlFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nBrkCount; i++) nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor, LoadCaseNo, rData, 0);
        if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
        {
            for(i=0; i<m_nBkCount; i++) nBK += Set_STLCIncludeCS(arBkLoad.GetAt(i), dBkFactor, LoadCaseNo, rData, 0);
        }
        else nBK = 0;
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(n), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(n), dWFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
        rData.Description = _T("");
        CString csPrefix = _T("");
        if(nDL  > 0)  {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");   csPrefix = _T("+");}
        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+");}       
        if(m_nLCount > 0)
        {
            if(nLL > 0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("L");  csPrefix = _T("+");}
            if(nIL > 0) {rData.Description += csPrefix + GetFactorString(dIlFactor) + _T("IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF>0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF");  csPrefix = _T("+");}
        }
        if(m_nWCount > 0) 
        {
            if(nWL > 0)
            {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nWLL > 0)
            {rData.Description += csPrefix + GetFactorString(dWlFactor) + _T("WL");  csPrefix = _T("+");}
        }
        if(nEP > 0)  {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0)  {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");   csPrefix = _T("+");}
        if(nWP > 0)  {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0)  {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0)  {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0)  {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}
        if(nBRK> 0)  {rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}
        if(nBK > 0)  {rData.Description += csPrefix + GetFactorString(dBkFactor)  + _T("BK"); csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
             
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 

                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL;  csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                {rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                {
                    if(nWL>0 && (nWLL > 0 || nBRK > 0))
                    { rData.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+");}
                    else
                    { rData.Description += csPrefix + GetFactorString(dWlFactor) + strcEL; csPrefix = _T("+");}
                }
            }
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);        
}}}

void CLoadCombCtrl::Set_CvlDeadMoveCfEpQWWlBrkG(CString strCode, ArINT& arDLoad, ArUNT& arMLoad, ArINT& arLLoad, ArINT& arIlLoad,
         ArINT& arCfLoad, ArINT& arEpLoad, ArINT& arBLoad, ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, 
         ArINT& arWLoad, ArINT& arWlLoad, ArINT& arBrkLoad, ArINT& arBkLoad, ArINT& arStlLoad, ArUNT& arSmLoad, ArINT& arCrLoad, 
         ArINT& arShLoad, ArINT& arTLoad, ArINT& arTpgLoad, ArINT& arCSLoad)
{ 
    // (KRTA-BRG, KSCE-USD, 2.2.6) 1.25D + 1.25(L+I) + 1.25CF + 1.65H + 1.25Q + 1.25(0.5W + WL + BK) +1.25G
    // (KSCE-RAIL-USD04,    3.3.7) 1.40D + 1.40(L+I) + 1.40CF + 1.70H + 1.40Q + 1.40(0.5W + WL + SB + LR) +1.40G
    if((m_nConstLoad==0 && m_nStlCount==0 && m_nSmCount==0 && m_nCrCount==0 && m_nShCount==0 && m_nTCount==0
         && m_nTpgCount==0) || (m_nWCount==0 && m_nBrkCount==0)) return;

    int LoadCaseNo = 0, nnn=0;
    T_LCOM_D rData;
    double dDFactor=1.25, dMFactor=1.25, dIlFactor=1.25, dCfFactor=1.25, dEpFactor=1.65, dBFactor=1.25;
    double dWpFactor=1.25, dFpFactor=1.25, dSfFactor=1.25, dWprFactor=1.25, dWFactor=0.625, dWlFactor=1.25;
    double dBrkFactor=1.25, dBkFactor=0., dStlFactor=1.25, dSmFactor=1.25, dCrFactor=1.25, dShFactor=1.25;
    double dTFactor=1.25, dTpgFactor=1.25;
    if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
    {
        dDFactor=1.4,   dMFactor=1.4,  dIlFactor=1.4,  dCfFactor=1.4,  dEpFactor=1.7, dBFactor=1.4;
        dWpFactor=1.4,  dFpFactor=1.4, dSfFactor=1.4,  dWprFactor=1.4, dWFactor=0.7,  dWlFactor=1.4;
        dBrkFactor=1.4, dBkFactor=1.4, dStlFactor=1.4, dSmFactor=1.4,  dCrFactor=1.4, dShFactor=1.4;
        dTFactor=1.4,   dTpgFactor=1.4;
    }
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    int nWCount   = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount  = max(m_nSmCount,  1);
    int nTCount   = max(m_nTCount,   1);
    int nTpgCount = max(m_nTpgCount, 1);
    CString strFixW, strFixM, strFixSm, strFixT, strFixTpg;

    int nMCount = max(m_nMCount, 1);
    for(int j = 0; j < nWCount;   j++) {
    for(int l = 0; l < nMCount;   l++) {
    for(int k = 0; k < nSmCount;  k++) {
    for(int n = 0; n < nTCount;   n++) {
    for(int m = 0; m < nTpgCount; m++)   // Temperature Gradient는 각각 고려
    {
        strFixW.Format(_T("%d"), j/2+1);
        strFixM.Format(_T("%d"), l+1);
        strFixSm.Format(_T("%d"), k+1);
        strFixT.Format(_T("%d"), n+1);
        strFixTpg.Format(_T("%d"), m+1);
        rData.Initialize();  
        LoadCaseNo = 0;
        
        int i=0, nDL=0, nLL=0, nIL=0, nCF=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nWL=0, nWLL=0;
        int nBRK=0, nBK=0, nSTL=0, nCR=0, nSH=0, nTL=0, nTPG=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        if(m_nMCount>0) Set_MovingCase(arMLoad.GetAt(l),  dMFactor,  LoadCaseNo, rData, TRUE);        
        if(m_nLCount>0)
        {
            for(i=0; i<m_nLCount;  i++) nLL += Set_STLCIncludeCS(arLLoad.GetAt(i),  dMFactor,  LoadCaseNo, rData, 0);
            for(i=0; i<m_nIlCount; i++) nIL += Set_STLCIncludeCS(arIlLoad.GetAt(i), dIlFactor, LoadCaseNo, rData, 0);
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            for(i=0; i<m_nCfCount; i++) nCF += Set_STLCIncludeCS(arCfLoad.GetAt(i), dCfFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++)nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);
        double dWF = 1.0;
        if(m_nWCount>0)
        {
            dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
            nWL += Set_STLCIncludeCS(arWLoad.GetAt(j/2), dWF, LoadCaseNo, rData, 0);
            for(i=0;i<m_nWlCount;i++) nWLL+= Set_STLCIncludeCS(arWlLoad.GetAt(i), dWlFactor, LoadCaseNo, rData, 0);
        }
        for(i=0; i<m_nBrkCount; i++)nBRK+= Set_STLCIncludeCS(arBrkLoad.GetAt(i), dBrkFactor,LoadCaseNo, rData, 0);
        if(strCode==_T("KSCE-RAIL-USD04") || strCode==_T("KSCE-RAIL-USD11"))
        {
            for(i=0; i<m_nBkCount; i++) nBK += Set_STLCIncludeCS(arBkLoad.GetAt(i), dBkFactor,LoadCaseNo, rData, 0);
        }
        else nBK = 0;
        for(i=0; i<m_nStlCount; i++)nSTL+= Set_STLCIncludeCS(arStlLoad.GetAt(i),dStlFactor, LoadCaseNo, rData, 0);
        if(m_nSmCount > 0)          Set_SettleCase(arSmLoad.GetAt(k), dSmFactor,  LoadCaseNo, rData, TRUE); 
        for(i=0; i<m_nCrCount; i++) nCR += Set_STLCIncludeCS(arCrLoad.GetAt(i), dCrFactor,  LoadCaseNo, rData, D_SGLD_CS_CVL);
        for(i=0; i<m_nShCount; i++) nSH += Set_STLCIncludeCS(arShLoad.GetAt(i), dShFactor,  LoadCaseNo, rData, D_SGLD_SS_CVL);
        if(m_nTCount > 0)           nTL += Set_STLCIncludeCS(arTLoad.GetAt(n),  dTFactor,   LoadCaseNo, rData, 0);
        if(m_nTpgCount > 0)         nTPG+= Set_STLCIncludeCS(arTpgLoad.GetAt(m),dTpgFactor, LoadCaseNo, rData, 0);

        if(m_nConstLoad!=0) // ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn),  dDFactor,  LoadCaseNo, rData, TRUE);

			CString strcEL;
			int nErection = 0;
			
            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dDFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("L")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dMFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("W")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dWFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("T")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dTFactor, LoadCaseNo, rData, TRUE);
                else if(CheckCSEL(nErection, _T("TPG")))
                    Set_CStageCase(arCSLoad.GetAt(nnn), dTpgFactor, LoadCaseNo, rData, TRUE);
                    
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn), dCrFactor, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn), dShFactor, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
                Set_CStageCase(arCSLoad.GetAt(nnn), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");
        CString csPrefix = _T("");
        if(nDL  > 0) {rData.Description += csPrefix + GetFactorString(dDFactor) + _T("D");    csPrefix = _T("+");}
        if(m_nMCount>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}
        if(m_nLCount>0)
        {
            if(nLL>0) {rData.Description += csPrefix + GetFactorString(dMFactor) + _T("L");  csPrefix = _T("+");}
            if(nIL>0) {rData.Description += csPrefix + GetFactorString(dIlFactor) + _T("IL"); csPrefix = _T("+");}
        }
        if(m_nMCount>0 || m_nLCount>0)
        {
            if(nCF>0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF");  csPrefix = _T("+");}
        }
        if(m_nWCount > 0) 
        {
            if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nWLL > 0) {rData.Description += csPrefix + GetFactorString(dWlFactor) + _T("WL"); csPrefix = _T("+");}
        }
        if(nTL > 0) {rData.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]");   csPrefix = _T("+");}
        if(nTPG> 0) {rData.Description += csPrefix + GetFactorString(dTpgFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+");}
        if(nSTL> 0) {rData.Description += csPrefix + GetFactorString(dStlFactor) + _T("STL");  csPrefix = _T("+");}
        if(nCR > 0) {rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("CR");   csPrefix = _T("+");} 
        if(nSH > 0) {rData.Description += csPrefix + GetFactorString(dShFactor) + _T("SH");   csPrefix = _T("+");}
        if(nCF > 0) {rData.Description += csPrefix + GetFactorString(dCfFactor) + _T("CF");  csPrefix = _T("+");}       
        if(nEP > 0) {rData.Description += csPrefix + GetFactorString(dEpFactor) + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + GetFactorString(dBFactor) + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + GetFactorString(dWpFactor) + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + GetFactorString(dFpFactor) + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + GetFactorString(dSfFactor) + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + GetFactorString(dWprFactor) + _T("WPR"); csPrefix = _T("+");}
        if(nBRK> 0) {rData.Description += csPrefix + GetFactorString(dBrkFactor) + _T("BRK"); csPrefix = _T("+");}
        if(nBK > 0) {rData.Description += csPrefix + GetFactorString(dBkFactor)  + _T("BK");  csPrefix = _T("+");}
        if(m_nSmCount > 0) {rData.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}     

        if(m_nConstLoad!=0) // ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
            { rData.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
            
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                { rData.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("L")))
                { rData.Description += csPrefix + GetFactorString(dMFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("T"))  || CheckCSEL(nErection, _T("TPG")))
                { rData.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");}
                else if(CheckCSEL(nErection, _T("W")))
                {
                    if(nWLL > 0 || nBRK > 0)
                    { rData.Description += csPrefix + GetFactorString(dWlFactor) + strcEL; csPrefix = _T("+"); }
                    else
                    { rData.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
                }
            }
            if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
            { rData.Description += csPrefix + GetFactorString(dCrFactor) + _T("(cCR)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
            { rData.Description += csPrefix + GetFactorString(dShFactor) + _T("(cSH)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }

        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR); 
}}}}}}

void CLoadCombCtrl::Set_CvlDeadEpQE(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArINT& arBLoad, 
                        ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArINT& arELoad, ArINT& arCSLoad)		
{// 이 함수는 Seismic Load가 있는 경우만 쓰임  
    // (KRTA-BRG, KSCE-USD, 2.2.7) : 1.0(D + H + Q + E)
    // (KSCE-RAIL-USD04,    3.3.8) : 1.0(D + H + Q + E)
    if(m_nECount==0) return;

    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.0, dEpFactor=1.0, dBFactor=1.0, dWpFactor=1.0, dFpFactor=1.0, dSfFactor=1.0;
    double dWprFactor=1.0, dEFactor = 1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;

    // DL, E는 항상포함
    for(int j=0; j<m_nECount*2; j++)   // seismic load는 각각 고려
    {
        strFix.Format(_T("%d"), j/2+1);
        rData.Initialize();  
        LoadCaseNo = 0;

        int i=0, nDL=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0, nEL=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++)nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        double dEF = (j%2==0) ? dEFactor : -1. * dEFactor;
        nEL += Set_STLCIncludeCS(arELoad.GetAt(j/2), dEF, LoadCaseNo, rData, 0);
        
        if(m_nConstLoad!=0) // CS or ST_CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
            
			
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("E")))
                    Set_CStageCase(arCSLoad.GetAt(n), 1.0, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }
                
        rData.Description = _T("");
        CString csPrefix = _T("");  
        
        if(nDL > 0) {rData.Description += csPrefix + _T("D");   csPrefix = _T("+");}
        if(nEL > 0) {if(dEF<0.) csPrefix=_T(""); rData.Description += csPrefix + GetFactorString(dEF)+_T("E[") + strFix + _T("]"); csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + _T("EP");  csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + _T("B");   csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + _T("WP");  csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + _T("FP");  csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("SF");  csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + _T("WPR"); csPrefix = _T("+");}
        if(m_nConstLoad!=0) // CS or ST_CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
             
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) || CheckCSEL(nErection, _T("E")))
                    {rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
    }
}

void CLoadCombCtrl::Set_CvlDeadEpQEsp(CString strCode, ArINT& arDLoad, ArINT& arEpLoad, ArINT& arBLoad, 
                        ArINT& arWpLoad, ArINT& arFpLoad, ArINT& arSfLoad, ArINT& arWprLoad, ArUNT& arEspLoad, ArINT& arCSLoad)		
{// 이 함수는 response spectrum load가 있는 경우만 쓰임  
    // (KRTA-BRG, KSCE-USD, 2.2.7) : 1.0(D + H + Q + E)
    // (KSCE-RAIL-USD04,    3.3.8) : 1.0(D + H + Q + E)
    if(m_nEspCount==0) return;
    
    int LoadCaseNo = 0, n=0;
    T_LCOM_D rData;
    double dDFactor=1.0, dEpFactor=1.0, dBFactor=1.0, dWpFactor=1.0, dFpFactor=1.0, dSfFactor=1.0;
    double dWprFactor=1.0, dEspFactor = 1.0;
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    CString strFix;
    CString strScaleUpFactor;

    // DL, E는 항상포함
    for(int j=0; j<m_nEspCount*2; j++)
    {
        strFix.Format(_T("%d"), j/2+1);
        double dScaleUpFactor=1.0;
        Get_ScaleUpFactor(D_LOADCASE_SPECTRUM, arEspLoad.GetAt(j/2), dScaleUpFactor);

        rData.Initialize();  
        LoadCaseNo = 0;
        int i=0, nDL=0, nEP=0, nBL=0, nWP=0, nFP=0, nSF=0, nWPR=0;
        for(i=0; i<m_nDCount; i++)  nDL += Set_STLCIncludeCS(arDLoad.GetAt(i),  dDFactor,  LoadCaseNo, rData, D_SGLD_DL_CVL);
        for(i=0; i<m_nEpCount; i++) nEP += Set_STLCIncludeCS(arEpLoad.GetAt(i), dEpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nBCount; i++)  nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  dBFactor,  LoadCaseNo, rData, 0);
        for(i=0; i<m_nWpCount; i++) nWP += Set_STLCIncludeCS(arWpLoad.GetAt(i), dWpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nFpCount; i++) nFP += Set_STLCIncludeCS(arFpLoad.GetAt(i), dFpFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nSfCount; i++) nSF += Set_STLCIncludeCS(arSfLoad.GetAt(i), dSfFactor, LoadCaseNo, rData, 0);
        for(i=0; i<m_nWprCount; i++)nWPR+= Set_STLCIncludeCS(arWprLoad.GetAt(i),dWprFactor,LoadCaseNo, rData, 0);

        double dEspF = (j%2==0) ? dEspFactor : -1. * dEspFactor;
		Set_SpectrumCase(arEspLoad.GetAt(j/2), dEspF*dScaleUpFactor, LoadCaseNo, rData, TRUE);

        if(m_nConstLoad!=0) // ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n),  dDFactor,  LoadCaseNo, rData, TRUE);
             
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                    Set_CStageCase(arCSLoad.GetAt(n), dDFactor, LoadCaseNo, rData, TRUE);
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPST, LoadCaseNo, rData, TRUE);
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
                Set_CStageCase(arCSLoad.GetAt(n), dPSS, LoadCaseNo, rData, TRUE);
        }

        rData.Description = _T("");
        CString csPrefix = _T("");    
        if(nDL > 0) {rData.Description += csPrefix + _T("D");  csPrefix = _T("+");}
        if(nEP > 0) {rData.Description += csPrefix + _T("EP"); csPrefix = _T("+");}
        if(nBL > 0) {rData.Description += csPrefix + _T("B");  csPrefix = _T("+");}
        if(nWP > 0) {rData.Description += csPrefix + _T("WP"); csPrefix = _T("+");}
        if(nFP > 0) {rData.Description += csPrefix + _T("FP"); csPrefix = _T("+");}
        if(nSF > 0) {rData.Description += csPrefix + _T("SF"); csPrefix = _T("+");}
        if(nWPR> 0) {rData.Description += csPrefix + _T("WPR");csPrefix = _T("+");}
        if(dEspF<0.0) csPrefix = _T("");
        rData.Description += csPrefix + GetFactorString(dEspF*dScaleUpFactor) + _T("ESP[") + strFix + _T("]"); csPrefix = _T("+");
        
        if(m_nConstLoad!=0) // ST+CS
        {
            if(CheckCS_SgldK(D_SGLD_DL_CVL, n))
            {rData.Description += csPrefix + _T("(cD)"); csPrefix = _T("+");}
             
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], n)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 
            
                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
                {rData.Description += csPrefix + strcEL; csPrefix = _T("+");}
            }
            if(CheckCS_SgldK(D_SGLD_TP_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPST) + _T("(cTS)"); csPrefix = _T("+");}
            if(CheckCS_SgldK(D_SGLD_TS_CVL, n))
            {rData.Description += csPrefix + GetFactorString(dPSS) + _T("(cTS)"); csPrefix = _T("+");}
        }
        if(LoadCaseNo > 0) Set_LoadComb4Civil(rData, D_STR);
    }
}

