BOOL CLoadCombCtrl::GetAdditionalMsg(CString &strMsg, int nMsgType)
{
    // 일단 중국 JTG D60-04에만 있다.
    CString strAdd = _T("");
    switch(nMsgType)
    {
    case 101: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_BASD); break; // JTG D60-04, 기본조합(영구하중)
    case 102: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_ACDD); break; // JTG D60-04, 우연조합(영구하중)
    case 103: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_BASE); break; // JTG D60-04, 기본조합
    case 104: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_ACDN); break; // JTG D60-04, 우연조합
    case 105: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_LMTD); break; // JTG D60-04, 극한조합(영구하중)
    case 106: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_LONG); break; // JTG D60-04, 장기조합
    case 107: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_SHRT); break; // JTG D60-04, 단기조합
    case 108: strAdd = _LS(IDS_CMD_LCOM_JTGD6004_ELST); break; // JTG D60-04, 탄성단계응력검토조합
    case 109: strAdd = _LS(IDS_CMD_LCOM_TB10002_1_MAIN);         break; // TB 10002.1-2005,  (CHINA Railway)
    case 110: strAdd = _LS(IDS_CMD_LCOM_TB10002_1_MAINADDITION); break; // TB 10002.1-2005,  (CHINA Railway)
    case 111: strAdd = _LS(IDS_CMD_LCOM_TB10002_1_MAINSPECIAL);  break; // TB 10002.1-2005,  (CHINA Railway)
    case 112: strAdd = _LS(IDS_CMD_LCOM_JTGD6015_BASD); break;//JTG D60-15 샘굶莉북(湛씹뵐潼)
    case 113: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_ACDD);break;//JTG D60-15 탉횔莉북(湛씹뵐潼)
    case 114: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_BASE);break;//JTG D60-15 샘굶
    case 115: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_ACDN);break;//JTG D60-15 탉횔
    case 116: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_LMTD);break;//JTG D60-15 섐掘莉북(湛씹뵐潼)
    case 117: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_LONG);break;//JTG D60-15 硫湛씹
    case 118: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_SHRT);break;//JTG D60-15 틉島
    case 119: strAdd =_LS(IDS_CMD_LCOM_JTGD6015_ELST);break;//JTG D60-15 깃硫
    default: break;
    }

    if(!strAdd.IsEmpty()) strMsg = strAdd + strMsg;

    return TRUE;
}

