    int  nLcomSize = aLcomD.GetSize();
    int  nConLivLcomSize = 0;
    CString strPos = _T(""); 

    T_LCOM_D LcomD ;LcomD.Initialize();
    int LoadCaseNo = 0;  LcomD.nActive = 1; // Active or Strength/Stress
    if(m_nLcomType == D_LCOMTYPE_CONCRETE) LcomD.nActive = 3;  // Main Force


