    if(nSlCount==0 && nNlCount==0  && nSNlCount==0 && nMCount==0 && nIlCount==0 && nCfCount==0 && nLCount==0 && nCrlCount == 0){
        //		if (nLcomSize >0) arConLivData.Copy(arConData);
        return FALSE;
    }

    int nM=0, nIL=0, nCF=0, nL=0, nCRL=0;  CString strDesc =_T("");
