BOOL CLoadCombCtrl::SetCvlEurocode4_Traffic(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
																			ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
																			ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
														          ArINT &arCSLoad,ArUNT &arPsi1FactorMLoad1,ArUNT &arPsi1FactorMLoad2, BOOL bAccompay/*=FALSE*/)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 || m_nEsCount>0 ||
        m_nElCount>0 || m_nCrCount>0 || m_nShCount>0 || m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;
	int nMCount = max(m_nLeadingMCount, 1);
	if (m_nEC4LVarTraffType == 0 && bAccompay)
	{
		nMCount = m_nAccompanyMCount;
	}

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
    int nBreakCount = (m_nBrkCount > 0 && m_nBkCount > 0) ? 2 : 1; // CIVIL-7875

	double dDFactor = 1.35;
	double dLFactor = m_nEC4LVarTraffType == 0 ? 1.35 : 1.45;
    if (m_nEC4LVarTraffType == 0 && bAccompay)
    {
        dLFactor *= 0.75;
    }
    double dLLFactor = 1.35;

	double dPsFactor = 1.3;
	double dWFactor = m_nEC4LVarTraffType == 0 ? 0.6*1.5 : 1.5*0.75;
    double dPsi1Factor = 0.8;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) 
        {
            dDFactor  = (d==0) ? 1.35 : 1.0;
            dLLFactor = (d==0) ? 1.35 : 1.0;
        }
		else           
        {
            dDFactor  = (m_nEC4Permanent==0) ? 1.0 : 1.35;
            dLLFactor = 1.0;
        }
		
		for(int i=0; i<nMCount; ++i) {
		for(int p=0; p<nPsCount; ++p)
		{
            if(nPsCount==2) dPsFactor = (p==0) ? 1.3 : 1.0;
			else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

			for(int j=0; j<nWCount; ++j) {
			for(int k=0; k<nSmCount; ++k) {
            for(int nBreak = 0; nBreak < nBreakCount; ++nBreak ) {
				nSmIndex = k;
				if(m_nEC4Settlement==2)
				{
					dSmFactor = (k%2==0) ? 1.35 : 1.0;
					nSmIndex = k/2;
				}
				
				int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
				int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
				int nPS=0, nWL=0, nWLL=0, nTL=0, nSL=0;

                BOOL bLeadingMCount = FALSE;
                BOOL bPsi1FactorMLoad1 = FALSE;
                BOOL bPsi1FactorMLoad2 = FALSE;
				LcomD.Initialize();
				LcomD.nActive = 1;
				LoadCaseNo = 0;
                for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
				for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                // 김정인 과장님 요청 20090728 - jhyun
                if(m_nEC4LVarTraffType == 0)
                {
                    BOOL bChk = FALSE;
                    if      (!bAccompay && m_nLeadingMCount   > 0) bChk = TRUE;
                    else if ( bAccompay && m_nAccompanyMCount > 0) bChk = TRUE;

                    if(bChk)
                    {
                        bLeadingMCount = TRUE;
                        Set_MovingCase(arLeadingMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                        for(ld=0; ld<m_nCfCount;  ++ld) nCF  += Set_STLCIncludeCS(arCfLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);

                        for(ld=0; ld<m_nLCount; ++ld) nLL += Set_STLCIncludeCS(arLLoad[ld], dLLFactor, LoadCaseNo, LcomD, 0);

                        if ( nBreakCount > 1 )
                        {
                            if ( nBreak == 0 )      { for(ld=0; ld<m_nBrkCount; ++ld) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                            else if ( nBreak == 1 ) { for(ld=0; ld<m_nBkCount;  ++ld) nBK  += Set_STLCIncludeCS(arBkLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0); }
                            else ASSERT(0);
                        }
                        else
                        {
                            for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                            for ( ld = 0; ld < m_nBkCount; ++ld )  nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                        }
                    }
                }
                else
                {
                    //for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld) Set_MovingCase(arPsi1FactorMLoad2[ld], dLFactor, LoadCaseNo, LcomD, TRUE);
                    for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld)
                    {
                        if(arLeadingMLoad[i] == arPsi1FactorMLoad2[ld])
                        { 
                            bPsi1FactorMLoad2 = TRUE;
                            Set_MovingCase(arPsi1FactorMLoad2[ld], dLFactor, LoadCaseNo, LcomD, TRUE); 
                        }
                    }
                }
                for(ld=0; ld<m_nPsCount;  ++ld) nPS  += Set_STLCIncludeCS(arPsLoad[ld],  dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
				double dWF = 1.0;
				if(m_nWCount>0)
				{
					dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
					nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
					for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
				}
				if(m_nSmCount > 0) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
					
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
							Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
						else if(CheckCSEL(nErection, _T("W")))
							Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
				}

				// description
				LcomD.Description.Empty();
				csPrefix.Empty();
				strFixM.Format(_T("%d"), i+1);
				strFixW.Format(_T("%d"), j/2+1);
				strFixSm.Format(_T("%d"), nSmIndex+1);

				if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
				{
					LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
					csPrefix = _T("+");
				}
				if(bLeadingMCount || bPsi1FactorMLoad1 || bPsi1FactorMLoad2) 
                {
                    LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");
                }
                if(nLL>0) { LcomD.Description += csPrefix + GetFactorString(dLLFactor) + _T("LL"); csPrefix = _T("+"); }
				if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
				if(m_nWCount > 0) 
				{
					if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
					if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
				}
				if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
                if ( nBRK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BRK"); csPrefix = _T("+"); }
                if ( nBK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BK"); csPrefix = _T("+"); }
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}

					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
						{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
						else if(CheckCSEL(nErection, _T("W")))
						{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
				}
				if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_STR);
			}
		}
	}}}}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Traffic_Therm(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
    ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
    ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
    ArINT &arCSLoad, ArINT &arTLoad, ArINT &arTpgLoad, BOOL bAccompay/*=FALSE*/)
{
    T_LCOM_D LcomD;

    int nDCount = 1;
    BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 || m_nEsCount>0 ||
        m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
    if ( bExistD && m_nEC4Permanent==2 ) nDCount = 2;
    int nMCount = max(m_nLeadingMCount, 1);
	if (m_nEC4LVarTraffType == 0 && bAccompay)
	{
		nMCount = m_nAccompanyMCount;
	}

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nTCount = (m_nTCount>0) ? m_nTCount : 1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
    int nBreakCount = (m_nBrkCount > 0 && m_nBkCount > 0) ? 2 : 1; // CIVIL-7875
    int nSmIndex = 0;

    double dDFactor = 1.35;
    double dLFactor = m_nEC4LVarTraffType == 0 ? 1.35 : 1.45;
	if (m_nEC4LVarTraffType == 0 && bAccompay)
	{
		dLFactor *= 0.75;
	}
    double dLLFactor = 1.35;

    double dPsFactor = 1.3;
    double dWFactor = m_nEC4LVarTraffType == 0 ? 0.6*1.5 : 1.5*0.75;
    double dPsi1Factor = 0.8;
    double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
    double dTFactor = 0.9;
    CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));

    int LoadCaseNo=0, ld=0, nnn=0;
    for ( int d=0; d<nDCount; ++d )
    {
        if ( nDCount==2 ) 
        {
            dDFactor  = (d==0) ? 1.35 : 1.0;
            dLLFactor = (d == 0) ? 1.35 : 1.0;
        }
        else
        {
            dDFactor  = (m_nEC4Permanent==0) ? 1.0 : 1.35;
            dLLFactor = 1.0;
        }

        for ( int i=0; i<nMCount; ++i ) 
        {
            for ( int p=0; p<nPsCount; ++p )
            {
                if ( nPsCount==2 ) dPsFactor = (p==0) ? 1.3 : 1.0;
                else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

                for ( int j=0; j<nWCount; ++j ) 
                {
                    for ( int k=0; k<nSmCount; ++k )
                    {
                        for ( int l = 0; l<nTCount; ++l )
                        {
                            for ( int m = 0; m < nTpgCount; ++m ) {
                                for ( int nBreak = 0; nBreak < nBreakCount; ++nBreak ) {
                                    nSmIndex = k;
                                    if ( m_nEC4Settlement == 2 )
                                    {
                                        dSmFactor = (k % 2 == 0) ? 1.35 : 1.0;
                                        nSmIndex = k / 2;
                                    }

                                    int nDL = 0, nDD = 0, nEP = 0, nES = 0, nEL = 0, nCR = 0, nSH = 0;
                                    int nLL = 0, nIL = 0, nLS = 0, nLP = 0, nILP = 0, nCF = 0, nBRK = 0, nBK = 0, nCRL = 0;
                                    int nPS = 0, nWL = 0, nWLL = 0, nTL = 0, nSL = 0, nTpg = 0;

                                    BOOL bLeadingMCount = FALSE;
                                    BOOL bPsi1FactorMLoad1 = FALSE;
                                    BOOL bPsi1FactorMLoad2 = FALSE;
                                    LcomD.Initialize();
                                    LcomD.nActive = 1;
                                    LoadCaseNo = 0;
                                    for ( ld = 0; ld < m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                                    for ( ld = 0; ld < m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                                    for ( ld = 0; ld < m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                                    for ( ld = 0; ld < m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                                    for ( ld = 0; ld < m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                                    for ( ld = 0; ld < m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                                    for ( ld = 0; ld < m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);

                                    if ( m_nTCount > 0 ) nTL += Set_STLCIncludeCS(arTLoad[l], dTFactor, LoadCaseNo, LcomD, 0);
                                    if ( m_nTpgCount > 0 ) nTpg += Set_STLCIncludeCS(arTpgLoad[m], dTFactor, LoadCaseNo, LcomD, 0);

									// 김정인 과장님 요청 20090728 - jhyun
									if (m_nEC4LVarTraffType == 0)
                                    {
                                        BOOL bChk = FALSE;
                                        if      (!bAccompay && m_nLeadingMCount   > 0) bChk = TRUE;
                                        else if ( bAccompay && m_nAccompanyMCount > 0) bChk = TRUE;

                                        if (bChk && m_nLeadingMCount > 0 )
                                        {
                                            bLeadingMCount = TRUE;
                                            Set_MovingCase(arLeadingMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                                            for ( ld = 0; ld < m_nCfCount; ++ld ) nCF += Set_STLCIncludeCS(arCfLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);

                                            for (ld = 0; ld < m_nLCount; ++ld) nLL += Set_STLCIncludeCS(arLLoad[ld], dLLFactor, LoadCaseNo, LcomD, 0);

                                            if ( nBreakCount > 1 )
                                            {
                                                if ( nBreak == 0 ) { for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                                                else if ( nBreak == 1 ) { for ( ld = 0; ld < m_nBkCount;  ++ld ) nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                                                else ASSERT(0);
                                            }
                                            else
                                            {
                                                for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                                                for ( ld = 0; ld < m_nBkCount; ++ld )  nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                                            }
                                        }
                                    }
                                    else
                                    {
                                        ASSERT(0); //여기 안들어올껄? 좀 지우자.. 데드코드들은.
                                    }

                                    for ( ld = 0; ld < m_nPsCount; ++ld ) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                                    double dWF = 1.0;
                                    if ( m_nWCount > 0 )
                                    {
                                        dWF = (j % 2 == 0) ? dWFactor : -1. * dWFactor;
                                        nWL += Set_STLCIncludeCS(arWLoad[j / 2], dWF, LoadCaseNo, LcomD, 0);
                                        for ( ld = 0; ld < m_nWlCount; ++ld ) nWLL += Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
                                    }
                                    if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
                                    if ( m_nConstLoad != 0 ) // ST+CS
                                    {
                                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                                        CString strcEL;
                                        int nErection = 0;

                                        for ( int nErec = 0; nErec < D_STCT_EREC_MAX_CVL; ++nErec )
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                            // 						else if(CheckCSEL(nErection, _T("L")))
                                            // 							Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
                                            else if ( CheckCSEL(nErection, _T("W")) )
                                                Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
                                        }
                                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                            Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                                    }

                                    // description
                                    LcomD.Description.Empty();
                                    csPrefix.Empty();
                                    strFixM.Format(_T("%d"), i + 1);
                                    strFixW.Format(_T("%d"), j / 2 + 1);
                                    strFixSm.Format(_T("%d"), nSmIndex + 1);
                                    strFixT.Format(_T("%d"), l + 1);
                                    strFixTpg.Format(_T("%d"), m + 1);

                                    if ( nDL > 0 || nDD > 0 || nEP > 0 || nES > 0 || nEL > 0 || nCR > 0 || nSH > 0 )
                                    {
                                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                                        csPrefix = _T("+");
                                    }
                                    if ( bLeadingMCount || bPsi1FactorMLoad1 || bPsi1FactorMLoad2 )
                                    {
                                        LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+");
                                    }
                                    if (nLL > 0) { LcomD.Description += csPrefix + GetFactorString(dLLFactor) + _T("LL"); csPrefix = _T("+"); }

                                    if ( nPS > 0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                                    if ( m_nWCount > 0 )
                                    {
                                        if ( nWL > 0 ) { if ( dWF < 0. ) csPrefix = _T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+"); }
                                        if ( nWLL > 0 ) { LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+"); }
                                    }
                                    if ( nTL > 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                                    if ( nTpg > 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                                    if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                                    if ( nBRK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BRK"); csPrefix = _T("+"); }
                                    if ( nBK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BK"); csPrefix = _T("+"); }
                                    if ( m_nConstLoad != 0 ) // ST+CS
                                    {
                                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                        {
                                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                                        }

                                        CString strcEL;
                                        int nErection = 0;

                                        for ( int nErec = 0; nErec < D_STCT_EREC_MAX_CVL; ++nErec )
                                        {
                                            strcEL = _T(""); nErection = 0;
                                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                            {
                                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                                            }
                                            else if ( CheckCSEL(nErection, _T("W")) )
                                            {
                                                LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+");
                                            }
                                        }
                                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                        {
                                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                                        }
                                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                        {
                                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                                        }
                                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                        {
                                            LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                                        }
                                    }
                                    if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_STR);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Wind1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
													 ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArUNT &arMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
													 ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
													 ArINT &arCSLoad,ArUNT &arIgnorePsi1FactorMLoad, BOOL bETC)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 || 
		              m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

	int nMCount = max(m_nMCount, 1);
    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
	int nTCount = (m_nThermalCount>0) ? m_nThermalCount*2 : 1;

	double dDFactor = 1.35;
	double dPsFactor = 1.3;
	double dWFactor = (bETC) ? 0.6*1.5 : 1.5;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dLFactor = m_nEC4LVarTraffType == 0 ? 1.35 : 1.45 * 0.8;
	CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
		else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

		for(int i=0; i<nMCount; ++i) {
		for(int p=0; p<nPsCount; ++p)
		{
            if(nPsCount==2) dPsFactor = (p==0) ? 1.3 : 1.0;
			else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

			for(int j=0; j<nWCount; ++j) {
			for(int k=0; k<nSmCount; ++k)
			{
				nSmIndex = k;
				if(m_nEC4Settlement==2)
				{
					dSmFactor = (k%2==0) ? 1.35 : 1.0;
					nSmIndex = k/2;
				}

				int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
				int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
				int nPS=0, nWL=0, nWLL=0;

				LcomD.Initialize();
				LcomD.nActive = 1;
				LoadCaseNo = 0;
                for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
				for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
				if(m_nMCount>0) Set_MovingCase(arMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
				if(m_nEC4LVarTraffType == 1) // Moving Load
				{
					for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld) Set_MovingCase(arIgnorePsi1FactorMLoad[ld], dLFactor, LoadCaseNo, LcomD, TRUE);
				}
// MNET:XXXX-JHKIM-20080618, 김정인대리 요청
// 				for(ld=0; ld<m_nLCount;   ++ld) nLL  += Set_STLCIncludeCS(arLLoad[ld],   dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nIlCount;  ++ld) nIL  += Set_STLCIncludeCS(arIlLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nLsCount;  ++ld) nLS  += Set_STLCIncludeCS(arLsLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nLpCount;  ++ld) nLP  += Set_STLCIncludeCS(arLpLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nIlpCount; ++ld) nILP += Set_STLCIncludeCS(arIlpLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nCfCount;  ++ld) nCF  += Set_STLCIncludeCS(arCfLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nBrkCount; ++ld) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nBkCount;  ++ld) nBK  += Set_STLCIncludeCS(arBkLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 				for(ld=0; ld<m_nCrlCount; ++ld) nCRL += Set_STLCIncludeCS(arCrlLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                for(ld=0; ld<m_nPsCount;  ++ld) nPS  += Set_STLCIncludeCS(arPsLoad[ld],  dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
				double dWF = 1.0;
				if(m_nWCount>0)
				{
					dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
					nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
					for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
				}
				if(m_nSmCount > 0) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
										 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
							Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
// 						else if(CheckCSEL(nErection, _T("L")))
// 							Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
						else if(CheckCSEL(nErection, _T("W")))
							Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
				}

				// description
				LcomD.Description.Empty();
				csPrefix.Empty();
				strFixM.Format(_T("%d"), j+1);
				strFixW.Format(_T("%d"), j/2+1);
				strFixSm.Format(_T("%d"), nSmIndex+1);

				if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
				{
					LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
					csPrefix = _T("+");
				}
				if(m_nPsi1FactorMLoad2>0) {LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}
// 				if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
// 				{
// 					LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
// 					csPrefix = _T("+");
// 				}
				if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                if(m_nWCount > 0) 
                {
                    if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                    if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
                }

                if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
					
					CString strcEL;
					int nErection = 0;
				
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
						{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
// 						else if(CheckCSEL(nErection, _T("L")))
// 						{ LcomD.Description += csPrefix + GetFactorString(dLFactor) + strcEL; csPrefix = _T("+");}
						else if(CheckCSEL(nErection, _T("W")))
						{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
				}
				if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_STR);
			}
		}
	}}}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Wind2(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
		                         ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad, ArINT &arSLoad,
														 ArINT &arCSLoad, ArUNT &arIgnorePsi1FactorMLoad, BOOL bETC)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 || 
	              	m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
	
	double dDFactor = 1.35;
	double dPsFactor = 1.3;
	double dWFactor = (bETC) ? 0.6*1.5 : 1.5;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dSFactor = 0.8*1.5;
	double dLFactor = m_nEC4LVarTraffType == 0 ? 1.35 : 1.45 * 0.8;
	CString csPrefix(_T("")), strFixW(_T("")), strFixSm(_T("")), strFixM(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
		else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

		for(int p=0; p<nPsCount; ++p)
		{
            if(nPsCount==2) dPsFactor = (p==0) ? 1.3 : 1.0;
			else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

			for(int j=0; j<nWCount; ++j) {
			for(int k=0; k<nSmCount; ++k)
			{
				nSmIndex = k;
				if(m_nEC4Settlement==2)
				{
					dSmFactor = (k%2==0) ? 1.35 : 1.0;
					nSmIndex = k/2;
				}

				int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
				int nPS=0, nWL=0, nWLL=0, nSL=0;

				LcomD.Initialize();
				LcomD.nActive = 1;
				LoadCaseNo = 0;
                for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
				for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                for(ld=0; ld<m_nPsCount; ++ld) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
				double dWF = 1.0;
				if(m_nWCount>0)
				{
					dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
					nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
					for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
				}
				if(m_nSmCount > 0) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
				for(ld=0; ld<m_nSCount; ++ld) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0);
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
										 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
							Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
						else if(CheckCSEL(nErection, _T("W")))
							Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
				}

				if(m_nEC4LVarTraffType == 1) // Moving Load
				{
					for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld) Set_MovingCase(arIgnorePsi1FactorMLoad[ld], dLFactor, LoadCaseNo, LcomD, TRUE);
				}

				// description
				LcomD.Description.Empty();
				csPrefix.Empty();
				strFixM.Format(_T("%d"), j+1);
				strFixW.Format(_T("%d"), j/2+1);
				strFixSm.Format(_T("%d"), nSmIndex+1);

				if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
				{
					LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
					csPrefix = _T("+");
				}
				if(m_nPsi1FactorMLoad2>0) {LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}
				if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                if(m_nWCount > 0) 
                {
                    if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                    if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
                }

				if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
				if(nSL > 0) {LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+");}
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
					
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
						{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
						else if(CheckCSEL(nErection, _T("W")))
						{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
				}
				if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_STR);
			}
		}
	}}

	return TRUE;
}


BOOL CLoadCombCtrl::SetCvlEurocode4_Therm1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
														ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArUNT &arMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
														ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArUNT &arSmLoad,
                                                        ArINT &arTLoad, ArINT& arTpgLoad, ArINT &arCSLoad, ArUNT &arPsi1FactorMLoad1, ArUNT &arPsi1FactorMLoad2)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 ||
	              	m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

    int nMCount = max(m_nMCount, 1);
    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
	int nTCount = (m_nTCount>0) ? m_nTCount : 1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;

	double dDFactor = 1.35;
	double dLFactor = 1.35;
	double dPsFactor = 1.3;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dTFactor = 1.5;
    double dTUFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.35 : dTFactor;
    double dTGFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.75 : dTFactor;
	CString csPrefix(_T("")), strFixM(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) 
        {
            dDFactor = (d==0) ? 1.35 : 1.0;
            dLFactor = (d==0) ? 1.35 : 1.0;
        }
		else
        {
            dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;
            dLFactor = 1.0;
        }

        for ( int i=0; i<nMCount; ++i )
        {
            for ( int p=0; p<nPsCount; ++p )
            {
                if ( nPsCount==2 ) dPsFactor = (p==0) ? 1.3 : 1.0;
                else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

                for ( int k=0; k<nSmCount; ++k )
                {
                    for ( int l=0; l<nTCount; ++l )
                    {
                        for ( int j = 0; j<nTpgCount; ++j )
                        {
                            nSmIndex = k;
                            if ( m_nEC4Settlement==2 )
                            {
                                dSmFactor = (k%2==0) ? 1.35 : 1.0;
                                nSmIndex = k/2;
                            }

                            int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
                            int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
                            int nPS=0, nTL=0, nTpg = 0;

                            LcomD.Initialize();
                            LcomD.nActive = 1;
                            LoadCaseNo = 0;
                            for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                            for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                            for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                            for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                            for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                            for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                            for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                            if ( m_nMCount>0 ) Set_MovingCase(arMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);

                            for( ld=0; ld<m_nLCount; ++ld) nLL += Set_STLCIncludeCS(arLLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);

                            for ( ld=0; ld<m_nPsCount; ++ld ) nPS  += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, 6);
                            if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);

                            if ( m_nTCount > 0 ) nTL   += Set_STLCIncludeCS(arTLoad[l], dTUFactor, LoadCaseNo, LcomD, 0);
                            if ( m_nTpgCount > 0 ) nTpg  += Set_STLCIncludeCS(arTpgLoad[j], dTGFactor, LoadCaseNo, LcomD, 0);

                            if ( m_nConstLoad!=0 ) // ST+CS
                            {
                                if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                                CString strcEL;
                                int nErection = 0;

                                for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                    if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                        Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                    // 						else if(CheckCSEL(nErection, _T("L")))
                                    // 							Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
                                    else if ( CheckCSEL(nErection, _T("T")) )
                                        Set_CStageCase(arCSLoad[nnn], dTUFactor, LoadCaseNo, LcomD, TRUE);
                                    else if ( CheckCSEL(nErection, _T("TPG")) )
                                        Set_CStageCase(arCSLoad[nnn], dTGFactor, LoadCaseNo, LcomD, TRUE);
                                }
                                if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                    Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                            }

                            // description
                            LcomD.Description.Empty();
                            csPrefix.Empty();
                            strFixM.Format(_T("%d"), i+1);
                            strFixSm.Format(_T("%d"), nSmIndex+1);
                            strFixT.Format(_T("%d"), l+1);
                            strFixTpg.Format(_T("%d"), j+1);

                            if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                                csPrefix = _T("+");
                            }
                            if ( m_nMCount>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+"); }
                            // 				if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
                            // 				{
                            // 					LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
                            // 					csPrefix = _T("+");
                            // 				}
                            if ( nLL>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("LL"); csPrefix = _T("+"); }
                            if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                            if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                            if ( nTL> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTUFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                            if ( nTpg> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTGFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }

                            if ( m_nConstLoad!=0 ) // ST+CS
                            {
                                if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                                }

                                CString strcEL;
                                int nErection = 0;

                                for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                                {
                                    strcEL = _T(""); nErection = 0;
                                    if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                    if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                    {
                                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                                    }
                                    // 						else if(CheckCSEL(nErection, _T("L")))
                                    // 						{ LcomD.Description += csPrefix + GetFactorString(dLFactor) + strcEL; csPrefix = _T("+");}
                                    else if ( CheckCSEL(nErection, _T("T")))
                                    {
                                        LcomD.Description += csPrefix + GetFactorString(dTUFactor) + strcEL; csPrefix = _T("+");
                                    }
                                    else if ( CheckCSEL(nErection, _T("TPG")) )
                                    {
                                        LcomD.Description += csPrefix + GetFactorString(dTGFactor) + strcEL; csPrefix = _T("+");
                                    }
                                }
                                if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                                }
                                if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                                }
                                if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                                }
                            }
                            if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_STR);
                        }
                    }
                }
            }
        }
	}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Therm2(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
														ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArUNT &arSmLoad,
														ArINT &arTLoad, ArINT &arTpgLoad, ArINT &arSLoad, ArINT &arCSLoad)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 ||
	              	m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
	int nTCount = (m_nTCount>0) ? m_nTCount : 1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;

	double dDFactor = 1.35;
	double dPsFactor = 1.3;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dTFactor = 1.5;
	double dTUFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.35 : dTFactor;
	double dTGFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.75 : dTFactor;

	double dSFactor = 0.8*1.5;
	CString csPrefix(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
		else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

		for(int p=0; p<nPsCount; ++p)
		{
            if(nPsCount==2) dPsFactor = (p==0) ? 1.3 : 1.0;
			else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

            for ( int k=0; k<nSmCount; ++k )
            {
                for ( int l=0; l<nTCount; ++l )
                {
                    for ( int m=0; m<nTpgCount; ++m )
                    {
                        nSmIndex = k;
                        if ( m_nEC4Settlement==2 )
                        {
                            dSmFactor = (k%2==0) ? 1.35 : 1.0;
                            nSmIndex = k/2;
                        }

                        int nDL=0, nDC=0, nDW=0, nDD=0, nEP=0, nEH=0, nEV=0, nES=0, nEL=0, nCR=0, nSH=0;
                        int nPS=0, nTL=0, nSL=0, nTpg= 0;

                        LcomD.Initialize();
                        LcomD.nActive = 1;
                        LoadCaseNo = 0;
                        for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                        for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                        for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                        for ( ld=0; ld<m_nPsCount; ++ld ) nPS  += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                        if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
                        for ( ld=0; ld<m_nSCount; ++ld ) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0);

                        if ( m_nTCount >0 ) nTL  += Set_STLCIncludeCS(arTLoad[l], dTUFactor, LoadCaseNo, LcomD, 0);
                        if ( m_nTpgCount > 0 ) nTpg  += Set_STLCIncludeCS(arTpgLoad[m], dTGFactor, LoadCaseNo, LcomD, 0);

                        if ( m_nConstLoad!=0 ) // ST+CS
                        {
                            if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                            CString strcEL;
                            int nErection = 0;

                            for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                            {
                                strcEL = _T(""); nErection = 0;
                                if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                else if ( CheckCSEL(nErection, _T("T")) )
                                    Set_CStageCase(arCSLoad[nnn], dTUFactor, LoadCaseNo, LcomD, TRUE);
                                else if ( CheckCSEL(nErection, _T("TPG")) )
                                    Set_CStageCase(arCSLoad[nnn], dTGFactor, LoadCaseNo, LcomD, TRUE);
                            }
                            if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                        }

                        // description
                        LcomD.Description.Empty();
                        csPrefix.Empty();
                        strFixSm.Format(_T("%d"), nSmIndex+1);
                        strFixT.Format(_T("%d"), l+1);
                        strFixTpg.Format(_T("%d"), m+1);

                        if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                            csPrefix = _T("+");
                        }
                        if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                        if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                        if ( nTL> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTUFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                        if ( nTpg> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTGFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                        if ( nSL > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+"); }
                        if ( m_nConstLoad!=0 ) // ST+CS
                        {
                            if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                            }

                            CString strcEL;
                            int nErection = 0;

                            for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                            {
                                strcEL = _T(""); nErection = 0;
                                if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                                }
                                else if ( CheckCSEL(nErection, _T("T")) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dTUFactor) + strcEL; csPrefix = _T("+");
                                }
								else if ( CheckCSEL(nErection, _T("TPG")) )
								{
									LcomD.Description += csPrefix + GetFactorString(dTGFactor) + strcEL; csPrefix = _T("+");
								}
                            }
                            if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                            }
                            if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                            }
                            if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                            }
                        }
                        if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_STR);
                    }
                }
            }
		}
	}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Snow(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
													ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
													ArINT &arSLoad, ArINT &arCSLoad)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 ||
	              	m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
	
	double dDFactor = 1.35;
	double dPsFactor = 1.3;
	double dWFactor = 0.6*1.5;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dSFactor = 1.5;
	CString csPrefix(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
		else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

		for(int p=0; p<nPsCount; ++p)
		{
            if(nPsCount==2) dPsFactor = (p==0) ? 1.3 : 1.0;
			else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

			for(int j=0; j<nWCount; ++j) {
			for(int k=0; k<nSmCount; ++k)
			{
				nSmIndex = k;
				if(m_nEC4Settlement==2)
				{
					dSmFactor = (k%2==0) ? 1.35 : 1.0;
					nSmIndex = k/2;
				}

				int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
				int nPS=0, nWL=0, nWLL=0, nSL=0;

				LcomD.Initialize();
				LcomD.nActive = 1;
				LoadCaseNo = 0;
                for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
				for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
				for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                for(ld=0; ld<m_nPsCount; ++ld) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
				double dWF = 1.0;
				if(m_nWCount>0)
				{
					dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
					nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
					for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
				}
				if(m_nSmCount > 0) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
				for(ld=0; ld<m_nSCount; ++ld) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0);
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
					 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
							Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
						else if(CheckCSEL(nErection, _T("W")))
							Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
						Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
				}

				// description
				LcomD.Description.Empty();
				csPrefix.Empty();
				strFixW.Format(_T("%d"), j/2+1);
				strFixSm.Format(_T("%d"), nSmIndex+1);

				if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
				{
					LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
					csPrefix = _T("+");
				}
				if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
				if(m_nWCount > 0) 
				{
					if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
					if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
				}
				if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
				if(nSL > 0) {LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+");}
				if(m_nConstLoad!=0) // ST+CS
				{
					if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
					 
					CString strcEL;
					int nErection = 0;
					
					for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
					{
						strcEL = _T(""); nErection = 0;
						if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
					
						if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
						{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
						else if(CheckCSEL(nErection, _T("W")))
						{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
					}
					if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
					if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
					{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
				}
				if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_STR);
			}
		}
	}}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Erection(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
					                   ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArUNT &arSmLoad, ArINT &arTLoad, ArINT &arTpgLoad, ArINT &arErLoad, ArINT &arCSLoad)
{
	T_LCOM_D LcomD;

	int nDCount = 1;
	BOOL bExistD = (m_nDCount>0  || m_nDdCount>0 || m_nEpCount>0 ||
	              	m_nEsCount>0 || m_nElCount>0 || m_nCrCount>0 || m_nShCount>0|| m_nConstLoad > 0);
	if(bExistD && m_nEC4Permanent==2) nDCount = 2;

    int nPsCount = ((m_nPsCount>0 || m_nConstLoad > 0) && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = (m_nSmCount>0) ? ((m_nEC4Settlement==2) ? m_nSmCount*2 : m_nSmCount) : 1;
	int nSmIndex = 0;
    int nTCount = (m_nTCount>0) ? m_nTCount:1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;
	
	double dDFactor = 1.35;
	double dPsFactor = 1.3;
	double dERFactor = 1.5;
	double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.35;
	double dTFactor = 1.5;
	double dTUFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.35 : dTFactor;
	double dTGFactor = (m_nTCount > 0 && m_nTpgCount > 0) ? 0.75 : dTFactor;
	CString csPrefix(_T("")), strFixT(_T("")), strFixSm(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int d=0; d<nDCount; ++d)
	{
		if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
		else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

        for ( int p=0; p<nPsCount; ++p )
        {
            if ( nPsCount==2 ) dPsFactor = (p==0) ? 1.3 : 1.0;
            else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.3;

            for ( int k=0; k<nSmCount; ++k )
            {
                for ( int l=0; l<nTCount; ++l )
                {
                    for ( int m = 0; m<nTpgCount; ++m )
                    {
                        nSmIndex = k;
                        if ( m_nEC4Settlement==2 )
                        {
                            dSmFactor = (k%2==0) ? 1.35 : 1.0;
                            nSmIndex = k/2;
                        }

                        int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
                        int nPS=0, nTL=0, nER=0, nTpg=0;

                        LcomD.Initialize();
                        LcomD.nActive = 1;
                        LoadCaseNo = 0;
                        for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                        for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                        for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                        for ( ld=0; ld<m_nPsCount; ++ld ) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                        if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
                        if ( m_nTCount>0 ) nTL += Set_STLCIncludeCS(arTLoad[l], dTUFactor, LoadCaseNo, LcomD, 0);
                        if ( m_nTpgCount>0 ) nTpg += Set_STLCIncludeCS(arTpgLoad[m], dTGFactor, LoadCaseNo, LcomD, 0);
                        for ( ld=0; ld<m_nErCount; ++ld ) nER += Set_STLCIncludeCS(arErLoad[ld], dERFactor, LoadCaseNo, LcomD, 0);
                        if ( m_nConstLoad!=0 ) // ST+CS
                        {
                            if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                            CString strcEL;
                            int nErection = 0;

                            for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                            {
                                strcEL = _T(""); nErection = 0;
                                if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            }
                            if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                                Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                        }

                        // description
                        LcomD.Description.Empty();
                        csPrefix.Empty();
                        strFixSm.Format(_T("%d"), nSmIndex+1);
                        strFixT.Format(_T("%d"), l+1);
                        strFixTpg.Format(_T("%d"), m+1);

                        if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                            csPrefix = _T("+");
                        }
                        if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                        if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                        if ( nTL > 0 ) { LcomD.Description += csPrefix + GetFactorString(dTUFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                        if ( nTpg > 0 ) { LcomD.Description += csPrefix + GetFactorString(dTGFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                        if ( nER>0 ) { LcomD.Description += csPrefix + GetFactorString(dERFactor) + _T("ER"); csPrefix = _T("+"); }
                        if ( m_nConstLoad!=0 ) // ST+CS
                        {
                            if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                            }

                            CString strcEL;
                            int nErection = 0;

                            for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                            {
                                strcEL = _T(""); nErection = 0;
                                if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                                if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                {
                                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                                }
                            }
                            if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                            }
                            if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                            }
                            if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                            }
                        }
                        if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_STR);
                    }
                }
            }
        }
	}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Traffic_serv1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
																					ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
																					ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
														              ArINT &arCSLoad, ArUNT &arPsi1FactorMLoad1, ArUNT &arPsi1FactorMLoad2, int nLeadingType)
{
	T_LCOM_D LcomD;

    int nPsi1FactorMLoad2Size = arPsi1FactorMLoad2.GetSize();  // psi 고려 안한것(=arLeadingMLoad.GetSize())
    int nPsi1FactorMLoad1Size = arPsi1FactorMLoad1.GetSize();  // psi 고려 한것

	int nLeadingMCount = arLeadingMLoad.GetSize();
    int nMCount = max(nLeadingMCount, 1);
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = max(m_nSmCount,  1);
    int nBreakCount = (m_nBrkCount > 0 && m_nBkCount > 0) ? 2 : 1; // CIVIL-7875

	double dDFactor = 1.0;
	double dLFactor = 1.0;//(nLeadingType==0) ? 1.0 : 0.75;
	double dPsFactor = 1.0;
	double dWFactor = 0.6;
	double dSmFactor = 1.0;
    double dPsi1Factor = 0.8;
	CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int i=0; i<nMCount; ++i) {
	for(int j=0; j<nWCount; ++j) {
	for(int k=0; k<nSmCount; ++k){
    for ( int nBreak = 0; nBreak < nBreakCount; ++nBreak ) {
		int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
		int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
		int nPS=0, nWL=0, nWLL=0;

		LcomD.Initialize();
		LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
		LoadCaseNo = 0;
        for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
		for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
        for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
        // 김정인 과장님 요청 20090728 - jhyun
        if(m_nEC4LVarTraffType == 0)
        {
		  if(nLeadingMCount>0)
            {
                Set_MovingCase(arLeadingMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                for(ld=0; ld<m_nCfCount;  ++ld) nCF  += Set_STLCIncludeCS(arCfLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
                if ( nBreakCount > 1 )
                {
                    if ( nBreak == 0 ) { for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                    else if ( nBreak == 1 ) { for ( ld = 0; ld < m_nBkCount;  ++ld ) nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                    else ASSERT(0);
                }
                else
                {
                    for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                    for ( ld = 0; ld < m_nBkCount; ++ld )  nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                }
            }
        }
        else  // Rail Traffic
        {
            // Psi 고려안한 것 - Leading
            for(ld=0; ld<nPsi1FactorMLoad2Size;  ++ld)
            {
                if(arLeadingMLoad[i] == arPsi1FactorMLoad2[ld])
                { Set_MovingCase(arPsi1FactorMLoad2[ld], dLFactor, LoadCaseNo, LcomD, TRUE); }
            }

            // Psi 고려한 것
            // SetCvlEurocode4_Traffic_serv2에서 고려
        }

// MNET:XXXX-JHKIM-20080618, 김정인대리 요청
// 		for(ld=0; ld<m_nLCount;   ++ld) nLL  += Set_STLCIncludeCS(arLLoad[ld],   dLFactor, LoadCaseNo, LcomD, 0);
// 		for(ld=0; ld<m_nIlCount;  ++ld) nIL  += Set_STLCIncludeCS(arIlLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 		for(ld=0; ld<m_nLsCount;  ++ld) nLS  += Set_STLCIncludeCS(arLsLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 		for(ld=0; ld<m_nLpCount;  ++ld) nLP  += Set_STLCIncludeCS(arLpLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
// 		for(ld=0; ld<m_nIlpCount; ++ld) nILP += Set_STLCIncludeCS(arIlpLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
// 		for(ld=0; ld<m_nCrlCount; ++ld) nCRL += Set_STLCIncludeCS(arCrlLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nPsCount;  ++ld) nPS  += Set_STLCIncludeCS(arPsLoad[ld],  dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
		double dWF = 1.0;
		if(m_nWCount>0)
		{
			dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
			nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
			for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
		}
		if(m_nSmCount > 0) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
			 
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			
				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
					Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
// 				else if(CheckCSEL(nErection, _T("L")))
// 					Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
				else if(CheckCSEL(nErection, _T("W")))
					Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
		}

		// description
		LcomD.Description = _T("Ch: ");
		LcomD.nServLcomType = 3;

		csPrefix.Empty();
		strFixM.Format(_T("%d"), i+1);
		strFixW.Format(_T("%d"), j/2+1);
		strFixSm.Format(_T("%d"), k+1);

		if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
		{
			LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
			csPrefix = _T("+");
		}
		if(nLeadingMCount>0 || m_nPsi1FactorMLoad1>0 || m_nPsi1FactorMLoad2>0)  
        {
            LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");
        }
// 		if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
// 		{
// 			LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
// 			csPrefix = _T("+");
// 		}
		if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
		if(m_nWCount > 0) 
		{
			if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
			if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
		}
		if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
        if ( nBRK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BRK"); csPrefix = _T("+"); }
        if ( nBK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BK"); csPrefix = _T("+"); }
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
			
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
			
				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
				{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
// 				else if(CheckCSEL(nErection, _T("L")))
// 				{ LcomD.Description += csPrefix + GetFactorString(dLFactor) + strcEL; csPrefix = _T("+");}
				else if(CheckCSEL(nErection, _T("W")))
				{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");}
		}
		if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_SER);
	}}}}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Traffic_serv2(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
																					ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
																					ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArUNT &arSmLoad,
														              ArINT &arTLoad, ArINT &arTpgLoad, ArINT &arCSLoad, ArUNT &arPsi1FactorMLoad1, ArUNT &arPsi1FactorMLoad2, BOOL bFr, int nLeadingType)
{
	T_LCOM_D LcomD;

    int nPsi1FactorMLoad2Size = arPsi1FactorMLoad2.GetSize();  // psi 고려 안한것(=arLeadingMLoad.GetSize())
    int nPsi1FactorMLoad1Size = arPsi1FactorMLoad1.GetSize();  // psi 고려 한것

    int nLeadingMCount = 0;
    if(!bFr && m_nEC4LVarTraffType == 1) 
    {  nLeadingMCount = arPsi1FactorMLoad1.GetSize();}
    else 
    {  nLeadingMCount = arLeadingMLoad.GetSize(); }

    int nMCount = max(nLeadingMCount, 1);
	int nSmCount = max(m_nSmCount,  1);
    int nTCount = (m_nTCount>0) ? m_nTCount:1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;
    int nBreakCount = (m_nBrkCount > 0 && m_nBkCount > 0) ? 2 : 1; // CIVIL-7875

	double dDFactor = 1.0;
	double dLFactor = 1.0;//(nLeadingType==0) ? 1.0 : 0.75;
	double dPsFactor = 1.0;
	double dSmFactor = 1.0;
	double dTFactor = (bFr) ? 0.5 : 0.6;
    double dPsi1Factor = 0.8;
	CString csPrefix(_T("")), strFixM(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int i=0; i<nMCount; ++i) 
    {
        for ( int k=0; k<nSmCount; ++k )
        {
            for ( int l=0; l<nTCount; ++l )
            {
                for ( int m = 0; m<nTpgCount; ++m ){
                for ( int nBreak = 0; nBreak < nBreakCount; ++nBreak ) {
                    int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
                    int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
                    int nPS=0, nTL=0, nTpg = 0;;

                    LcomD.Initialize();
                    LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
                    LoadCaseNo = 0;
                    for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                    for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                    for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                    // 김정인 과장님 요청 20090728 - jhyun
                    if ( m_nEC4LVarTraffType == 0 )
                    {
                        if ( nLeadingMCount>0 )
                        {
                            Set_MovingCase(arLeadingMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                            
                            for ( ld=0; ld<m_nLCount; ++ld) nLL += Set_STLCIncludeCS(arLLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);

                            for ( ld=0; ld<m_nCfCount; ++ld ) nCF  += Set_STLCIncludeCS(arCfLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                            if ( nBreakCount > 1 )
                            {
                                if ( nBreak == 0 ) { for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                                else if ( nBreak == 1 ) { for ( ld = 0; ld < m_nBkCount;  ++ld ) nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0); }
                                else ASSERT(0);
                            }
                            else
                            {
                                for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                                for ( ld = 0; ld < m_nBkCount; ++ld )  nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                            }
                        }
                    }
                    else // Rail Traffic
                    {
                        if ( !bFr )
                        {
                            // psi 고려 안된것 - Leading
                            //SetCvlEurocode4_Traffic_serv1 에서 고려

                            // psi 고려 된것
                            if ( arPsi1FactorMLoad1.GetSize()>0 )
                            {
                                dLFactor = dPsi1Factor;
                                Set_MovingCase(arPsi1FactorMLoad1[i], dPsi1Factor, LoadCaseNo, LcomD, TRUE);
                            }
                        }
                    }
                    for ( ld=0; ld<m_nPsCount; ++ld ) nPS  += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                    if ( m_nTCount>0 ) nTL += Set_STLCIncludeCS(arTLoad[l], dTFactor, LoadCaseNo, LcomD, 0);
                    if ( m_nTpgCount>0 ) nTpg += Set_STLCIncludeCS(arTpgLoad[m], dTFactor, LoadCaseNo, LcomD, 0);
                    if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
                    if ( m_nConstLoad!=0 ) // ST+CS
                    {
                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                        CString strcEL;
                        int nErection = 0;

                        for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                        {
                            strcEL = _T(""); nErection = 0;
                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            else if ( CheckCSEL(nErection, _T("T")) )
                                Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                            else if ( CheckCSEL(nErection, _T("TPG")) )
                                Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                        }
                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                        // MQC:4539-JHYUN-20120316
                        if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                    }

                    // description
                    LcomD.Description = (bFr) ? _T("Fr: ") : _T("Ch: ");
                    LcomD.nServLcomType = (bFr) ? 2 : 3;

                    csPrefix.Empty();
                    strFixM.Format(_T("%d"), i+1);
                    strFixSm.Format(_T("%d"), k+1);
                    strFixT.Format(_T("%d"), l+1);
                    strFixTpg.Format(_T("%d"), m+1);

                    if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                        csPrefix = _T("+");
                    }
                    if ( nLeadingMCount>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+"); }
                    if ( nLL>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("LL"); csPrefix = _T("+"); }
                    if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                    if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                    if ( nBRK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BRK"); csPrefix = _T("+"); }
                    if ( nBK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BK"); csPrefix = _T("+"); }
                    if ( nTL> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                    if ( nTpg> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                    if ( m_nConstLoad!=0 ) // ST+CS
                    {
                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                        }

                        CString strcEL;
                        int nErection = 0;

                        for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                        {
                            strcEL = _T(""); nErection = 0;
                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                            }
                            else if ( CheckCSEL(nErection, _T("T"))  || CheckCSEL(nErection, _T("TPG")) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");
                            }
                        }
                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                        }
                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                        }
                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                        }
                        // MQC:4539-JHYUN-20120316
                        if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");
                        }
                    }
                    if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_SER);
                }}
            }
        }
	}

	return TRUE;
}	

BOOL CLoadCombCtrl::SetCvlEurocode4_Wind_serv1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
													 ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArUNT &arMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
													 ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
													 ArINT &arCSLoad, BOOL bFr)
{
	T_LCOM_D LcomD;

    int nMCount = (bFr) ? 1 : max(m_nMCount, 1);
	int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = max(m_nSmCount, 1);
	
	double dDFactor = 1.0;
	double dLFactor = 1.0;
	double dPsFactor = 1.0;
	double dWFactor = (bFr) ? 0.2 : 1.0;
	double dSmFactor = 1.0;
	CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
    for(int i=0; i<nMCount; ++i) {
	for(int j=0; j<nWCount; ++j) {
	for(int k=0; k<nSmCount; ++k)
	{
		int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
		int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
		int nPS=0, nWL=0, nWLL=0;

		LcomD.Initialize();
		LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
		LoadCaseNo = 0;
        for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
		for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
        for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
		if(!bFr && m_nMCount>0) Set_MovingCase(arMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
        for(ld=0; ld<m_nLCount; ++ld)  nLL += Set_STLCIncludeCS(arLLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nPsCount;  ++ld) nPS  += Set_STLCIncludeCS(arPsLoad[ld],  dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
		double dWF = 1.0;
		if(m_nWCount>0)
		{
			dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
			nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
			for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
		}
		if(m_nSmCount > 0) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
			 
			CString strcEL;
			int nErection = 0;
		
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }

				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
					Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
// 				else if(CheckCSEL(nErection, _T("L")))
// 					Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
				else if(CheckCSEL(nErection, _T("W")))
					Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
		}

		// description
		LcomD.Description = (bFr) ? _T("Fr: ") : _T("Ch: ");
		LcomD.nServLcomType = (bFr) ? 2 : 3;

		csPrefix.Empty();
		strFixM.Format(_T("%d"), i+1);
		strFixW.Format(_T("%d"), j/2+1);
		strFixSm.Format(_T("%d"), k+1);

		if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
		{
			LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
			csPrefix = _T("+");
		}
		if(!bFr && m_nMCount>0) {LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");}
// 		if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
// 		{
// 			LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
// 			csPrefix = _T("+");
// 		}
        if(nLL>0) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("LL"); csPrefix = _T("+"); }
		if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
        if(m_nWCount > 0) 
        {
            if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
        }

		if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}

			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 	

				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
				{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
// 				else if(CheckCSEL(nErection, _T("L")))
// 				{ LcomD.Description += csPrefix + GetFactorString(dLFactor) + strcEL; csPrefix = _T("+");}
				else if(CheckCSEL(nErection, _T("W")))
				{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");}
		}
		if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_SER);
	}}}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Wind_serv2(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
		                         ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad, ArINT &arSLoad,
														 ArINT &arCSLoad)
{
	T_LCOM_D LcomD;

	int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = max(m_nSmCount, 1);
	
	double dDFactor = 1.0;
	double dPsFactor = 1.0;
	double dWFactor = 1.0;
	double dSmFactor = 1.0;
	double dSFactor = 0.8;
	CString csPrefix(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int j=0; j<nWCount; ++j) {
	for(int k=0; k<nSmCount; ++k)
	{
		int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
		int nPS=0, nWL=0, nWLL=0, nSL=0;

		LcomD.Initialize();
		LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
		LoadCaseNo = 0;
        for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
		for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
        for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
        for(ld=0; ld<m_nPsCount; ++ld) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
		double dWF = 1.0;
		if(m_nWCount>0)
		{
			dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
			nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
			for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
		}
		if(m_nSmCount > 0) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
		for(ld=0; ld<m_nSCount; ++ld) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0);
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
			
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 	

				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
					Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
				else if(CheckCSEL(nErection, _T("W")))
					Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
		}

		// description
		LcomD.Description = _T("Ch: ");
		LcomD.nServLcomType = 3;

		csPrefix.Empty();
		strFixW.Format(_T("%d"), j/2+1);
		strFixSm.Format(_T("%d"), k+1);

		if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
		{
			LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
			csPrefix = _T("+");
		}
		if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
        if(m_nWCount > 0) 
        {
            if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
            if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
        }

        if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
		if(nSL > 0) {LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+");}
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
						 
			CString strcEL;
			int nErection = 0;
			
			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 	

				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
				{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
				else if(CheckCSEL(nErection, _T("W")))
				{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");}
		}
		if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_SER);
	}}

	return TRUE;
}


BOOL CLoadCombCtrl::SetCvlEurocode4_Therm_serv1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
														ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArUNT &arMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,
														ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArUNT &arSmLoad,
														ArINT &arTLoad, ArINT &arTpgLoad, ArINT &arCSLoad, BOOL bFr)
{
	T_LCOM_D LcomD;

    int nMCount = (bFr) ? 1 : max(m_nMCount, 1);
	int nSmCount = max(m_nSmCount, 1);
    int nTCount = (m_nTCount>0) ? m_nTCount:1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;
	
	double dDFactor = 1.0;
	double dLFactor = 1.0;
	double dPsFactor = 1.0;
	double dSmFactor = 1.0;
	double dTFactor = (bFr) ? 0.6 : 1.0;
	CString csPrefix(_T("")), strFixM(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int i=0; i<nMCount; ++i) 
    {
        for ( int k=0; k<nSmCount; ++k )
        {
            for ( int l=0; l<nTCount; ++l )
            {
                for ( int m = 0; m<nTpgCount; ++m )
                {
                    int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
                    int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
                    int nPS=0, nTL=0, nTpg = 0;

                    LcomD.Initialize();
                    LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
                    LoadCaseNo = 0;
                    for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                    for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                    for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                    if ( !bFr && m_nMCount>0 ) Set_MovingCase(arMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                    for(ld=0; ld<m_nLCount; ++ld) nLL += Set_STLCIncludeCS(arLLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                    for ( ld=0; ld<m_nPsCount; ++ld ) nPS  += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                    if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
                    if ( m_nTCount>0 ) nTL += Set_STLCIncludeCS(arTLoad[l], dTFactor, LoadCaseNo, LcomD, 0);
                    if ( m_nTpgCount>0 ) nTpg += Set_STLCIncludeCS(arTpgLoad[m], dTFactor, LoadCaseNo, LcomD, 0);

                    if ( m_nConstLoad!=0 ) // ST+CS
                    {
                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                        CString strcEL;
                        int nErection = 0;

                        for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                        {
                            strcEL = _T(""); nErection = 0;
                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                                Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                            // 				else if(CheckCSEL(nErection, _T("L")))
                            // 					Set_CStageCase(arCSLoad[nnn], dLFactor, LoadCaseNo, LcomD, TRUE);
                            else if ( CheckCSEL(nErection, _T("T")) )
                                Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                            else if ( CheckCSEL(nErection, _T("TPG")) )
                                Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                        }
                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                        // MQC:4539-JHYUN-20120316
                        if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                    }

                    // description
                    LcomD.Description = (bFr) ? _T("Fr: ") : _T("Ch: ");
                    LcomD.nServLcomType = (bFr) ? 2 : 3;

                    csPrefix.Empty();
                    strFixM.Format(_T("%d"), i+1);
                    strFixSm.Format(_T("%d"), k+1);
                    strFixT.Format(_T("%d"), l+1);
                    strFixTpg.Format(_T("%d"),m+1);

                    if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                        csPrefix = _T("+");
                    }
                    if ( !bFr && m_nMCount>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]"); csPrefix = _T("+"); }
                    // 		if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
                    // 		{
                    // 			LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
                    // 			csPrefix = _T("+");
                    // 		}
                    if ( nLL>0 ) { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("LL"); csPrefix = _T("+"); }
                    if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                    if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                    if ( nTL> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                    if ( nTpg> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                    if ( m_nConstLoad!=0 ) // ST+CS
                    {
                        if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                        }

                        CString strcEL;
                        int nErection = 0;

                        for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                        {
                            strcEL = _T(""); nErection = 0;
                            if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                            if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                            }
                            // 				else if(CheckCSEL(nErection, _T("L")))
                            // 				{ LcomD.Description += csPrefix + GetFactorString(dLFactor) + strcEL; csPrefix = _T("+");}
                            else if ( CheckCSEL(nErection, _T("T"))  || CheckCSEL(nErection, _T("TPG")) )
                            {
                                LcomD.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");
                            }
                        }
                        if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                        }
                        if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                        }
                        if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                        }
                        // MQC:4539-JHYUN-20120316
                        if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");
                        }
                    }
                    if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_SER);
                }
            }
        }
	}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Therm_serv2(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
														ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArUNT &arSmLoad,
														ArINT &arTLoad, ArINT &arTpgLoad, ArINT &arSLoad, ArINT &arCSLoad, BOOL bQP)
{
	T_LCOM_D LcomD;

	int nSmCount = max(m_nSmCount, 1);
    int nTCount = (m_nTCount>0) ? m_nTCount:1;
    int nTpgCount = (m_nTpgCount>0) ? m_nTpgCount:1;

	double dDFactor = 1.0;
	double dPsFactor = 1.0;
	double dSmFactor = 1.0;
	double dTFactor = (bQP) ? 0.5 : 1.0;
	double dSFactor = 0.8;
	CString csPrefix(_T("")), strFixSm(_T("")), strFixT(_T("")), strFixTpg(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int k=0; k<nSmCount; ++k) 
    {
        for ( int l=0; l<nTCount; ++l )
        {
            for ( int m = 0; m<nTpgCount; ++m )
            {
                int nDL=0, nDC=0, nDW=0, nDD=0, nEP=0, nEH=0, nEV=0, nES=0, nEL=0, nCR=0, nSH=0;
                int nPS=0, nTL=0, nSL=0, nTpg = 0;

                LcomD.Initialize();
                LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
                LoadCaseNo = 0;
                for ( ld=0; ld<m_nDCount; ++ld ) nDL += Set_STLCIncludeCS(arDLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                for ( ld=0; ld<m_nDdCount; ++ld ) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for ( ld=0; ld<m_nEpCount; ++ld ) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for ( ld=0; ld<m_nEsCount; ++ld ) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for ( ld=0; ld<m_nElCount; ++ld ) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
                for ( ld=0; ld<m_nCrCount; ++ld ) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
                for ( ld=0; ld<m_nShCount; ++ld ) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
                for ( ld=0; ld<m_nPsCount; ++ld ) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor, LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                if ( m_nSmCount > 0 ) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
                if ( m_nTCount>0 ) nTL += Set_STLCIncludeCS(arTLoad[l], dTFactor, LoadCaseNo, LcomD, 0);
                if ( m_nTpgCount>0 ) nTpg += Set_STLCIncludeCS(arTpgLoad[m], dTFactor, LoadCaseNo, LcomD, 0);

                if ( !bQP ) { for ( ld=0; ld<m_nSCount; ++ld ) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0); }
                if ( m_nConstLoad!=0 ) // ST+CS
                {
                    if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                        Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);

                    CString strcEL;
                    int nErection = 0;

                    for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                    {
                        strcEL = _T(""); nErection = 0;
                        if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                        if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                            Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                        else if ( CheckCSEL(nErection, _T("T")) )
                            Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                        else if ( CheckCSEL(nErection, _T("TPG")) )
                            Set_CStageCase(arCSLoad[nnn], dTFactor, LoadCaseNo, LcomD, TRUE);
                    }
                    if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                        Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                    if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                        Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                    if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                        Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                    // MQC:4539-JHYUN-20120316
                    if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                        Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                }

                // description
                LcomD.Description = (bQP) ? _T("QP: ") : _T("Ch: ");
                LcomD.nServLcomType = (bQP) ? 1 : 3;

                csPrefix.Empty();
                strFixSm.Format(_T("%d"), k+1);
                strFixT.Format(_T("%d"), l+1);
                strFixTpg.Format(_T("%d"), m+1);

                if ( nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0 )
                {
                    LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                    csPrefix = _T("+");
                }
                if ( nPS>0 ) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                if ( m_nSmCount > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+"); }
                if ( nTL> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("T[") + strFixT + _T("]"); csPrefix = _T("+"); }
                if ( nTpg> 0 ) { LcomD.Description += csPrefix + GetFactorString(dTFactor) + _T("TPG[") + strFixTpg + _T("]"); csPrefix = _T("+"); }
                if ( !bQP && nSL > 0 ) { LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+"); }
                if ( m_nConstLoad!=0 ) // ST+CS
                {
                    if ( CheckCS_SgldK(D_SGLD_DL_CVL, nnn) )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");
                    }

                    CString strcEL;
                    int nErection = 0;

                    for ( int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec )
                    {
                        strcEL = _T(""); nErection = 0;
                        if ( CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn) ) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }



                        if ( CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");
                        }
                        else if ( CheckCSEL(nErection, _T("T"))  || CheckCSEL(nErection, _T("TPG")) )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dTFactor) + strcEL; csPrefix = _T("+");
                        }
                    }
                    if ( CheckCS_SgldK(D_SGLD_CS_CVL, nnn) )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");
                    }
                    if ( CheckCS_SgldK(D_SGLD_SS_CVL, nnn) )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");
                    }
                    if ( CheckCS_SgldK(D_SGLD_TS_CVL, nnn) )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");
                    }
                    // MQC:4539-JHYUN-20120316
                    if ( CheckCS_SgldK(D_SGLD_TP_CVL, nnn) )
                    {
                        LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");
                    }
                }
                if ( LoadCaseNo > 0 ) Set_LoadComb4Civil(LcomD, D_SER);
            }
        }
	}

	return TRUE;
}

BOOL CLoadCombCtrl::SetCvlEurocode4_Snow_serv1(ArINT &arDLoad, ArINT &arDdLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,
																ArINT &arCrLoad, ArINT &arShLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
																ArINT &arSLoad, ArINT &arCSLoad)
{
    T_LCOM_D LcomD;

	int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
	int nSmCount = max(m_nSmCount, 1);
	
	double dDFactor = 1.0;
	double dPsFactor = 1.0;
	double dWFactor = 0.6;
	double dSmFactor = 1.0;
	double dSFactor = 1.0;
	CString csPrefix(_T("")), strFixW(_T("")), strFixSm(_T(""));
	
	int LoadCaseNo=0, ld=0, nnn=0;
	for(int j=0; j<nWCount; ++j) {
	for(int k=0; k<nSmCount; ++k)
	{
		int nDL=0, nDD=0, nEP=0, nES=0, nEL=0, nCR=0, nSH=0;
		int nPS=0, nWL=0, nWLL=0, nSL=0;

		LcomD.Initialize();
		LcomD.nActive = (m_nLcomType==D_LCOMTYPE_GENERAL) ? 1 : 2;
		LoadCaseNo = 0;
        for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
		for(ld=0; ld<m_nDdCount; ++ld) nDD += Set_STLCIncludeCS(arDdLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
		for(ld=0; ld<m_nElCount; ++ld) nEL += Set_STLCIncludeCS(arElLoad[ld], dDFactor, LoadCaseNo, LcomD, 0);
        for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_CS_CVL);
        for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, D_SGLD_SS_CVL);
		for(ld=0; ld<m_nPsCount; ++ld) nPS += Set_STLCIncludeCS(arPsLoad[ld], dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
		double dWF = 1.0;
		if(m_nWCount>0)
		{
			dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
			nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
			for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWFactor, LoadCaseNo, LcomD, 0);
		}
		if(m_nSmCount > 0) Set_SettleCase(arSmLoad[k], dSmFactor, LoadCaseNo, LcomD, TRUE);
		for(ld=0; ld<m_nSCount; ++ld) nSL += Set_STLCIncludeCS(arSLoad[ld], dSFactor, LoadCaseNo, LcomD, 0);
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);
			
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 	
			
				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
					Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
				else if(CheckCSEL(nErection, _T("W")))
					Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
				Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
		}

		// description
		LcomD.Description = _T("Ch: ");
		LcomD.nServLcomType = 3;

		csPrefix.Empty();
		strFixW.Format(_T("%d"), j/2+1);
		strFixSm.Format(_T("%d"), k+1);

		if(nDL>0 || nDD>0 || nEP>0 || nES>0 || nEL>0 || nCR>0 || nSH>0)
		{
			LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
			csPrefix = _T("+");
		}
		if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
		if(m_nWCount > 0) 
		{
			if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
			if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
		}
		if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
		if(nSL > 0) {LcomD.Description += csPrefix + GetFactorString(dSFactor) + _T("S");  csPrefix = _T("+");}
		if(m_nConstLoad!=0) // ST+CS
		{
			if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}
			
			CString strcEL;
			int nErection = 0;

			for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
			{
				strcEL = _T(""); nErection = 0;
				if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
				 
				 	
			
				if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) || CheckCSEL(nErection, _T("DW")))
				{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
				else if(CheckCSEL(nErection, _T("W")))
				{ LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
			}
			if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
			if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
			// MQC:4539-JHYUN-20120316
			if(CheckCS_SgldK(D_SGLD_TP_CVL, nnn))
			{ LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cTP)"); csPrefix = _T("+");}
		}
		if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_SER);
	}}

	return TRUE;
}

