														for(i=0; i<m_nSfCount; i++)  nSfL += Set_STLCIncludeCS(arSfLoad.GetAt(i),  darSfLoadFactor, LoadCaseNo, rData, 0);
														for(i=0; i<m_nBCount; i++)   nBL += Set_STLCIncludeCS(arBLoad.GetAt(i),  darBLoadFactor, LoadCaseNo, rData, 0);
