														if(m_nLcomType == D_LCOMTYPE_CONCRETE) rData.nActive = 2;  // Serviceability.  
														
														if(LoadCaseNo > 0)  Set_LoadComb4Civil(rData, D_SER);  //Set_LoadComb4Civil(rData, D_SER); for serviceability
