//IRC6 Modified load combinations
BOOL CLoadCombCtrl::SetCvlIRC6_Traffic(ArINT &arDLoad, ArINT &arDcLoad,ArINT &arDwLoad, ArINT &arEpLoad, ArINT &arEsLoad, ArINT &arElLoad,ArINT &arEvLoad,
                                                                             ArINT &arCrLoad, ArINT &arShLoad, ArUNT &arLeadingMLoad, ArINT &arLsLoad, ArINT &arLLoad, ArINT &arLpLoad, ArINT &arIlLoad,ArINT &arErLoad,
                                                                             ArINT &arIlpLoad, ArINT &arCfLoad, ArINT &arBrkLoad, ArINT &arBkLoad, ArINT &arCrlLoad, ArINT &arPsLoad, ArINT &arWLoad, ArINT &arWlLoad, ArUNT &arSmLoad,
                                                                             ArINT &arCSLoad,ArINT &arThermal,ArUNT &arMLoad, ArINT& arWprLoad,ArINT& arBLoad,ArINT& arWpLoad,ArUNT &arPsi1FactorMLoad1,ArUNT &arPsi1FactorMLoad2)
{
    T_LCOM_D LcomD;

    int nDCount = 1;
    BOOL bExistD = (m_nDCount>0  || m_nDwCount>0 || m_nEpCount>0 || m_nEsCount>0 ||
        m_nElCount>0 || m_nCrCount>0 || m_nShCount>0);
    if(bExistD && m_nEC4Permanent==2) nDCount = 2;
    int nMCount = max(m_nMCount, 1);
    int nPsCount = (m_nPsCount>0 && m_nEC4Prestress==2) ? 2 : 1;
    int nWCount = (m_nWCount>0) ? m_nWCount*2 : 1;
    int nSmCount =1;
    int nSmIndex = 0;
    BOOL bSPV = FALSE;

    double dDFactor = 1.35;
    double dDwFactor = 1.35;
    double dLFactor = 1.5;
    double dLsFactor = 1.2;
    double dBackfille = 1.5;
    double dEhFact = 1.5;
    double dErFact = 1.35;
    double dPsFactor = 1.0;
    double dWFactor = m_nIRC6_LSDLVarTraffType == 0 ? 0.9 : 0.9;
    double dPsi1Factor = 1.0;
    double dSmFactor = (m_nEC4Settlement==0) ? 1.0 : 1.0;
    double dTempFactor = 0.9;//Accompanying load
    CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));
    int nBreakCount = (m_nBrkCount > 0 && m_nBkCount > 0) ? 2 : 1; // CIVIL-7875

    int LoadCaseNo=0, ld=0, nnn=0;
    for(int d=0; d<nDCount; ++d)
    {
        if(nDCount==2) dDFactor = (d==0) ? 1.35 : 1.0;
        else           dDFactor = (m_nEC4Permanent==0) ? 1.0 : 1.35;

        if(nDCount==2) dDwFactor = (d==0) ? 1.75 : 1.0;
        else           dDwFactor = (m_nEC4Permanent==0) ? 1.0 : 1.75;

        if(nDCount==2) dEhFact = (d==0) ? 1.5 : 1.0;
        else           dEhFact = (m_nEC4Permanent==0) ? 1.0 : 1.5;

        for(int i=0; i<nMCount; ++i) {bSPV=FALSE; for(int nSPV=0;nSPV<m_aMvldSPVSel.GetSize();nSPV++) {if(arMLoad[i]==m_aMvldSPVSel[nSPV]) bSPV=TRUE;};if(bSPV==TRUE) continue;
            for(int p=0; p<nPsCount; ++p)
            {
                if(nPsCount==2) dPsFactor = (p==0) ? 1.0 : 1.0;
                else            dPsFactor = (m_nEC4Prestress==0) ? 1.0 : 1.0;

                for(int j=0; j<nWCount; ++j) {
                    for(int k=0; k<nSmCount; ++k){
                    for ( int nBreak = 0; nBreak < nBreakCount; ++nBreak ) {
                        nSmIndex = k;
                        if(m_nEC4Settlement==2)
                        {
                            dSmFactor = (k%2==0) ? 1.35 : 1.0;
                            nSmIndex = k/2;
                        }

                        int nDL=0, nDc=0, nSnow=0, nDw=0, nPL=0, nEP=0, nEV=0, nES=0, nEH=0;
                        int nLL=0, nIL=0, nLS=0, nLP=0, nILP=0, nCF=0, nBRK=0, nBK=0, nCRL=0;
                        int nPS=0, nWL=0, nWLL=0, nTL=0, nSL=0, nER=0 ;

                        LcomD.Initialize();
                        LcomD.nActive = 1;
                        LoadCaseNo = 0;

                        //Permanent
                        for(ld=0; ld<m_nDCount;  ++ld) nDL += Set_STLCIncludeCS(arDLoad[ld],  dDFactor, LoadCaseNo, LcomD, D_SGLD_DL_CVL);
                        for(ld=0; ld<m_nDwCount; ++ld) nDw += Set_STLCIncludeCS(arDwLoad[ld], dDwFactor, LoadCaseNo, LcomD, 0);
                     // for(ld=0; ld<m_nLsCount; ++ld) nLS += Set_STLCIncludeCS(arLsLoad[ld], dLsFactor, LoadCaseNo, LcomD, 0);
                        int nWPR =0,nGWP = 0;double dWpFactor = 1.0;
                        for(ld=0; ld<m_nWprCount; ++ld)  nWPR+= Set_STLCIncludeCS(arWprLoad[ld], dWpFactor,  LoadCaseNo, LcomD, 0);
                        //for(ld=0; ld<m_nWpCount; ++ld)  nGWP+= Set_STLCIncludeCS(arWpLoad[ld], dWpFactor,  LoadCaseNo, LcomD, 0);
                        int nB =0;double dBFactor = 0.15;
                        for(ld=0; ld<m_nBCount; ++ld)  nB+= Set_STLCIncludeCS(arBLoad[ld], dBFactor,  LoadCaseNo, LcomD, 0);

                        for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dEhFact, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], 1.5, LoadCaseNo, LcomD, 0);
                        //for(ld=0; ld<m_nTCount; ++ld) nTL += Set_STLCIncludeCS(arThermal[ld], dTempFactor, LoadCaseNo, LcomD, 0);
                        if(m_nMCount>0 && !bSPV) Set_MovingCase(arMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                        //for(ld=0; ld<m_nCrCount; ++ld) nCR += Set_STLCIncludeCS(arCrLoad[ld], dDFactor, LoadCaseNo, LcomD, 8);
                        //for(ld=0; ld<m_nShCount; ++ld) nSH += Set_STLCIncludeCS(arShLoad[ld], dDFactor, LoadCaseNo, LcomD, 10);
                        // 김정인 과장님 요청 20090728 - jhyun
                        if(m_nIRC6_LSDLVarTraffType == 0)
                        {
                            if(m_nLeadingMCount>0)
                            {
                                Set_MovingCase(arLeadingMLoad[i], dLFactor, LoadCaseNo, LcomD, TRUE);
                            }
                            for ( ld = 0; ld < m_nCfCount; ++ld ) nCF += Set_STLCIncludeCS(arCfLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                            if ( nBreakCount > 1 )
                            {
                                if ( nBreak == 0 ) { if ( !bSPV ) for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad.GetAt(i), dLsFactor, LoadCaseNo, LcomD, 0); }
                                else if ( nBreak == 1 ) { for ( ld = 0; ld < m_nBkCount; ++ld )  nBK += Set_STLCIncludeCS(arBkLoad.GetAt(i), dLFactor, LoadCaseNo, LcomD, 0); }
                            }
                            else
                            {
                                if ( !bSPV ) { for ( ld = 0; ld < m_nBrkCount; ++ld ) nBRK += Set_STLCIncludeCS(arBrkLoad[ld], dLsFactor, LoadCaseNo, LcomD, 0); }
                                for ( ld = 0; ld < m_nBkCount; ++ld ) nBK += Set_STLCIncludeCS(arBkLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
                            }
                        }
                        else
                        {
                            //for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld) Set_MovingCase(arPsi1FactorMLoad2[ld], dLFactor, LoadCaseNo, LcomD, TRUE);
                            for(ld=0; ld<m_nPsi1FactorMLoad2;  ++ld)
                            {
                                if(arLeadingMLoad[i] == arPsi1FactorMLoad2[ld])
                                { Set_MovingCase(arPsi1FactorMLoad2[ld], dLFactor, LoadCaseNo, LcomD, TRUE); }
                            }
                        }

                        //Variable
                        // MNET:XXXX-JHKIM-20080618, 김정인대리 요청
                        for(ld=0; ld<m_nLCount;   ++ld) nLL  += Set_STLCIncludeCS(arLLoad[ld],   dLFactor, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nLsCount;  ++ld) nLS  += Set_STLCIncludeCS(arLsLoad[ld], dLsFactor, LoadCaseNo, LcomD, 0);

                        
                                        
                         // 				for(ld=0; ld<m_nIlCount;  ++ld) nIL  += Set_STLCIncludeCS(arIlLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
                        	 // 				for(ld=0; ld<m_nLpCount;  ++ld) nLP  += Set_STLCIncludeCS(arLpLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nErCount; ++ld) nER += Set_STLCIncludeCS(arErLoad[ld], dErFact, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nCrlCount; ++ld) nCRL += Set_STLCIncludeCS(arCrlLoad[ld], dPsFactor, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nPsCount;  ++ld) nPS  += Set_STLCIncludeCS(arPsLoad[ld],  dPsFactor,LoadCaseNo, LcomD, D_SGLD_TS_CVL);
                        double dWF = 1.0;
                        if(m_nWCount>0 && !bSPV)
                        {
                            dWF = (j%2==0) ? dWFactor : -1. * dWFactor;
                            nWL += Set_STLCIncludeCS(arWLoad[j/2], dWF, LoadCaseNo, LcomD, 0);
                            for(ld=0; ld<m_nWlCount; ++ld) nWLL+= Set_STLCIncludeCS(arWlLoad[ld], dWF, LoadCaseNo, LcomD, 0);
                        }
                        //if(m_nSmCount > 0) Set_SettleCase(arSmLoad[nSmIndex], dSmFactor, LoadCaseNo, LcomD, TRUE);
                        if(m_nConstLoad!=0) // ST+CS
                        {
                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
                                Set_CStageCase(arCSLoad[nnn],  dDFactor,  LoadCaseNo, LcomD, TRUE);

                            CString strcEL;
                            int nErection = 0;

                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                            {
                                strcEL = _T(""); nErection = 0;
                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
                                                                 	

                                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) )
                                    Set_CStageCase(arCSLoad[nnn], dDFactor, LoadCaseNo, LcomD, TRUE);
                                else if(CheckCSEL(nErection, _T("DW")))
                                    Set_CStageCase(arCSLoad[nnn], dDwFactor, LoadCaseNo, LcomD, TRUE);
                                else if(CheckCSEL(nErection, _T("W")))
                                    Set_CStageCase(arCSLoad[nnn], dWFactor, LoadCaseNo, LcomD, TRUE);
                            }
                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
                                Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
                                Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
                                Set_CStageCase(arCSLoad[nnn], dPsFactor, LoadCaseNo, LcomD, TRUE);
                        }

                        // description
                        LcomD.Description.Empty();
                        csPrefix.Empty();
                        strFixM.Format(_T("%d"), i+1);
                        strFixW.Format(_T("%d"), j/2+1);
                        strFixSm.Format(_T("%d"), nSmIndex+1);
                        LcomD.Description += _T("TrW:");
                        if(nDL>0 || nDc>0 || nEP>0 || nES>0 || nEV>0 )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("Permanent");
                            csPrefix = _T("+");
                        }
                        if(nDw>0  )
                        {
                            LcomD.Description += csPrefix + GetFactorString(dDwFactor) + _T("DW");
                            csPrefix = _T("+");
                        }
                        if(m_nMCount>0 ) 
                        {
                            LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("M[") + strFixM + _T("]");csPrefix = _T("+");
                        }
                        // 				if(nLS>0 || nLL>0 || nLP>0 || nIL>0 || nILP>0 || nCF>0 || nBRK>0 || nBK>0 || nCRL>0)
                        // 				{
                        // 					LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("Traffic");
                        // 					csPrefix = _T("+");
                        // 				}
                        if(nPS>0) { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("PS"); csPrefix = _T("+"); }
                        if(m_nWCount > 0) 
                        {
                            if(nWL  > 0) {if(dWF<0.) csPrefix=_T(""); LcomD.Description += csPrefix + GetFactorString(dWF) + _T("W[") + strFixW + _T("]"); csPrefix = _T("+");}
                            if(nWLL > 0) {LcomD.Description += csPrefix + GetFactorString(dWFactor) + _T("WL"); csPrefix = _T("+");}
                        }
                        if(m_nSmCount > 0) {LcomD.Description += csPrefix + GetFactorString(dSmFactor) + _T("SM[") + strFixSm + _T("]"); csPrefix = _T("+");}
                        if ( nBRK > 0 ) { LcomD.Description += csPrefix + GetFactorString(dLsFactor) + _T("BRK"); csPrefix = _T("+"); }
                        if ( nBK > 0 )  { LcomD.Description += csPrefix + GetFactorString(dLFactor) + _T("BK");  csPrefix = _T("+"); }

                        if(m_nConstLoad!=0) // ST+CS
                        {
                            if(CheckCS_SgldK(D_SGLD_DL_CVL, nnn))
                            { LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cD)"); csPrefix = _T("+");}

                            CString strcEL;
                            int nErection = 0;

                            for(int nErec=0; nErec<D_STCT_EREC_MAX_CVL; ++nErec)
                            {
                                strcEL = _T(""); nErection = 0;
                                if(CheckCS_SgldK(m_CSEL_SgldK[nErec], nnn)) { strcEL = m_CSEL_Sgld_Desc[nErec]; nErection = m_CSEL_SgldK[nErec]; }
  
                                if(CheckCSEL(nErection, _T("D")) || CheckCSEL(nErection, _T("DC")) )
                                { LcomD.Description += csPrefix + GetFactorString(dDFactor) + strcEL; csPrefix = _T("+");}
                                else if(CheckCSEL(nErection, _T("DW")))
                                { LcomD.Description += csPrefix + GetFactorString(dDwFactor) + strcEL; csPrefix = _T("+");}
                                else if(CheckCSEL(nErection, _T("W")))
                                { LcomD.Description += csPrefix + GetFactorString(dWFactor) + strcEL; csPrefix = _T("+"); }
                            }
                            if(CheckCS_SgldK(D_SGLD_CS_CVL, nnn))
                            { LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cCR)"); csPrefix = _T("+");}
                            if(CheckCS_SgldK(D_SGLD_SS_CVL, nnn))
                            { LcomD.Description += csPrefix + GetFactorString(dDFactor) + _T("(cSH)"); csPrefix = _T("+");}
                            if(CheckCS_SgldK(D_SGLD_TS_CVL, nnn))
                            { LcomD.Description += csPrefix + GetFactorString(dPsFactor) + _T("(cPS)"); csPrefix = _T("+");}
                        }
                        if(LoadCaseNo > 0) Set_LoadComb4Civil(LcomD, D_STR);
                    }
                }
            }}}}

    return TRUE;
}

