												 for(ld=0; ld<m_nEpCount; ++ld) nEP += Set_STLCIncludeCS(arEpLoad[ld], dPsi1Factor, LoadCaseNo, LcomD, 0);
												 for(ld=0; ld<m_nEsCount; ++ld) nES += Set_STLCIncludeCS(arEsLoad[ld], dPsi1Factor, LoadCaseNo, LcomD, 0);
												 double dRS_X = (m%2==0) ?  -1. * dRsFactor : dRsFactor ;
												 double dRS_Y = (n%2==0) ?  -1. * dRsFactor : dRsFactor ;
												 double dRS_Z = (o%2==0) ?  -1. * dRsFactor : dRsFactor ;
