    //int nELoad_x = arELoad_x.GetSize();
    //int nELoad_y = arELoad_y.GetSize();
    //int nELoad_z = arELoad_z.GetSize();
    //int nTtlELoad = nELoad_x + nELoad_y + nELoad_z;

    int nDCount = 1;
