    int nWCount = 1;
    int nSmCount = 1;
    int nSmIndex = 0;
    int nESPCount_X = (nEsp_x > 0) ? nEsp_x * 2 : 1;
    int nESPCount_Y = (nEsp_y > 0) ? nEsp_y * 2 : 1;
    int nESPCount_Z = (nEsp_z > 0) ? nEsp_z * 2 : 1;
  /*  int nELoadCount_X = (nELoad_x > 0) ? nELoad_x * 2 : 1;
    int nELoadCount_Y = (nELoad_y > 0) ? nELoad_y * 2 : 1;
    int nELoadCount_Z = (nELoad_z > 0) ? nELoad_z * 2 : 1;*/
    BOOL bSPV = FALSE;
    double dDFactor = 1.35;
    double dDwFactor = 1.35;
    double dLFactor = 1.5;
    double dLsFactor = 0.2;
    double dBackfille = 1.5;
    double dEhFact = 1.5;
    double dErFact = 1.35;
    double dPsFactor = 1.0;
    double dRsFactor = 1.5;
    double dWFactor = m_nIRC6_LSDLVarTraffType == 0 ? 0.9 : 0.9;
    double dPsi1Factor = 1.0;
    double dSmFactor = (m_nEC4Settlement == 0) ? 1.0 : 1.0;
    double dTempFactor = 0.5;//Accompanying load
    CString csPrefix(_T("")), strFixM(_T("")), strFixW(_T("")), strFixSm(_T(""));

    int LoadCaseNo = 0, ld = 0, nnn = 0;
