                        //Variable
                        // MNET:XXXX-JHKIM-20080618, 김정인대리 요청
                        


                        // 				for(ld=0; ld<m_nIlCount;  ++ld) nIL  += Set_STLCIncludeCS(arIlLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
                        // 				for(ld=0; ld<m_nLpCount;  ++ld) nLP  += Set_STLCIncludeCS(arLpLoad[ld],  dLFactor, LoadCaseNo, LcomD, 0);
                        for(ld=0; ld<m_nErCount; ++ld) nER += Set_STLCIncludeCS(arErLoad[ld], dErFact, LoadCaseNo, LcomD, 0);
                        //for(ld=0; ld<m_nCrlCount; ++ld) nCRL += Set_STLCIncludeCS(arCrlLoad[ld], dLFactor, LoadCaseNo, LcomD, 0);
